import http.server, sys, os, mimetypes, time
ROOT = "/tmp/t/www"
class H(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    def log_message(self, *a): pass
    def send(self, code, body, ctype=None, extra=None):
        self.send_response(code)
        if ctype: self.send_header("Content-Type", ctype)
        for k,v in (extra or []): self.send_header(k, v)
        self.send_header("Content-Length", str(len(body))); self.end_headers(); self.wfile.write(body)
    def do_GET(self):
        sys.stderr.write("REQ %s %s\n" % (self.command, self.path))
        for k,v in self.headers.items(): sys.stderr.write("  %s: %s\n" % (k,v))
        sys.stderr.flush()
        p = self.path.split("?")[0]
        if p.startswith("/redir/"):
            self.send(302, b"", None, [("Location", "/" + p[len("/redir/"):])]); return
        if p.startswith("/status/"):
            code = int(p.split("/")[2]); self.send(code, b"body of %d" % code, "text/html"); return
        if p.startswith("/slow/"):
            time.sleep(int(p.split("/")[2])); self.send(200, b"<p>slow</p>", "text/html"); return
        if p.startswith("/noct/"):
            fp = os.path.join(ROOT, p[len("/noct/"):])
            self.send(200, open(fp,"rb").read(), None); return
        if p.startswith("/ct/"):
            # /ct/<ctype-with-_-for-slash>/<file>
            parts = p.split("/", 3)
            ct = parts[2].replace("_", "/").replace("|", ";").replace("~", " ")
            fp = os.path.join(ROOT, parts[3])
            self.send(200, open(fp,"rb").read(), ct); return
        if p.startswith("/setcookie/"):
            self.send(200, b"<p>cookie</p>", "text/html", [("Set-Cookie", "a=b; Path=/")]); return
        fp = os.path.join(ROOT, p.lstrip("/"))
        if os.path.isdir(fp): fp = os.path.join(fp, "index.html")
        if os.path.isfile(fp):
            ct = mimetypes.guess_type(fp)[0]
            self.send(200, open(fp,"rb").read(), ct)
        else:
            self.send(404, b"nf", "text/html")
http.server.HTTPServer(("127.0.0.1", 8765), H).serve_forever()
EOF
