//! Simple arena-based DOM used by the HTML parser, processor and serializer.

pub type NodeId = usize;

pub const NS_HTML: &str = "http://www.w3.org/1999/xhtml";
pub const NS_SVG: &str = "http://www.w3.org/2000/svg";
pub const NS_MATHML: &str = "http://www.w3.org/1998/Math/MathML";
pub const NS_XLINK: &str = "http://www.w3.org/1999/xlink";
pub const NS_XML: &str = "http://www.w3.org/XML/1998/namespace";
pub const NS_XMLNS: &str = "http://www.w3.org/2000/xmlns/";

#[derive(Clone, Debug)]
pub struct Attr {
    pub ns: String,
    pub prefix: Option<String>,
    pub local: String,
    pub value: String,
}

#[derive(Clone, Debug)]
pub enum NodeData {
    Document,
    Doctype {
        name: String,
        public_id: String,
        system_id: String,
    },
    Text(String),
    Comment(String),
    Element {
        ns: String,
        local: String,
        attrs: Vec<Attr>,
        /// Document fragment node holding template contents (for <template>).
        template_contents: Option<NodeId>,
    },
}

#[derive(Clone, Debug)]
pub struct Node {
    pub parent: Option<NodeId>,
    pub children: Vec<NodeId>,
    pub data: NodeData,
}

#[derive(Clone, Debug)]
pub struct Dom {
    pub nodes: Vec<Node>,
    pub document: NodeId,
    pub quirks_mode: QuirksMode,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum QuirksMode {
    NoQuirks,
    LimitedQuirks,
    Quirks,
}

impl Dom {
    pub fn new() -> Dom {
        let mut dom = Dom {
            nodes: Vec::new(),
            document: 0,
            quirks_mode: QuirksMode::NoQuirks,
        };
        dom.document = dom.new_node(NodeData::Document);
        dom
    }

    pub fn new_node(&mut self, data: NodeData) -> NodeId {
        self.nodes.push(Node {
            parent: None,
            children: Vec::new(),
            data,
        });
        self.nodes.len() - 1
    }

    pub fn new_element(&mut self, ns: &str, local: &str, attrs: Vec<Attr>) -> NodeId {
        self.new_node(NodeData::Element {
            ns: ns.to_string(),
            local: local.to_string(),
            attrs,
            template_contents: None,
        })
    }

    pub fn new_text(&mut self, text: &str) -> NodeId {
        self.new_node(NodeData::Text(text.to_string()))
    }

    pub fn new_comment(&mut self, text: &str) -> NodeId {
        self.new_node(NodeData::Comment(text.to_string()))
    }

    pub fn node(&self, id: NodeId) -> &Node {
        &self.nodes[id]
    }

    pub fn node_mut(&mut self, id: NodeId) -> &mut Node {
        &mut self.nodes[id]
    }

    pub fn parent(&self, id: NodeId) -> Option<NodeId> {
        self.nodes[id].parent
    }

    pub fn children(&self, id: NodeId) -> Vec<NodeId> {
        self.nodes[id].children.clone()
    }

    pub fn is_element(&self, id: NodeId) -> bool {
        matches!(self.nodes[id].data, NodeData::Element { .. })
    }

    pub fn element_name(&self, id: NodeId) -> Option<(&str, &str)> {
        match &self.nodes[id].data {
            NodeData::Element { ns, local, .. } => Some((ns.as_str(), local.as_str())),
            _ => None,
        }
    }

    pub fn local_name(&self, id: NodeId) -> Option<&str> {
        match &self.nodes[id].data {
            NodeData::Element { local, .. } => Some(local.as_str()),
            _ => None,
        }
    }

    pub fn is_html_element(&self, id: NodeId, name: &str) -> bool {
        match &self.nodes[id].data {
            NodeData::Element { ns, local, .. } => ns == NS_HTML && local == name,
            _ => false,
        }
    }

    pub fn is_named(&self, id: NodeId, name: &str) -> bool {
        match &self.nodes[id].data {
            NodeData::Element { local, .. } => local == name,
            _ => false,
        }
    }

    pub fn attrs(&self, id: NodeId) -> &[Attr] {
        match &self.nodes[id].data {
            NodeData::Element { attrs, .. } => attrs,
            _ => &[],
        }
    }

    pub fn attrs_mut(&mut self, id: NodeId) -> Option<&mut Vec<Attr>> {
        match &mut self.nodes[id].data {
            NodeData::Element { attrs, .. } => Some(attrs),
            _ => None,
        }
    }

    /// Get attribute value by local name (ignores namespace/prefix).
    pub fn get_attr(&self, id: NodeId, name: &str) -> Option<String> {
        self.attrs(id)
            .iter()
            .find(|a| a.local == name)
            .map(|a| a.value.clone())
    }

    pub fn has_attr(&self, id: NodeId, name: &str) -> bool {
        self.attrs(id).iter().any(|a| a.local == name)
    }

    /// Set attribute by local name. If value is None, removes all matching attributes.
    /// If the attribute doesn't exist, appends it.
    pub fn set_attr(&mut self, id: NodeId, name: &str, value: Option<&str>) {
        if let Some(attrs) = self.attrs_mut(id) {
            match value {
                Some(v) => {
                    let mut found = false;
                    for a in attrs.iter_mut() {
                        if a.local == name {
                            a.value = v.to_string();
                            found = true;
                        }
                    }
                    if !found {
                        attrs.push(Attr {
                            ns: String::new(),
                            prefix: None,
                            local: name.to_string(),
                            value: v.to_string(),
                        });
                    }
                }
                None => {
                    attrs.retain(|a| a.local != name);
                }
            }
        }
    }

    pub fn remove_attr(&mut self, id: NodeId, name: &str) {
        self.set_attr(id, name, None);
    }

    pub fn append(&mut self, parent: NodeId, child: NodeId) {
        self.detach(child);
        self.nodes[child].parent = Some(parent);
        self.nodes[parent].children.push(child);
    }

    pub fn insert_before(&mut self, parent: NodeId, child: NodeId, reference: Option<NodeId>) {
        self.detach(child);
        self.nodes[child].parent = Some(parent);
        match reference {
            Some(r) => {
                let pos = self.nodes[parent]
                    .children
                    .iter()
                    .position(|&c| c == r)
                    .unwrap_or(self.nodes[parent].children.len());
                self.nodes[parent].children.insert(pos, child);
            }
            None => self.nodes[parent].children.push(child),
        }
    }

    pub fn insert_at(&mut self, parent: NodeId, index: usize, child: NodeId) {
        self.detach(child);
        self.nodes[child].parent = Some(parent);
        let len = self.nodes[parent].children.len();
        let idx = if index > len { len } else { index };
        self.nodes[parent].children.insert(idx, child);
    }

    pub fn detach(&mut self, child: NodeId) {
        if let Some(p) = self.nodes[child].parent {
            self.nodes[p].children.retain(|&c| c != child);
            self.nodes[child].parent = None;
        }
    }

    /// Append text, merging with the previous text node if present (like html5ever RcDom).
    pub fn append_text(&mut self, parent: NodeId, text: &str) {
        if let Some(&last) = self.nodes[parent].children.last() {
            if let NodeData::Text(s) = &mut self.nodes[last].data {
                s.push_str(text);
                return;
            }
        }
        let t = self.new_text(text);
        self.append(parent, t);
    }

    /// Insert text before a reference node, merging with the previous sibling text node if present.
    pub fn insert_text_before(&mut self, parent: NodeId, reference: NodeId, text: &str) {
        let pos = self.nodes[parent]
            .children
            .iter()
            .position(|&c| c == reference)
            .unwrap_or(0);
        if pos > 0 {
            let prev = self.nodes[parent].children[pos - 1];
            if let NodeData::Text(s) = &mut self.nodes[prev].data {
                s.push_str(text);
                return;
            }
        }
        let t = self.new_text(text);
        self.insert_at(parent, pos, t);
    }

    pub fn text_content(&self, id: NodeId) -> String {
        let mut out = String::new();
        self.collect_text(id, &mut out);
        out
    }

    fn collect_text(&self, id: NodeId, out: &mut String) {
        match &self.nodes[id].data {
            NodeData::Text(t) => out.push_str(t),
            _ => {
                for &c in &self.nodes[id].children {
                    self.collect_text(c, out);
                }
            }
        }
    }

    /// Find first child element with the given local name.
    pub fn find_child_element(&self, parent: NodeId, name: &str) -> Option<NodeId> {
        self.nodes[parent]
            .children
            .iter()
            .copied()
            .find(|&c| self.is_named(c, name))
    }

    /// Deep-clone a subtree from another DOM into this one. Returns new node id (not attached).
    pub fn import_subtree(&mut self, other: &Dom, id: NodeId) -> NodeId {
        let data = match &other.nodes[id].data {
            NodeData::Element {
                ns,
                local,
                attrs,
                template_contents: _,
            } => NodeData::Element {
                ns: ns.clone(),
                local: local.clone(),
                attrs: attrs.clone(),
                template_contents: None,
            },
            d => d.clone(),
        };
        let new_id = self.new_node(data);
        for &c in &other.nodes[id].children {
            let nc = self.import_subtree(other, c);
            self.nodes[nc].parent = Some(new_id);
            self.nodes[new_id].children.push(nc);
        }
        new_id
    }

    pub fn html_element(&self) -> Option<NodeId> {
        self.nodes[self.document]
            .children
            .iter()
            .copied()
            .find(|&c| self.is_named(c, "html"))
    }

    pub fn head_element(&self) -> Option<NodeId> {
        self.html_element()
            .and_then(|h| self.find_child_element(h, "head"))
    }

    pub fn body_element(&self) -> Option<NodeId> {
        self.html_element()
            .and_then(|h| self.find_child_element(h, "body"))
    }
}
EOF
