use super::dom::*;

fn is_void(ns: &str, local: &str) -> bool {
    ns == NS_HTML
        && matches!(
            local,
            "area"
                | "base"
                | "basefont"
                | "bgsound"
                | "br"
                | "col"
                | "embed"
                | "frame"
                | "hr"
                | "img"
                | "input"
                | "keygen"
                | "link"
                | "meta"
                | "param"
                | "source"
                | "track"
                | "wbr"
        )
}

fn write_escaped(out: &mut String, text: &str, attr_mode: bool) {
    for c in text.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '\u{a0}' => out.push_str("&nbsp;"),
            '"' if attr_mode => out.push_str("&quot;"),
            '<' if !attr_mode => out.push_str("&lt;"),
            '>' if !attr_mode => out.push_str("&gt;"),
            c => out.push(c),
        }
    }
}

struct ElemInfo {
    html_name: Option<String>,
    ignore_children: bool,
}

pub struct Serializer {
    out: String,
    stack: Vec<ElemInfo>,
    scripting_enabled: bool,
}

impl Serializer {
    fn parent(&self) -> &ElemInfo {
        self.stack.last().expect("no parent ElemInfo")
    }

    fn start_elem(&mut self, ns: &str, local: &str, attrs: &[Attr]) {
        let html_name = if ns == NS_HTML {
            Some(local.to_string())
        } else {
            None
        };
        if self.parent().ignore_children {
            self.stack.push(ElemInfo {
                html_name,
                ignore_children: true,
            });
            return;
        }
        self.out.push('<');
        self.out.push_str(local);
        for a in attrs {
            self.out.push(' ');
            match a.ns.as_str() {
                "" => {}
                NS_XML => self.out.push_str("xml:"),
                NS_XMLNS => {
                    if a.local != "xmlns" {
                        self.out.push_str("xmlns:");
                    }
                }
                NS_XLINK => self.out.push_str("xlink:"),
                _ => self.out.push_str("unknown_namespace:"),
            }
            self.out.push_str(&a.local);
            self.out.push_str("=\"");
            write_escaped(&mut self.out, &a.value, true);
            self.out.push('"');
        }
        self.out.push('>');
        let ignore_children = is_void(ns, local);
        self.stack.push(ElemInfo {
            html_name,
            ignore_children,
        });
    }

    fn end_elem(&mut self, local: &str) {
        let info = self.stack.pop().expect("no ElemInfo");
        if info.ignore_children {
            return;
        }
        self.out.push_str("</");
        self.out.push_str(local);
        self.out.push('>');
    }

    fn write_text(&mut self, text: &str) {
        let escape = match self.parent().html_name.as_deref() {
            Some("style") | Some("script") | Some("xmp") | Some("iframe") | Some("noembed")
            | Some("noframes") | Some("plaintext") => false,
            Some("noscript") => !self.scripting_enabled,
            _ => true,
        };
        if escape {
            write_escaped(&mut self.out, text, false);
        } else {
            self.out.push_str(text);
        }
    }

    fn write_comment(&mut self, text: &str) {
        self.out.push_str("<!--");
        self.out.push_str(text);
        self.out.push_str("-->");
    }

    fn write_doctype(&mut self, name: &str) {
        self.out.push_str("<!DOCTYPE ");
        self.out.push_str(name);
        self.out.push('>');
    }

    fn serialize_node(&mut self, dom: &Dom, id: NodeId, include_self: bool) {
        match &dom.node(id).data {
            NodeData::Document => {
                for &c in &dom.node(id).children {
                    self.serialize_node(dom, c, true);
                }
            }
            NodeData::Element {
                ns, local, attrs, ..
            } => {
                if include_self {
                    self.start_elem(ns, local, attrs);
                }
                for &c in &dom.node(id).children {
                    self.serialize_node(dom, c, true);
                }
                if include_self {
                    self.end_elem(local);
                }
            }
            NodeData::Doctype { name, .. } => {
                self.write_doctype(name);
            }
            NodeData::Text(t) => {
                self.write_text(t);
            }
            NodeData::Comment(t) => {
                self.write_comment(t);
            }
        }
    }
}

/// Serialize the children of `root` (ChildrenOnly traversal scope), html5ever style.
pub fn serialize_children(dom: &Dom, root: NodeId, scripting_enabled: bool) -> String {
    let mut s = Serializer {
        out: String::new(),
        stack: vec![ElemInfo {
            html_name: None,
            ignore_children: false,
        }],
        scripting_enabled,
    };
    for &c in &dom.node(root).children {
        s.serialize_node(dom, c, true);
    }
    s.out
}

/// Serialize a whole document (children of the document node).
pub fn serialize_document(dom: &Dom) -> String {
    serialize_children(dom, dom.document, true)
}
