//! HTML5 tokenizer (WHATWG), modelled to match html5ever's observable behaviour.

use super::entities::ENTITIES;
use std::collections::VecDeque;

#[derive(Clone, Debug, PartialEq)]
pub enum Token {
    Doctype {
        name: Option<String>,
        public_id: Option<String>,
        system_id: Option<String>,
        force_quirks: bool,
    },
    StartTag {
        name: String,
        attrs: Vec<(String, String)>,
        self_closing: bool,
    },
    EndTag {
        name: String,
    },
    Comment(String),
    Chars(String),
    Eof,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    Data,
    Rcdata,
    Rawtext,
    ScriptData,
    Plaintext,
    TagOpen,
    EndTagOpen,
    TagName,
    RcdataLessThanSign,
    RcdataEndTagOpen,
    RcdataEndTagName,
    RawtextLessThanSign,
    RawtextEndTagOpen,
    RawtextEndTagName,
    ScriptDataLessThanSign,
    ScriptDataEndTagOpen,
    ScriptDataEndTagName,
    ScriptDataEscapeStart,
    ScriptDataEscapeStartDash,
    ScriptDataEscaped,
    ScriptDataEscapedDash,
    ScriptDataEscapedDashDash,
    ScriptDataEscapedLessThanSign,
    ScriptDataEscapedEndTagOpen,
    ScriptDataEscapedEndTagName,
    ScriptDataDoubleEscapeStart,
    ScriptDataDoubleEscaped,
    ScriptDataDoubleEscapedDash,
    ScriptDataDoubleEscapedDashDash,
    ScriptDataDoubleEscapedLessThanSign,
    ScriptDataDoubleEscapeEnd,
    BeforeAttributeName,
    AttributeName,
    AfterAttributeName,
    BeforeAttributeValue,
    AttributeValueDoubleQuoted,
    AttributeValueSingleQuoted,
    AttributeValueUnquoted,
    AfterAttributeValueQuoted,
    SelfClosingStartTag,
    BogusComment,
    MarkupDeclarationOpen,
    CommentStart,
    CommentStartDash,
    Comment,
    CommentLessThanSign,
    CommentLessThanSignBang,
    CommentLessThanSignBangDash,
    CommentLessThanSignBangDashDash,
    CommentEndDash,
    CommentEnd,
    CommentEndBang,
    Doctype,
    BeforeDoctypeName,
    DoctypeName,
    AfterDoctypeName,
    AfterDoctypePublicKeyword,
    BeforeDoctypePublicIdentifier,
    DoctypePublicIdentifierDoubleQuoted,
    DoctypePublicIdentifierSingleQuoted,
    AfterDoctypePublicIdentifier,
    BetweenDoctypePublicAndSystemIdentifiers,
    AfterDoctypeSystemKeyword,
    BeforeDoctypeSystemIdentifier,
    DoctypeSystemIdentifierDoubleQuoted,
    DoctypeSystemIdentifierSingleQuoted,
    AfterDoctypeSystemIdentifier,
    BogusDoctype,
    CdataSection,
    CdataSectionBracket,
    CdataSectionEnd,
}

#[derive(Clone, Debug)]
struct TagBuilder {
    is_end: bool,
    name: String,
    attrs: Vec<(String, String)>,
    cur_attr_name: String,
    cur_attr_value: String,
    self_closing: bool,
}

#[derive(Clone, Debug, Default)]
struct DoctypeBuilder {
    name: Option<String>,
    public_id: Option<String>,
    system_id: Option<String>,
    force_quirks: bool,
}

pub struct Tokenizer {
    input: Vec<char>,
    pos: usize,
    pub state: State,
    return_state: State,
    out: VecDeque<Token>,
    pending: String,
    tag: TagBuilder,
    last_start_tag: String,
    temp_buf: String,
    comment: String,
    doctype: DoctypeBuilder,
    /// Set by tree builder: whether CDATA sections are allowed (adjusted current node not in HTML ns).
    pub allow_cdata: bool,
    eof_emitted: bool,
}

fn is_ws(c: char) -> bool {
    matches!(c, '\t' | '\n' | '\u{c}' | ' ')
}

fn lower(c: char) -> char {
    if c.is_ascii_uppercase() {
        c.to_ascii_lowercase()
    } else {
        c
    }
}

impl Tokenizer {
    pub fn new(input: &str) -> Tokenizer {
        // Preprocess: normalize newlines; strip BOM.
        let mut chars: Vec<char> = Vec::with_capacity(input.len());
        let mut it = input.chars().peekable();
        if let Some(&'\u{feff}') = it.peek() {
            it.next();
        }
        while let Some(c) = it.next() {
            if c == '\r' {
                if let Some(&'\n') = it.peek() {
                    it.next();
                }
                chars.push('\n');
            } else {
                chars.push(c);
            }
        }
        Tokenizer {
            input: chars,
            pos: 0,
            state: State::Data,
            return_state: State::Data,
            out: VecDeque::new(),
            pending: String::new(),
            tag: TagBuilder {
                is_end: false,
                name: String::new(),
                attrs: Vec::new(),
                cur_attr_name: String::new(),
                cur_attr_value: String::new(),
                self_closing: false,
            },
            last_start_tag: String::new(),
            temp_buf: String::new(),
            comment: String::new(),
            doctype: DoctypeBuilder::default(),
            allow_cdata: false,
            eof_emitted: false,
        }
    }

    pub fn set_state(&mut self, s: State) {
        self.state = s;
    }

    fn peek(&self) -> Option<char> {
        self.input.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.input.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn reconsume(&mut self) {
        self.pos -= 1;
    }

    fn starts_with_ci(&self, s: &str) -> bool {
        let mut i = self.pos;
        for sc in s.chars() {
            match self.input.get(i) {
                Some(&c) if lower(c) == lower(sc) => i += 1,
                _ => return false,
            }
        }
        true
    }

    fn starts_with(&self, s: &str) -> bool {
        let mut i = self.pos;
        for sc in s.chars() {
            match self.input.get(i) {
                Some(&c) if c == sc => i += 1,
                _ => return false,
            }
        }
        true
    }

    fn emit_char(&mut self, c: char) {
        self.pending.push(c);
    }

    fn emit_str(&mut self, s: &str) {
        self.pending.push_str(s);
    }

    fn flush_chars(&mut self) {
        if !self.pending.is_empty() {
            let s = std::mem::take(&mut self.pending);
            self.out.push_back(Token::Chars(s));
        }
    }

    fn emit_token(&mut self, t: Token) {
        self.flush_chars();
        self.out.push_back(t);
    }

    fn start_tag_builder(&mut self, is_end: bool) {
        self.tag = TagBuilder {
            is_end,
            name: String::new(),
            attrs: Vec::new(),
            cur_attr_name: String::new(),
            cur_attr_value: String::new(),
            self_closing: false,
        };
    }

    fn start_attr(&mut self) {
        self.finish_attr();
        self.tag.cur_attr_name.clear();
        self.tag.cur_attr_value.clear();
    }

    fn finish_attr(&mut self) {
        if !self.tag.cur_attr_name.is_empty() {
            let name = std::mem::take(&mut self.tag.cur_attr_name);
            let value = std::mem::take(&mut self.tag.cur_attr_value);
            // Duplicate attribute: drop (first wins)
            if !self.tag.attrs.iter().any(|(n, _)| *n == name) {
                self.tag.attrs.push((name, value));
            }
        } else {
            self.tag.cur_attr_value.clear();
        }
    }

    fn emit_tag(&mut self) {
        self.finish_attr();
        let tag = self.tag.clone();
        if tag.is_end {
            self.emit_token(Token::EndTag { name: tag.name });
        } else {
            self.last_start_tag = tag.name.clone();
            self.emit_token(Token::StartTag {
                name: tag.name,
                attrs: tag.attrs,
                self_closing: tag.self_closing,
            });
        }
    }

    fn emit_comment(&mut self) {
        let c = std::mem::take(&mut self.comment);
        self.emit_token(Token::Comment(c));
    }

    fn emit_doctype(&mut self) {
        let d = std::mem::take(&mut self.doctype);
        self.emit_token(Token::Doctype {
            name: d.name,
            public_id: d.public_id,
            system_id: d.system_id,
            force_quirks: d.force_quirks,
        });
    }

    fn emit_eof(&mut self) {
        self.flush_chars();
        self.out.push_back(Token::Eof);
        self.eof_emitted = true;
    }

    fn is_appropriate_end_tag(&self) -> bool {
        self.tag.is_end && self.tag.name == self.last_start_tag
    }

    fn emit_temp_buf(&mut self) {
        let t = std::mem::take(&mut self.temp_buf);
        self.pending.push_str(&t);
    }

    /// Consume a character reference; returns the replacement text (or the original text if none).
    fn consume_char_ref(&mut self, in_attribute: bool) -> String {
        // We're positioned right after '&'.
        let c = match self.peek() {
            Some(c) => c,
            None => return "&".to_string(),
        };
        if c.is_ascii_alphanumeric() {
            // Named character reference: find longest match
            let start = self.pos;
            let mut best: Option<(usize, &'static str)> = None; // (end pos, replacement)
            let mut name = String::new();
            let mut i = start;
            // Longest possible entity name is ~32 chars
            while i < self.input.len() && name.len() < 40 {
                let ch = self.input[i];
                if !(ch.is_ascii_alphanumeric() || ch == ';') {
                    break;
                }
                name.push(ch);
                i += 1;
                if let Ok(idx) = ENTITIES.binary_search_by(|(k, _)| (*k).cmp(name.as_str())) {
                    best = Some((i, ENTITIES[idx].1));
                }
                if ch == ';' {
                    break;
                }
            }
            match best {
                Some((end, repl)) => {
                    let matched: String = self.input[start..end].iter().collect();
                    let last_is_semicolon = matched.ends_with(';');
                    if in_attribute && !last_is_semicolon {
                        if let Some(&next) = self.input.get(end) {
                            if next == '=' || next.is_ascii_alphanumeric() {
                                // Not a character reference (historical reasons)
                                // consume nothing extra; return "&" and let caller continue
                                return "&".to_string();
                            }
                        }
                    }
                    self.pos = end;
                    repl.to_string()
                }
                None => "&".to_string(),
            }
        } else if c == '#' {
            let save = self.pos;
            self.pos += 1;
            let mut hex = false;
            if let Some(x) = self.peek() {
                if x == 'x' || x == 'X' {
                    hex = true;
                    self.pos += 1;
                }
            }
            let digits_start = self.pos;
            let mut value: u32 = 0;
            let mut overflow = false;
            while let Some(d) = self.peek() {
                let dv = if hex {
                    d.to_digit(16)
                } else {
                    d.to_digit(10)
                };
                match dv {
                    Some(v) => {
                        self.pos += 1;
                        if !overflow {
                            value = value
                                .checked_mul(if hex { 16 } else { 10 })
                                .and_then(|v2| v2.checked_add(v))
                                .unwrap_or_else(|| {
                                    overflow = true;
                                    0x110000
                                });
                            if value > 0x10FFFF {
                                overflow = true;
                                value = 0x110000;
                            }
                        }
                    }
                    None => break,
                }
            }
            if self.pos == digits_start {
                // No digits: not a character reference
                self.pos = save;
                return "&".to_string();
            }
            if let Some(';') = self.peek() {
                self.pos += 1;
            }
            let cp = if overflow {
                0xFFFD
            } else {
                numeric_ref_replacement(value)
            };
            match char::from_u32(cp) {
                Some(ch) => ch.to_string(),
                None => "\u{fffd}".to_string(),
            }
        } else {
            "&".to_string()
        }
    }

    pub fn next_token(&mut self) -> Token {
        loop {
            if let Some(t) = self.out.pop_front() {
                return t;
            }
            if self.eof_emitted {
                return Token::Eof;
            }
            self.step();
        }
    }

    fn step(&mut self) {
        use State::*;
        match self.state {
            Data => match self.next_char() {
                Some('&') => {
                    let s = self.consume_char_ref(false);
                    self.emit_str(&s);
                }
                Some('<') => {
                    self.state = TagOpen;
                    // Flush characters so the tree builder can update CDATA allowance etc.
                    self.flush_chars();
                }
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            Rcdata => match self.next_char() {
                Some('&') => {
                    let s = self.consume_char_ref(false);
                    self.emit_str(&s);
                }
                Some('<') => self.state = RcdataLessThanSign,
                Some('\0') => self.emit_char('\u{fffd}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            Rawtext => match self.next_char() {
                Some('<') => self.state = RawtextLessThanSign,
                Some('\0') => self.emit_char('\u{fffd}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            ScriptData => match self.next_char() {
                Some('<') => self.state = ScriptDataLessThanSign,
                Some('\0') => self.emit_char('\u{fffd}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            Plaintext => match self.next_char() {
                Some('\0') => self.emit_char('\u{fffd}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            TagOpen => match self.next_char() {
                Some('!') => self.state = MarkupDeclarationOpen,
                Some('/') => self.state = EndTagOpen,
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag_builder(false);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('?') => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
                Some(_) => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = Data;
                }
                None => {
                    self.emit_char('<');
                    self.emit_eof();
                }
            },
            EndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag_builder(true);
                    self.reconsume();
                    self.state = TagName;
                }
                Some('>') => self.state = Data,
                Some(_) => {
                    self.comment.clear();
                    self.reconsume();
                    self.state = BogusComment;
                }
                None => {
                    self.emit_str("</");
                    self.emit_eof();
                }
            },
            TagName => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttributeName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                Some('\0') => self.tag.name.push('\u{fffd}'),
                Some(c) => self.tag.name.push(lower(c)),
                None => self.emit_eof(),
            },
            RcdataLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = RcdataEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = Rcdata;
                }
            },
            RcdataEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag_builder(true);
                    self.reconsume();
                    self.state = RcdataEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = Rcdata;
                }
            },
            RcdataEndTagName | RawtextEndTagName | ScriptDataEndTagName
            | ScriptDataEscapedEndTagName => {
                let (back_state, _) = match self.state {
                    RcdataEndTagName => (Rcdata, ()),
                    RawtextEndTagName => (Rawtext, ()),
                    ScriptDataEndTagName => (ScriptData, ()),
                    _ => (ScriptDataEscaped, ()),
                };
                let c = self.next_char();
                let mut anything_else = false;
                match c {
                    Some(ch) if is_ws(ch) => {
                        if self.is_appropriate_end_tag() {
                            self.state = BeforeAttributeName;
                        } else {
                            anything_else = true;
                        }
                    }
                    Some('/') => {
                        if self.is_appropriate_end_tag() {
                            self.state = SelfClosingStartTag;
                        } else {
                            anything_else = true;
                        }
                    }
                    Some('>') => {
                        if self.is_appropriate_end_tag() {
                            self.state = Data;
                            self.emit_tag();
                        } else {
                            anything_else = true;
                        }
                    }
                    Some(ch) if ch.is_ascii_alphabetic() => {
                        self.tag.name.push(lower(ch));
                        self.temp_buf.push(ch);
                    }
                    _ => anything_else = true,
                }
                if anything_else {
                    self.emit_str("</");
                    self.emit_temp_buf();
                    if c.is_some() {
                        self.reconsume();
                    }
                    self.state = back_state;
                }
            }
            RawtextLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = RawtextEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = Rawtext;
                }
            },
            RawtextEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag_builder(true);
                    self.reconsume();
                    self.state = RawtextEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = Rawtext;
                }
            },
            ScriptDataLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEndTagOpen;
                }
                Some('!') => {
                    self.state = ScriptDataEscapeStart;
                    self.emit_str("<!");
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag_builder(true);
                    self.reconsume();
                    self.state = ScriptDataEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscapeStart => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapeStartDash;
                    self.emit_char('-');
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscapeStartDash => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptData;
                }
            },
            ScriptDataEscaped => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapedDash;
                    self.emit_char('-');
                }
                Some('<') => self.state = ScriptDataEscapedLessThanSign,
                Some('\0') => self.emit_char('\u{fffd}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            ScriptDataEscapedDash => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                Some('<') => self.state = ScriptDataEscapedLessThanSign,
                Some('\0') => {
                    self.state = ScriptDataEscaped;
                    self.emit_char('\u{fffd}');
                }
                Some(c) => {
                    self.state = ScriptDataEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataEscapedDashDash => match self.next_char() {
                Some('-') => self.emit_char('-'),
                Some('<') => self.state = ScriptDataEscapedLessThanSign,
                Some('>') => {
                    self.state = ScriptData;
                    self.emit_char('>');
                }
                Some('\0') => {
                    self.state = ScriptDataEscaped;
                    self.emit_char('\u{fffd}');
                }
                Some(c) => {
                    self.state = ScriptDataEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataEscapedLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataEscapedEndTagOpen;
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.clear();
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataDoubleEscapeStart;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataEscapedEndTagOpen => match self.next_char() {
                Some(c) if c.is_ascii_alphabetic() => {
                    self.start_tag_builder(true);
                    self.reconsume();
                    self.state = ScriptDataEscapedEndTagName;
                }
                _ => {
                    self.emit_str("</");
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataDoubleEscapeStart => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    if self.temp_buf == "script" {
                        self.state = ScriptDataDoubleEscaped;
                    } else {
                        self.state = ScriptDataEscaped;
                    }
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(lower(c));
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataEscaped;
                }
            },
            ScriptDataDoubleEscaped => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataDoubleEscapedDash;
                    self.emit_char('-');
                }
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Some('\0') => self.emit_char('\u{fffd}'),
                Some(c) => self.emit_char(c),
                None => self.emit_eof(),
            },
            ScriptDataDoubleEscapedDash => match self.next_char() {
                Some('-') => {
                    self.state = ScriptDataDoubleEscapedDashDash;
                    self.emit_char('-');
                }
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Some('\0') => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char('\u{fffd}');
                }
                Some(c) => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataDoubleEscapedDashDash => match self.next_char() {
                Some('-') => self.emit_char('-'),
                Some('<') => {
                    self.state = ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Some('>') => {
                    self.state = ScriptData;
                    self.emit_char('>');
                }
                Some('\0') => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char('\u{fffd}');
                }
                Some(c) => {
                    self.state = ScriptDataDoubleEscaped;
                    self.emit_char(c);
                }
                None => self.emit_eof(),
            },
            ScriptDataDoubleEscapedLessThanSign => match self.next_char() {
                Some('/') => {
                    self.temp_buf.clear();
                    self.state = ScriptDataDoubleEscapeEnd;
                    self.emit_char('/');
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            ScriptDataDoubleEscapeEnd => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    if self.temp_buf == "script" {
                        self.state = ScriptDataEscaped;
                    } else {
                        self.state = ScriptDataDoubleEscaped;
                    }
                    self.emit_char(c);
                }
                Some(c) if c.is_ascii_alphabetic() => {
                    self.temp_buf.push(lower(c));
                    self.emit_char(c);
                }
                _ => {
                    self.reconsume();
                    self.state = ScriptDataDoubleEscaped;
                }
            },
            BeforeAttributeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('/') | Some('>') | None => {
                    self.reconsume_or_eof();
                    self.state = AfterAttributeName;
                }
                Some('=') => {
                    self.start_attr();
                    self.tag.cur_attr_name.push('=');
                    self.state = AttributeName;
                }
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttributeName;
                }
            },
            AttributeName => match self.next_char() {
                Some(c) if is_ws(c) || c == '/' || c == '>' => {
                    self.reconsume();
                    self.state = AfterAttributeName;
                }
                None => {
                    self.state = AfterAttributeName;
                }
                Some('=') => self.state = BeforeAttributeValue,
                Some('\0') => self.tag.cur_attr_name.push('\u{fffd}'),
                Some(c) => self.tag.cur_attr_name.push(lower(c)),
            },
            AfterAttributeName => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('/') => self.state = SelfClosingStartTag,
                Some('=') => self.state = BeforeAttributeValue,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                None => self.emit_eof(),
                Some(_) => {
                    self.start_attr();
                    self.reconsume();
                    self.state = AttributeName;
                }
            },
            BeforeAttributeValue => match self.next_char() {
                Some(c) if is_ws(c) => {}
                Some('"') => self.state = AttributeValueDoubleQuoted,
                Some('\'') => self.state = AttributeValueSingleQuoted,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                _ => {
                    self.reconsume_or_eof();
                    self.state = AttributeValueUnquoted;
                }
            },
            AttributeValueDoubleQuoted => match self.next_char() {
                Some('"') => self.state = AfterAttributeValueQuoted,
                Some('&') => {
                    let s = self.consume_char_ref(true);
                    self.tag.cur_attr_value.push_str(&s);
                }
                Some('\0') => self.tag.cur_attr_value.push('\u{fffd}'),
                Some(c) => self.tag.cur_attr_value.push(c),
                None => self.emit_eof(),
            },
            AttributeValueSingleQuoted => match self.next_char() {
                Some('\'') => self.state = AfterAttributeValueQuoted,
                Some('&') => {
                    let s = self.consume_char_ref(true);
                    self.tag.cur_attr_value.push_str(&s);
                }
                Some('\0') => self.tag.cur_attr_value.push('\u{fffd}'),
                Some(c) => self.tag.cur_attr_value.push(c),
                None => self.emit_eof(),
            },
            AttributeValueUnquoted => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttributeName,
                Some('&') => {
                    let s = self.consume_char_ref(true);
                    self.tag.cur_attr_value.push_str(&s);
                }
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                Some('\0') => self.tag.cur_attr_value.push('\u{fffd}'),
                Some(c) => self.tag.cur_attr_value.push(c),
                None => self.emit_eof(),
            },
            AfterAttributeValueQuoted => match self.next_char() {
                Some(c) if is_ws(c) => self.state = BeforeAttributeName,
                Some('/') => self.state = SelfClosingStartTag,
                Some('>') => {
                    self.state = Data;
                    self.emit_tag();
                }
                None => self.emit_eof(),
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttributeName;
                }
            },
            SelfClosingStartTag => match self.next_char() {
                Some('>') => {
                    self.tag.self_closing = true;
                    self.state = Data;
                    self.emit_tag();
                }
                None => self.emit_eof(),
                Some(_) => {
                    self.reconsume();
                    self.state = BeforeAttributeName;
                }
            },
            BogusComment => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some('\0') => self.comment.push('\u{fffd}'),
                Some(c) => self.comment.push(c),
            },
            MarkupDeclarationOpen => {
                if self.starts_with("--") {
                    self.pos += 2;
                    self.comment.clear();
                    self.state = CommentStart;
                } else if self.starts_with_ci("DOCTYPE") {
                    self.pos += 7;
                    self.state = Doctype;
                } else if self.starts_with("[CDATA[") {
                    if self.allow_cdata {
                        self.pos += 7;
                        self.state = CdataSection;
                    } else {
                        self.comment.clear();
                        self.state = BogusComment;
                    }
                } else {
                    self.comment.clear();
                    self.state = BogusComment;
                }
            }
            CommentStart => match self.next_char() {
                Some('-') => self.state = CommentStartDash,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                _ => {
                    self.reconsume_or_eof();
                    self.state = Comment;
                }
            },
            CommentStartDash => match self.next_char() {
                Some('-') => self.state = CommentEnd,
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            Comment => match self.next_char() {
                Some('<') => {
                    self.comment.push('<');
                    self.state = CommentLessThanSign;
                }
                Some('-') => self.state = CommentEndDash,
                Some('\0') => self.comment.push('\u{fffd}'),
                Some(c) => self.comment.push(c),
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
            },
            CommentLessThanSign => match self.next_char() {
                Some('!') => {
                    self.comment.push('!');
                    self.state = CommentLessThanSignBang;
                }
                Some('<') => self.comment.push('<'),
                _ => {
                    self.reconsume_or_eof();
                    self.state = Comment;
                }
            },
            CommentLessThanSignBang => match self.next_char() {
                Some('-') => self.state = CommentLessThanSignBangDash,
                _ => {
                    self.reconsume_or_eof();
                    self.state = Comment;
                }
            },
            CommentLessThanSignBangDash => match self.next_char() {
                Some('-') => self.state = CommentLessThanSignBangDashDash,
                _ => {
                    self.reconsume_or_eof();
                    self.state = CommentEndDash;
                }
            },
            CommentLessThanSignBangDashDash => {
                // Anything else: reconsume in comment end state
                self.reconsume_or_eof_peek();
                self.state = CommentEnd;
            }
            CommentEndDash => match self.next_char() {
                Some('-') => self.state = CommentEnd,
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push('-');
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEnd => match self.next_char() {
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                Some('!') => self.state = CommentEndBang,
                Some('-') => self.comment.push('-'),
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push_str("--");
                    self.reconsume();
                    self.state = Comment;
                }
            },
            CommentEndBang => match self.next_char() {
                Some('-') => {
                    self.comment.push_str("--!");
                    self.state = CommentEndDash;
                }
                Some('>') => {
                    self.state = Data;
                    self.emit_comment();
                }
                None => {
                    self.emit_comment();
                    self.emit_eof();
                }
                Some(_) => {
                    self.comment.push_str("--!");
