                    Some(c) if c == q => self.state = AfterDoctypeSystemIdentifier,
                    Some('\0') => self
                        .doctype
                        .system_id
                        .get_or_insert_with(String::new)
                        .push('\u{fffd}'),
                    Some('>') => {
