fn foreign_attr(name: &str) -> Option<(&'static str, Option<&'static str>, &'static str)> {
    // returns (ns, prefix, local)
    match name {
        "xlink:actuate" => Some((NS_XLINK, Some("xlink"), "actuate")),
        "xlink:arcrole" => Some((NS_XLINK, Some("xlink"), "arcrole")),
        "xlink:href" => Some((NS_XLINK, Some("xlink"), "href")),
        "xlink:role" => Some((NS_XLINK, Some("xlink"), "role")),
        "xlink:show" => Some((NS_XLINK, Some("xlink"), "show")),
        "xlink:title" => Some((NS_XLINK, Some("xlink"), "title")),
        "xlink:type" => Some((NS_XLINK, Some("xlink"), "type")),
        "xml:lang" => Some((NS_XML, Some("xml"), "lang")),
        "xml:space" => Some((NS_XML, Some("xml"), "space")),
        "xmlns" => Some((NS_XMLNS, None, "xmlns")),
        "xmlns:xlink" => Some((NS_XMLNS, Some("xmlns"), "xlink")),
        _ => None,
    }
}

