pub struct TreeBuilder {
    pub dom: Dom,
    tok: Tokenizer,
    mode: Mode,
    original_mode: Mode,
    template_modes: Vec<Mode>,
    open: Vec<NodeId>,
    fmt: Vec<FmtEntry>,
    head: Option<NodeId>,
    form: Option<NodeId>,
    frameset_ok: bool,
    foster_parenting: bool,
    pending_table_text: String,
    pending_table_text_non_ws: bool,
    scripting: bool,
    ignore_lf: bool,
    done: bool,
}

#[derive(PartialEq)]
enum Proc {
    Done,
    Reprocess,
}

impl TreeBuilder {
    pub fn new(input: &str) -> TreeBuilder {
        TreeBuilder {
            dom: Dom::new(),
            tok: Tokenizer::new(input),
            mode: Mode::Initial,
            original_mode: Mode::Initial,
            template_modes: Vec::new(),
            open: Vec::new(),
            fmt: Vec::new(),
            head: None,
            form: None,
            frameset_ok: true,
            foster_parenting: false,
            pending_table_text: String::new(),
            pending_table_text_non_ws: false,
            scripting: true,
            ignore_lf: false,
            done: false,
        }
    }

    pub fn parse(mut self) -> Dom {
        while !self.done {
            self.tok.allow_cdata = self.adjusted_current_node_not_html();
            let token = self.tok.next_token();
            self.process_token(token);
        }
        self.dom
    }

    // ---------- helpers ----------

    fn current(&self) -> NodeId {
        *self.open.last().expect("no current node")
    }

    fn adjusted_current(&self) -> Option<NodeId> {
        self.open.last().copied()
    }

    fn adjusted_current_node_not_html(&self) -> bool {
        match self.adjusted_current() {
            Some(n) => match self.dom.element_name(n) {
                Some((ns, _)) => ns != NS_HTML,
                None => false,
            },
            None => false,
        }
    }

    fn name_of(&self, n: NodeId) -> &str {
        self.dom.local_name(n).unwrap_or("")
    }

    fn is_html(&self, n: NodeId, name: &str) -> bool {
        self.dom.is_html_element(n, name)
    }

    fn is_html_any(&self, n: NodeId, names: &[&str]) -> bool {
        match self.dom.element_name(n) {
            Some((ns, local)) => ns == NS_HTML && names.contains(&local),
            None => false,
        }
    }

    fn current_is(&self, name: &str) -> bool {
        self.open.last().map_or(false, |&n| self.is_html(n, name))
    }

    fn current_is_any(&self, names: &[&str]) -> bool {
        self.open.last().map_or(false, |&n| self.is_html_any(n, names))
    }

    fn is_special(&self, n: NodeId) -> bool {
        match self.dom.element_name(n) {
            Some((ns, local)) => {
                (ns == NS_HTML && SPECIAL.contains(&local))
                    || (ns == NS_MATHML
                        && matches!(local, "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml"))
                    || (ns == NS_SVG && matches!(local, "foreignObject" | "desc" | "title"))
            }
            None => false,
        }
    }

    fn is_mathml_text_integration_point(&self, n: NodeId) -> bool {
        match self.dom.element_name(n) {
            Some((ns, local)) => ns == NS_MATHML && matches!(local, "mi" | "mo" | "mn" | "ms" | "mtext"),
            None => false,
        }
    }

    fn is_html_integration_point(&self, n: NodeId) -> bool {
        match self.dom.element_name(n) {
            Some((ns, local)) => {
                if ns == NS_SVG && matches!(local, "foreignObject" | "desc" | "title") {
                    return true;
                }
                if ns == NS_MATHML && local == "annotation-xml" {
                    if let Some(enc) = self.dom.get_attr(n, "encoding") {
                        let e = enc.to_ascii_lowercase();
                        return e == "text/html" || e == "application/xhtml+xml";
                    }
                }
                false
            }
            None => false,
        }
    }

    fn in_scope_impl<F>(&self, target: F, extra: &[&str], list_mode: bool) -> bool
    where
        F: Fn(&Self, NodeId) -> bool,
    {
        for &n in self.open.iter().rev() {
            if target(self, n) {
                return true;
            }
            match self.dom.element_name(n) {
                Some((ns, local)) => {
                    if ns == NS_HTML {
                        if list_mode {
                            if extra.contains(&local) {
                                return false;
                            }
                        } else if matches!(
                            local,
                            "applet" | "caption" | "html" | "table" | "td" | "th" | "marquee"
                                | "object" | "template"
                        ) || extra.contains(&local)
                        {
                            return false;
                        }
                    } else if !list_mode {
                        if ns == NS_MATHML
                            && matches!(local, "mi" | "mo" | "mn" | "ms" | "mtext" | "annotation-xml")
                        {
                            return false;
                        }
                        if ns == NS_SVG && matches!(local, "foreignObject" | "desc" | "title") {
                            return false;
                        }
                    }
                }
                None => {}
            }
        }
        false
    }

    fn in_scope(&self, name: &str) -> bool {
        self.in_scope_impl(|s, n| s.is_html(n, name), &[], false)
    }

    fn in_scope_any(&self, names: &[&str]) -> bool {
        self.in_scope_impl(|s, n| s.is_html_any(n, names), &[], false)
    }

    fn node_in_scope(&self, node: NodeId) -> bool {
        self.in_scope_impl(|_, n| n == node, &[], false)
    }

    fn in_list_item_scope(&self, name: &str) -> bool {
        self.in_scope_impl(|s, n| s.is_html(n, name), &["ol", "ul"], false)
    }

    fn in_button_scope(&self, name: &str) -> bool {
        self.in_scope_impl(|s, n| s.is_html(n, name), &["button"], false)
    }

    fn in_table_scope(&self, name: &str) -> bool {
        self.in_scope_impl(|s, n| s.is_html(n, name), &["html", "table", "template"], true)
    }

    fn in_table_scope_any(&self, names: &[&str]) -> bool {
        self.in_scope_impl(|s, n| s.is_html_any(n, names), &["html", "table", "template"], true)
    }

    fn in_select_scope(&self, name: &str) -> bool {
        for &n in self.open.iter().rev() {
            if self.is_html(n, name) {
                return true;
            }
            match self.dom.element_name(n) {
                Some((ns, local)) => {
                    if !(ns == NS_HTML && (local == "optgroup" || local == "option")) {
                        return false;
                    }
                }
                None => return false,
            }
        }
        false
    }

    fn pop(&mut self) -> Option<NodeId> {
        self.open.pop()
    }

    fn pop_until(&mut self, name: &str) {
        while let Some(n) = self.pop() {
            if self.is_html(n, name) {
                break;
            }
        }
    }

    fn pop_until_any(&mut self, names: &[&str]) {
        while let Some(n) = self.pop() {
            if self.is_html_any(n, names) {
                break;
            }
        }
    }

    fn remove_from_open(&mut self, node: NodeId) {
        if let Some(pos) = self.open.iter().rposition(|&n| n == node) {
            self.open.remove(pos);
        }
    }

    fn generate_implied_end_tags(&mut self, except: Option<&str>) {
        loop {
            match self.open.last() {
                Some(&n) => {
                    let name = self.name_of(n).to_string();
                    let is_html = self.dom.element_name(n).map_or(false, |(ns, _)| ns == NS_HTML);
                    if is_html
                        && matches!(
                            name.as_str(),
                            "dd" | "dt" | "li" | "optgroup" | "option" | "p" | "rb" | "rp" | "rt" | "rtc"
                        )
                        && except != Some(name.as_str())
                    {
                        self.pop();
                    } else {
                        break;
                    }
                }
                None => break,
            }
        }
    }

    fn generate_implied_end_tags_thoroughly(&mut self) {
        loop {
            match self.open.last() {
                Some(&n) => {
                    if self.is_html_any(
                        n,
                        &[
                            "caption", "colgroup", "dd", "dt", "li", "optgroup", "option", "p", "rb",
                            "rp", "rt", "rtc", "tbody", "td", "tfoot", "th", "thead", "tr",
                        ],
                    ) {
                        self.pop();
                    } else {
                        break;
                    }
                }
                None => break,
            }
        }
    }

    /// Appropriate place for inserting a node: returns (parent, Option<before sibling>)
    fn insertion_place(&mut self, override_target: Option<NodeId>) -> (NodeId, Option<NodeId>) {
        let target = override_target.unwrap_or_else(|| self.current());
        let mut place: (NodeId, Option<NodeId>) = (target, None);
        if self.foster_parenting
            && self.is_html_any(target, &["table", "tbody", "tfoot", "thead", "tr"])
        {
            let last_template = self.open.iter().rposition(|&n| self.is_html(n, "template"));
            let last_table = self.open.iter().rposition(|&n| self.is_html(n, "table"));
            match (last_template, last_table) {
                (Some(t), Some(tb)) if t > tb => {
                    place = (self.open[t], None);
                }
                (Some(t), None) => {
                    place = (self.open[t], None);
                }
                (_, Some(tb)) => {
                    let table = self.open[tb];
                    match self.dom.parent(table) {
                        Some(p) => place = (p, Some(table)),
                        None => place = (self.open[tb - 1], None),
                    }
                }
                (None, None) => {
                    place = (self.open[0], None);
                }
            }
        }
        // If inside a template element, use its contents
        if self.is_html(place.0, "template") {
            let tc = self.template_contents(place.0);
            place = (tc, None);
        }
        place
    }

    fn template_contents(&mut self, template: NodeId) -> NodeId {
        if let NodeData::Element {
            template_contents, ..
        } = &self.dom.node(template).data
        {
            if let Some(tc) = template_contents {
                return *tc;
            }
        }
        let tc = self.dom.new_node(NodeData::Document);
        if let NodeData::Element {
            template_contents, ..
        } = &mut self.dom.node_mut(template).data
        {
            *template_contents = Some(tc);
        }
        tc
    }

    fn insert_node_at(&mut self, place: (NodeId, Option<NodeId>), node: NodeId) {
        match place.1 {
            Some(before) => self.dom.insert_before(place.0, node, Some(before)),
            None => self.dom.append(place.0, node),
        }
    }

    fn create_element(&mut self, ns: &str, tag: &Tag) -> NodeId {
        let mut attrs = Vec::new();
        for (n, v) in &tag.attrs {
            let (ans, prefix, local) = if ns != NS_HTML {
                match foreign_attr(n) {
                    Some((ans, p, l)) => (ans.to_string(), p.map(|s| s.to_string()), l.to_string()),
                    None => (String::new(), None, n.clone()),
                }
            } else {
                (String::new(), None, n.clone())
            };
            attrs.push(Attr {
                ns: ans,
                prefix,
                local,
                value: v.clone(),
            });
        }
        let el = self.dom.new_element(ns, &tag.name, attrs);
        if ns == NS_HTML && tag.name == "template" {
            self.template_contents(el);
        }
        el
    }

    fn insert_element(&mut self, tag: &Tag) -> NodeId {
        self.insert_foreign_element(NS_HTML, tag)
    }

    fn insert_foreign_element(&mut self, ns: &str, tag: &Tag) -> NodeId {
        let place = self.insertion_place(None);
        let el = self.create_element(ns, tag);
        self.insert_node_at(place, el);
        self.open.push(el);
        el
    }

    fn insert_element_named(&mut self, name: &str) -> NodeId {
        let tag = Tag {
            name: name.to_string(),
            attrs: Vec::new(),
            self_closing: false,
        };
        self.insert_element(&tag)
    }

    fn insert_text(&mut self, text: &str) {
        if text.is_empty() {
            return;
        }
        let place = self.insertion_place(None);
        match place.1 {
            Some(before) => self.dom.insert_text_before(place.0, before, text),
            None => self.dom.append_text(place.0, text),
        }
    }

    fn insert_comment(&mut self, text: &str) {
        let place = self.insertion_place(None);
        let c = self.dom.new_comment(text);
        self.insert_node_at(place, c);
    }

    fn insert_comment_at(&mut self, parent: NodeId, text: &str) {
        let c = self.dom.new_comment(text);
        self.dom.append(parent, c);
    }

    fn set_tok_state(&mut self, s: State) {
        self.tok.set_state(s);
    }

    fn parse_raw_text(&mut self, tag: &Tag, state: State) {
        self.insert_element(tag);
        self.set_tok_state(state);
        self.original_mode = self.mode;
        self.mode = Mode::Text;
    }

    fn reset_insertion_mode(&mut self) {
        let mut last = false;
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let node = self.open[i];
            if i == 0 {
                last = true;
            }
            let name = self.name_of(node).to_string();
            let is_html = self.dom.element_name(node).map_or(false, |(ns, _)| ns == NS_HTML);
            if !is_html {
                continue;
            }
            match name.as_str() {
                "select" => {
                    if !last {
                        let mut j = i;
                        while j > 0 {
                            j -= 1;
                            let anc = self.open[j];
                            if self.is_html(anc, "template") {
                                break;
                            }
                            if self.is_html(anc, "table") {
                                self.mode = Mode::InSelectInTable;
                                return;
                            }
                        }
                    }
                    self.mode = Mode::InSelect;
                    return;
                }
                "td" | "th" if !last => {
                    self.mode = Mode::InCell;
                    return;
                }
                "tr" => {
                    self.mode = Mode::InRow;
                    return;
                }
                "tbody" | "thead" | "tfoot" => {
                    self.mode = Mode::InTableBody;
                    return;
                }
                "caption" => {
                    self.mode = Mode::InCaption;
                    return;
                }
                "colgroup" => {
                    self.mode = Mode::InColumnGroup;
                    return;
                }
                "table" => {
                    self.mode = Mode::InTable;
                    return;
                }
                "template" => {
                    self.mode = *self.template_modes.last().unwrap_or(&Mode::InTemplate);
                    return;
                }
                "head" if !last => {
                    self.mode = Mode::InHead;
                    return;
                }
                "body" => {
                    self.mode = Mode::InBody;
                    return;
                }
                "frameset" => {
                    self.mode = Mode::InFrameset;
                    return;
                }
                "html" => {
                    self.mode = if self.head.is_none() {
                        Mode::BeforeHead
                    } else {
                        Mode::AfterHead
                    };
                    return;
                }
                _ => {}
            }
            if last {
                self.mode = Mode::InBody;
                return;
            }
        }
        self.mode = Mode::InBody;
    }

    // ---------- active formatting elements ----------

    fn push_marker(&mut self) {
        self.fmt.push(FmtEntry::Marker);
    }

    fn clear_fmt_to_marker(&mut self) {
        while let Some(e) = self.fmt.pop() {
            if matches!(e, FmtEntry::Marker) {
                break;
            }
        }
    }

    fn push_formatting(&mut self, node: NodeId, tag: &Tag) {
        // Noah's Ark clause: no more than 3 identical entries after last marker
        let mut count = 0;
        let mut earliest: Option<usize> = None;
        for (i, e) in self.fmt.iter().enumerate().rev() {
            match e {
                FmtEntry::Marker => break,
                FmtEntry::Element { name, attrs, .. } => {
                    if *name == tag.name && same_attrs(attrs, &tag.attrs) {
                        count += 1;
                        earliest = Some(i);
                    }
                }
            }
        }
        if count >= 3 {
            if let Some(i) = earliest {
                self.fmt.remove(i);
            }
        }
        self.fmt.push(FmtEntry::Element {
            node,
            name: tag.name.clone(),
            attrs: tag.attrs.clone(),
        });
    }

    fn reconstruct_formatting(&mut self) {
        if self.fmt.is_empty() {
            return;
        }
        let last = self.fmt.len() - 1;
        match &self.fmt[last] {
            FmtEntry::Marker => return,
            FmtEntry::Element { node, .. } => {
                if self.open.contains(node) {
                    return;
                }
            }
        }
        let mut i = last;
        loop {
            if i == 0 {
                break;
            }
            i -= 1;
            match &self.fmt[i] {
                FmtEntry::Marker => {
                    i += 1;
                    break;
                }
                FmtEntry::Element { node, .. } => {
                    if self.open.contains(node) {
                        i += 1;
                        break;
                    }
                }
            }
        }
        loop {
            let (name, attrs) = match &self.fmt[i] {
                FmtEntry::Element { name, attrs, .. } => (name.clone(), attrs.clone()),
                FmtEntry::Marker => unreachable!(),
            };
            let tag = Tag {
                name,
                attrs,
                self_closing: false,
            };
            let new = self.insert_element(&tag);
            if let FmtEntry::Element { node, .. } = &mut self.fmt[i] {
                *node = new;
            }
            if i == self.fmt.len() - 1 {
                break;
            }
            i += 1;
        }
    }

    fn fmt_index_of(&self, node: NodeId) -> Option<usize> {
        self.fmt.iter().position(|e| match e {
            FmtEntry::Element { node: n, .. } => *n == node,
            _ => false,
        })
    }

    /// Find formatting element by name between end and last marker.
    fn find_fmt_by_name(&self, name: &str) -> Option<(usize, NodeId)> {
        for (i, e) in self.fmt.iter().enumerate().rev() {
            match e {
                FmtEntry::Marker => return None,
                FmtEntry::Element { node, name: n, .. } => {
                    if n == name {
                        return Some((i, *node));
                    }
                }
            }
        }
        None
    }

    // ---------- adoption agency ----------

    fn adoption_agency(&mut self, subject: &str) {
        // Step 1-2
        if let Some(&cur) = self.open.last() {
            if self.is_html(cur, subject) && self.fmt_index_of(cur).is_none() {
                self.pop();
                return;
            }
        }
        let mut outer = 0;
        while outer < 8 {
            outer += 1;
            let (fmt_idx, fmt_el) = match self.find_fmt_by_name(subject) {
                Some(x) => x,
                None => {
                    self.any_other_end_tag(subject);
                    return;
                }
            };
            let fmt_pos_in_open = match self.open.iter().position(|&n| n == fmt_el) {
                Some(p) => p,
                None => {
                    self.fmt.remove(fmt_idx);
                    return;
                }
            };
            if !self.node_in_scope(fmt_el) {
                return;
            }
            // furthest block
            let furthest = self.open[fmt_pos_in_open + 1..]
                .iter()
                .copied()
                .find(|&n| self.is_special(n));
            let furthest = match furthest {
                Some(f) => f,
                None => {
                    self.open.truncate(fmt_pos_in_open);
                    self.fmt.remove(fmt_idx);
                    return;
                }
            };
            let common_ancestor = self.open[fmt_pos_in_open - 1];
            let mut bookmark = fmt_idx;
            let mut node = furthest;
            let mut last_node = furthest;
            let mut node_pos = self.open.iter().position(|&n| n == node).unwrap();
            let mut inner = 0;
            loop {
                inner += 1;
                node_pos -= 1;
                node = self.open[node_pos];
                if node == fmt_el {
                    break;
                }
                let node_fmt_idx = self.fmt_index_of(node);
                if inner > 3 && node_fmt_idx.is_some() {
                    let idx = node_fmt_idx.unwrap();
                    self.fmt.remove(idx);
                    if idx < bookmark {
                        bookmark -= 1;
                    }
                    self.open.remove(node_pos);
                    continue;
                }
                let node_fmt_idx = match self.fmt_index_of(node) {
                    Some(i) => i,
                    None => {
                        self.open.remove(node_pos);
                        continue;
                    }
                };
                // create new element for the token
                let (name, attrs) = match &self.fmt[node_fmt_idx] {
                    FmtEntry::Element { name, attrs, .. } => (name.clone(), attrs.clone()),
                    _ => unreachable!(),
                };
                let tag = Tag {
                    name,
                    attrs,
                    self_closing: false,
                };
                let new_el = self.create_element(NS_HTML, &tag);
                if let FmtEntry::Element { node: n, .. } = &mut self.fmt[node_fmt_idx] {
                    *n = new_el;
                }
                self.open[node_pos] = new_el;
                node = new_el;
                if last_node == furthest {
                    bookmark = node_fmt_idx + 1;
                }
                self.dom.append(node, last_node);
                last_node = node;
            }
            // insert last_node at appropriate place with common_ancestor as override
            let saved_foster = self.foster_parenting;
            let place = {
                // appropriate place for inserting with override target common_ancestor
                let target = common_ancestor;
                let mut place: (NodeId, Option<NodeId>) = (target, None);
                if self.foster_parenting
                    && self.is_html_any(target, &["table", "tbody", "tfoot", "thead", "tr"])
                {
                    place = self.insertion_place(Some(target));
                } else if self.is_html(target, "template") {
                    let tc = self.template_contents(target);
                    place = (tc, None);
                }
                place
            };
            self.foster_parenting = saved_foster;
            self.insert_node_at(place, last_node);
            // create new element for formatting element token
            let (name, attrs) = match &self.fmt[fmt_idx] {
                FmtEntry::Element { name, attrs, .. } => (name.clone(), attrs.clone()),
                _ => unreachable!(),
            };
            let tag = Tag {
                name,
                attrs,
                self_closing: false,
            };
            let new_fmt = self.create_element(NS_HTML, &tag);
            // move children of furthest block to new element
            let children = self.dom.children(furthest);
            for c in children {
                self.dom.append(new_fmt, c);
            }
            self.dom.append(furthest, new_fmt);
            // remove fmt_el from fmt list, insert new at bookmark
            self.fmt.remove(fmt_idx);
            let bm = if bookmark > fmt_idx { bookmark - 1 } else { bookmark };
            let bm = bm.min(self.fmt.len());
            self.fmt.insert(
                bm,
                FmtEntry::Element {
                    node: new_fmt,
                    name: tag.name.clone(),
                    attrs: tag.attrs.clone(),
                },
            );
            // remove fmt_el from open elements, insert new_fmt after furthest block
            self.remove_from_open(fmt_el);
            if let Some(fpos) = self.open.iter().position(|&n| n == furthest) {
                self.open.insert(fpos + 1, new_fmt);
            }
        }
    }

    fn any_other_end_tag(&mut self, name: &str) {
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let node = self.open[i];
            if self.is_html(node, name) {
                self.generate_implied_end_tags(Some(name));
                self.open.truncate(i);
                return;
            }
            if self.is_special(node) {
                return;
            }
        }
    }

    // ---------- token dispatch ----------

    fn process_token(&mut self, token: Token) {
        let token = if self.ignore_lf {
            self.ignore_lf = false;
            match token {
                Token::Chars(s) if s.starts_with('\n') => {
                    let rest = s[1..].to_string();
                    if rest.is_empty() {
                        return;
                    }
                    Token::Chars(rest)
                }
                t => t,
            }
        } else {
            token
        };
        // Split character tokens into runs and dispatch each run.
        if let Token::Chars(s) = &token {
            // If in foreign content we need per-token handling; splitting is safe.
            let mut runs: Vec<String> = Vec::new();
            let mut cur = String::new();
            let mut cur_kind = 0u8; // 1 ws, 2 nul, 3 other
            for c in s.chars() {
                let k = if c == '\0' {
                    2
                } else if is_ws(c) {
                    1
                } else {
                    3
                };
                if k != cur_kind && !cur.is_empty() {
                    runs.push(std::mem::take(&mut cur));
                }
                cur_kind = k;
                cur.push(c);
            }
            if !cur.is_empty() {
                runs.push(cur);
            }
            for r in runs {
                self.dispatch(Token::Chars(r));
            }
            return;
        }
        self.dispatch(token);
    }

    fn dispatch(&mut self, token: Token) {
        let mut token = token;
        loop {
            let use_foreign = self.should_use_foreign_rules(&token);
            let r = if use_foreign {
                self.foreign_content(&token)
            } else {
                self.process_in_mode(self.mode, &token)
            };
            if r == Proc::Done {
                break;
            }
            // Reprocess: possibly token mutated (e.g. image->img)
            token = self.reprocess_token.take().unwrap_or(token);
        }
    }

    fn should_use_foreign_rules(&self, token: &Token) -> bool {
        let acn = match self.adjusted_current() {
            Some(n) => n,
            None => return false,
        };
        let (ns, _local) = match self.dom.element_name(acn) {
            Some(x) => x,
            None => return false,
        };
        if ns == NS_HTML {
            return false;
        }
        if self.is_mathml_text_integration_point(acn) {
            match token {
                Token::StartTag { name, .. } if name != "mglyph" && name != "malignmark" => {
                    return false
                }
                Token::Chars(_) => return false,
                _ => {}
            }
        }
        if ns == NS_MATHML && _local == "annotation-xml" {
            if let Token::StartTag { name, .. } = token {
                if name == "svg" {
                    return false;
                }
            }
        }
        if self.is_html_integration_point(acn) {
            match token {
                Token::StartTag { .. } | Token::Chars(_) => return false,
                _ => {}
            }
        }
        if let Token::Eof = token {
            return false;
        }
        true
    }
}

fn same_attrs(a: &[(String, String)], b: &[(String, String)]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    for (n, v) in a {
        match b.iter().find(|(bn, _)| bn == n) {
            Some((_, bv)) if bv == v => {}
            _ => return false,
        }
    }
    true
}

