// Insertion mode handlers for TreeBuilder (included from tree_builder.rs).

impl TreeBuilder {
    fn tag_of(token: &Token) -> Tag {
        match token {
            Token::StartTag {
                name,
                attrs,
                self_closing,
            } => Tag {
                name: name.clone(),
                attrs: attrs.clone(),
                self_closing: *self_closing,
            },
            _ => unreachable!(),
        }
    }

    fn process_in_mode(&mut self, mode: Mode, token: &Token) -> Proc {
        match mode {
            Mode::Initial => self.mode_initial(token),
            Mode::BeforeHtml => self.mode_before_html(token),
            Mode::BeforeHead => self.mode_before_head(token),
            Mode::InHead => self.mode_in_head(token),
            Mode::InHeadNoscript => self.mode_in_head_noscript(token),
            Mode::AfterHead => self.mode_after_head(token),
            Mode::InBody => self.mode_in_body(token),
            Mode::Text => self.mode_text(token),
            Mode::InTable => self.mode_in_table(token),
            Mode::InTableText => self.mode_in_table_text(token),
            Mode::InCaption => self.mode_in_caption(token),
            Mode::InColumnGroup => self.mode_in_column_group(token),
            Mode::InTableBody => self.mode_in_table_body(token),
            Mode::InRow => self.mode_in_row(token),
            Mode::InCell => self.mode_in_cell(token),
            Mode::InSelect => self.mode_in_select(token),
            Mode::InSelectInTable => self.mode_in_select_in_table(token),
            Mode::InTemplate => self.mode_in_template(token),
            Mode::AfterBody => self.mode_after_body(token),
            Mode::InFrameset => self.mode_in_frameset(token),
            Mode::AfterFrameset => self.mode_after_frameset(token),
            Mode::AfterAfterBody => self.mode_after_after_body(token),
            Mode::AfterAfterFrameset => self.mode_after_after_frameset(token),
        }
    }

    fn chars_all_ws(s: &str) -> bool {
        s.chars().all(is_ws)
    }

    // ---- initial ----
    fn mode_initial(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) if Self::chars_all_ws(s) => Proc::Done,
            Token::Comment(c) => {
                let doc = self.dom.document;
                self.insert_comment_at(doc, c);
                Proc::Done
            }
            Token::Doctype {
                name,
                public_id,
                system_id,
                force_quirks,
            } => {
                let n = name.clone().unwrap_or_default();
                let node = self.dom.new_node(NodeData::Doctype {
                    name: n.clone(),
                    public_id: public_id.clone().unwrap_or_default(),
                    system_id: system_id.clone().unwrap_or_default(),
                });
                let doc = self.dom.document;
                self.dom.append(doc, node);
                // quirks mode determination
                let pid = public_id.clone().unwrap_or_default();
                let pid_l = pid.to_ascii_lowercase();
                let sid = system_id.clone();
                let sid_l = sid.clone().unwrap_or_default().to_ascii_lowercase();
                let quirks = *force_quirks
                    || n != "html"
                    || QUIRKY_PUBLIC_PREFIXES
                        .iter()
                        .any(|p| pid_l.starts_with(&p.to_ascii_lowercase()))
                    || pid_l == "-//w3o//dtd w3 html strict 3.0//en//"
                    || pid_l == "-/w3c/dtd html 4.0 transitional/en"
                    || pid_l == "html"
                    || sid_l == "http://www.ibm.com/data/dtd/v11/ibmxhtml1-transitional.dtd"
                    || (sid.is_none()
                        && (pid_l.starts_with("-//w3c//dtd html 4.01 frameset//")
                            || pid_l.starts_with("-//w3c//dtd html 4.01 transitional//")));
                let limited = !quirks
                    && (pid_l.starts_with("-//w3c//dtd xhtml 1.0 frameset//")
                        || pid_l.starts_with("-//w3c//dtd xhtml 1.0 transitional//")
                        || (sid.is_some()
                            && (pid_l.starts_with("-//w3c//dtd html 4.01 frameset//")
                                || pid_l.starts_with("-//w3c//dtd html 4.01 transitional//"))));
                self.dom.quirks_mode = if quirks {
                    QuirksMode::Quirks
                } else if limited {
                    QuirksMode::LimitedQuirks
                } else {
                    QuirksMode::NoQuirks
                };
                self.mode = Mode::BeforeHtml;
                Proc::Done
            }
            _ => {
                self.dom.quirks_mode = QuirksMode::Quirks;
                self.mode = Mode::BeforeHtml;
                Proc::Reprocess
            }
        }
    }

    // ---- before html ----
    fn mode_before_html(&mut self, token: &Token) -> Proc {
        match token {
            Token::Doctype { .. } => Proc::Done,
            Token::Comment(c) => {
                let doc = self.dom.document;
                self.insert_comment_at(doc, c);
                Proc::Done
            }
            Token::Chars(s) if Self::chars_all_ws(s) => Proc::Done,
            Token::StartTag { name, .. } if name == "html" => {
                let tag = Self::tag_of(token);
                let el = self.create_element(NS_HTML, &tag);
                let doc = self.dom.document;
                self.dom.append(doc, el);
                self.open.push(el);
                self.mode = Mode::BeforeHead;
                Proc::Done
            }
            Token::EndTag { name }
                if !matches!(name.as_str(), "head" | "body" | "html" | "br") =>
            {
                Proc::Done
            }
            _ => {
                let tag = Tag {
                    name: "html".to_string(),
                    attrs: Vec::new(),
                    self_closing: false,
                };
                let el = self.create_element(NS_HTML, &tag);
                let doc = self.dom.document;
                self.dom.append(doc, el);
                self.open.push(el);
                self.mode = Mode::BeforeHead;
                Proc::Reprocess
            }
        }
    }

    // ---- before head ----
    fn mode_before_head(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) if Self::chars_all_ws(s) => Proc::Done,
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::StartTag { name, .. } if name == "head" => {
                let tag = Self::tag_of(token);
                let el = self.insert_element(&tag);
                self.head = Some(el);
                self.mode = Mode::InHead;
                Proc::Done
            }
            Token::EndTag { name }
                if !matches!(name.as_str(), "head" | "body" | "html" | "br") =>
            {
                Proc::Done
            }
            _ => {
                let el = self.insert_element_named("head");
                self.head = Some(el);
                self.mode = Mode::InHead;
                Proc::Reprocess
            }
        }
    }

    // ---- in head ----
    fn mode_in_head(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) if Self::chars_all_ws(s) => {
                self.insert_text(s);
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } => {
                let tag = Self::tag_of(token);
                match name.as_str() {
                    "html" => self.mode_in_body(token),
                    "base" | "basefont" | "bgsound" | "link" | "meta" => {
                        self.insert_element(&tag);
                        self.pop();
                        Proc::Done
                    }
                    "title" => {
                        self.parse_raw_text(&tag, State::Rcdata);
                        Proc::Done
                    }
                    "noframes" | "style" => {
                        self.parse_raw_text(&tag, State::Rawtext);
                        Proc::Done
                    }
                    "noscript" if self.scripting => {
                        self.parse_raw_text(&tag, State::Rawtext);
                        Proc::Done
                    }
                    "noscript" => {
                        self.insert_element(&tag);
                        self.mode = Mode::InHeadNoscript;
                        Proc::Done
                    }
                    "script" => {
                        let place = self.insertion_place(None);
                        let el = self.create_element(NS_HTML, &tag);
                        self.insert_node_at(place, el);
                        self.open.push(el);
                        self.set_tok_state(State::ScriptData);
                        self.original_mode = self.mode;
                        self.mode = Mode::Text;
                        Proc::Done
                    }
                    "template" => {
                        self.insert_element(&tag);
                        self.push_marker();
                        self.frameset_ok = false;
                        self.mode = Mode::InTemplate;
                        self.template_modes.push(Mode::InTemplate);
                        Proc::Done
                    }
                    "head" => Proc::Done,
                    _ => {
                        self.pop();
                        self.mode = Mode::AfterHead;
                        Proc::Reprocess
                    }
                }
            }
            Token::EndTag { name } => match name.as_str() {
                "head" => {
                    self.pop();
                    self.mode = Mode::AfterHead;
                    Proc::Done
                }
                "body" | "html" | "br" => {
                    self.pop();
                    self.mode = Mode::AfterHead;
                    Proc::Reprocess
                }
                "template" => {
                    if !self.open.iter().any(|&n| self.is_html(n, "template")) {
                        return Proc::Done;
                    }
                    self.generate_implied_end_tags_thoroughly();
                    self.pop_until("template");
                    self.clear_fmt_to_marker();
                    self.template_modes.pop();
                    self.reset_insertion_mode();
                    Proc::Done
                }
                _ => Proc::Done,
            },
            _ => {
                self.pop();
                self.mode = Mode::AfterHead;
                Proc::Reprocess
            }
        }
    }

    // ---- in head noscript ----
    fn mode_in_head_noscript(&mut self, token: &Token) -> Proc {
        match token {
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::EndTag { name } if name == "noscript" => {
                self.pop();
                self.mode = Mode::InHead;
                Proc::Done
            }
            Token::Chars(s) if Self::chars_all_ws(s) => self.mode_in_head(token),
            Token::Comment(_) => self.mode_in_head(token),
            Token::StartTag { name, .. }
                if matches!(
                    name.as_str(),
                    "basefont" | "bgsound" | "link" | "meta" | "noframes" | "style"
                ) =>
            {
                self.mode_in_head(token)
            }
            Token::EndTag { name } if name == "br" => {
                self.pop();
                self.mode = Mode::InHead;
                Proc::Reprocess
            }
            Token::StartTag { name, .. } if name == "head" || name == "noscript" => Proc::Done,
            Token::EndTag { .. } => Proc::Done,
            _ => {
                self.pop();
                self.mode = Mode::InHead;
                Proc::Reprocess
            }
        }
    }

    // ---- after head ----
    fn mode_after_head(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) if Self::chars_all_ws(s) => {
                self.insert_text(s);
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } => {
                let tag = Self::tag_of(token);
                match name.as_str() {
                    "html" => self.mode_in_body(token),
                    "body" => {
                        self.insert_element(&tag);
                        self.frameset_ok = false;
                        self.mode = Mode::InBody;
                        Proc::Done
                    }
                    "frameset" => {
                        self.insert_element(&tag);
                        self.mode = Mode::InFrameset;
                        Proc::Done
                    }
                    "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script"
                    | "style" | "template" | "title" => {
                        let head = self.head.expect("head");
                        self.open.push(head);
                        let r = self.mode_in_head(token);
                        self.remove_from_open(head);
                        r
                    }
                    "head" => Proc::Done,
                    _ => {
                        self.insert_element_named("body");
                        self.mode = Mode::InBody;
                        Proc::Reprocess
                    }
                }
            }
            Token::EndTag { name } => match name.as_str() {
                "template" => self.mode_in_head(token),
                "body" | "html" | "br" => {
                    self.insert_element_named("body");
                    self.mode = Mode::InBody;
                    Proc::Reprocess
                }
                _ => Proc::Done,
            },
            _ => {
                self.insert_element_named("body");
                self.mode = Mode::InBody;
                Proc::Reprocess
            }
        }
    }

    // ---- in body ----
    fn mode_in_body(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                if s.starts_with('\0') {
                    return Proc::Done;
                }
                self.reconstruct_formatting();
                self.insert_text(s);
                if !Self::chars_all_ws(s) {
                    self.frameset_ok = false;
                }
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::Eof => {
                if !self.template_modes.is_empty() {
                    return self.mode_in_template(token);
                }
                self.done = true;
                Proc::Done
            }
            Token::StartTag { name, .. } => self.in_body_start_tag(name.clone(), token),
            Token::EndTag { name } => self.in_body_end_tag(name.clone()),
        }
    }

    fn in_body_start_tag(&mut self, name: String, token: &Token) -> Proc {
        let tag = Self::tag_of(token);
        match name.as_str() {
            "html" => {
                if self.open.iter().any(|&n| self.is_html(n, "template")) {
                    return Proc::Done;
                }
                let html = self.open[0];
                for (n, v) in &tag.attrs {
                    if !self.dom.has_attr(html, n) {
                        if let Some(attrs) = self.dom.attrs_mut(html) {
                            attrs.push(Attr {
                                ns: String::new(),
                                prefix: None,
                                local: n.clone(),
                                value: v.clone(),
                            });
                        }
                    }
                }
                Proc::Done
            }
            "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script" | "style"
            | "template" | "title" => self.mode_in_head(token),
            "body" => {
                if self.open.len() < 2
                    || !self.is_html(self.open[1], "body")
                    || self.open.iter().any(|&n| self.is_html(n, "template"))
                {
                    return Proc::Done;
                }
                self.frameset_ok = false;
                let body = self.open[1];
                for (n, v) in &tag.attrs {
                    if !self.dom.has_attr(body, n) {
                        if let Some(attrs) = self.dom.attrs_mut(body) {
                            attrs.push(Attr {
                                ns: String::new(),
                                prefix: None,
                                local: n.clone(),
                                value: v.clone(),
                            });
                        }
                    }
                }
                Proc::Done
            }
            "frameset" => {
                if self.open.len() < 2 || !self.is_html(self.open[1], "body") {
                    return Proc::Done;
                }
                if !self.frameset_ok {
                    return Proc::Done;
                }
                let body = self.open[1];
                self.dom.detach(body);
                self.open.truncate(1);
                self.insert_element(&tag);
                self.mode = Mode::InFrameset;
                Proc::Done
            }
            "address" | "article" | "aside" | "blockquote" | "center" | "details" | "dialog"
            | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header"
            | "hgroup" | "main" | "menu" | "nav" | "ol" | "p" | "section" | "summary" | "ul" => {
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                Proc::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                if self.current_is_any(HEADINGS) {
                    self.pop();
                }
                self.insert_element(&tag);
                Proc::Done
            }
            "pre" | "listing" => {
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                self.ignore_lf = true;
                self.frameset_ok = false;
                Proc::Done
            }
            "form" => {
                let has_template = self.open.iter().any(|&n| self.is_html(n, "template"));
                if self.form.is_some() && !has_template {
                    return Proc::Done;
                }
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                let el = self.insert_element(&tag);
                if !has_template {
                    self.form = Some(el);
                }
                Proc::Done
            }
            "li" => {
                self.frameset_ok = false;
                let mut i = self.open.len();
                while i > 0 {
                    i -= 1;
                    let node = self.open[i];
                    if self.is_html(node, "li") {
                        self.generate_implied_end_tags(Some("li"));
                        self.pop_until("li");
                        break;
                    }
                    if self.is_special(node) && !self.is_html_any(node, &["address", "div", "p"]) {
                        break;
                    }
                }
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                Proc::Done
            }
            "dd" | "dt" => {
                self.frameset_ok = false;
                let mut i = self.open.len();
                while i > 0 {
                    i -= 1;
                    let node = self.open[i];
                    if self.is_html(node, "dd") {
                        self.generate_implied_end_tags(Some("dd"));
                        self.pop_until("dd");
                        break;
                    }
                    if self.is_html(node, "dt") {
                        self.generate_implied_end_tags(Some("dt"));
                        self.pop_until("dt");
                        break;
                    }
                    if self.is_special(node) && !self.is_html_any(node, &["address", "div", "p"]) {
                        break;
                    }
                }
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                Proc::Done
            }
            "plaintext" => {
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                self.set_tok_state(State::Plaintext);
                Proc::Done
            }
            "button" => {
                if self.in_scope("button") {
                    self.generate_implied_end_tags(None);
                    self.pop_until("button");
                }
                self.reconstruct_formatting();
                self.insert_element(&tag);
                self.frameset_ok = false;
                Proc::Done
            }
            "a" => {
                if let Some((idx, node)) = self.find_fmt_by_name("a") {
                    self.adoption_agency("a");
                    // remove from lists if still present
                    if let Some(i) = self.fmt_index_of(node) {
                        self.fmt.remove(i);
                    } else {
                        let _ = idx;
                    }
                    self.remove_from_open(node);
                }
                self.reconstruct_formatting();
                let el = self.insert_element(&tag);
                self.push_formatting(el, &tag);
                Proc::Done
            }
            "b" | "big" | "code" | "em" | "font" | "i" | "s" | "small" | "strike" | "strong"
            | "tt" | "u" => {
                self.reconstruct_formatting();
                let el = self.insert_element(&tag);
                self.push_formatting(el, &tag);
                Proc::Done
            }
            "nobr" => {
                self.reconstruct_formatting();
                if self.in_scope("nobr") {
                    self.adoption_agency("nobr");
                    self.reconstruct_formatting();
                }
                let el = self.insert_element(&tag);
                self.push_formatting(el, &tag);
                Proc::Done
            }
            "applet" | "marquee" | "object" => {
                self.reconstruct_formatting();
                self.insert_element(&tag);
                self.push_marker();
                self.frameset_ok = false;
                Proc::Done
            }
            "table" => {
                if self.dom.quirks_mode != QuirksMode::Quirks && self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                self.frameset_ok = false;
                self.mode = Mode::InTable;
                Proc::Done
            }
            "area" | "br" | "embed" | "img" | "keygen" | "wbr" => {
                self.reconstruct_formatting();
                self.insert_element(&tag);
                self.pop();
                self.frameset_ok = false;
                Proc::Done
            }
            "input" => {
                self.reconstruct_formatting();
                self.insert_element(&tag);
                self.pop();
                let is_hidden = tag
                    .attrs
                    .iter()
                    .any(|(n, v)| n == "type" && v.eq_ignore_ascii_case("hidden"));
                if !is_hidden {
                    self.frameset_ok = false;
                }
                Proc::Done
            }
            "param" | "source" | "track" => {
                self.insert_element(&tag);
                self.pop();
                Proc::Done
            }
            "hr" => {
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.insert_element(&tag);
                self.pop();
                self.frameset_ok = false;
                Proc::Done
            }
            "image" => {
                let mut t = tag.clone();
                t.name = "img".to_string();
                self.reprocess_token = Some(Token::StartTag {
                    name: t.name,
                    attrs: t.attrs,
                    self_closing: t.self_closing,
                });
                Proc::Reprocess
            }
            "textarea" => {
                self.insert_element(&tag);
                self.ignore_lf = true;
                self.set_tok_state(State::Rcdata);
                self.original_mode = self.mode;
                self.frameset_ok = false;
                self.mode = Mode::Text;
                Proc::Done
            }
            "xmp" => {
                if self.in_button_scope("p") {
                    self.close_p_element();
                }
                self.reconstruct_formatting();
                self.frameset_ok = false;
                self.parse_raw_text(&tag, State::Rawtext);
                Proc::Done
            }
            "iframe" => {
                self.frameset_ok = false;
                self.parse_raw_text(&tag, State::Rawtext);
                Proc::Done
            }
            "noembed" => {
                self.parse_raw_text(&tag, State::Rawtext);
                Proc::Done
            }
            "noscript" if self.scripting => {
                self.parse_raw_text(&tag, State::Rawtext);
                Proc::Done
            }
            "select" => {
                self.reconstruct_formatting();
                self.insert_element(&tag);
                self.frameset_ok = false;
                if matches!(
                    self.mode,
                    Mode::InTable | Mode::InCaption | Mode::InTableBody | Mode::InRow | Mode::InCell
                ) {
                    self.mode = Mode::InSelectInTable;
                } else {
                    self.mode = Mode::InSelect;
                }
                Proc::Done
            }
            "optgroup" | "option" => {
                if self.current_is("option") {
                    self.pop();
                }
                self.reconstruct_formatting();
                self.insert_element(&tag);
                Proc::Done
            }
            "rb" | "rtc" => {
                if self.in_scope("ruby") {
                    self.generate_implied_end_tags(None);
                }
                self.insert_element(&tag);
                Proc::Done
            }
            "rp" | "rt" => {
                if self.in_scope("ruby") {
                    self.generate_implied_end_tags(Some("rtc"));
                }
                self.insert_element(&tag);
                Proc::Done
            }
            "math" => {
                self.reconstruct_formatting();
                let mut t = tag.clone();
                adjust_mathml_attrs(&mut t);
                let el = self.insert_foreign_element(NS_MATHML, &t);
                if t.self_closing {
                    self.pop();
                    let _ = el;
                }
                Proc::Done
            }
            "svg" => {
                self.reconstruct_formatting();
                let mut t = tag.clone();
                adjust_svg_attrs(&mut t);
                self.insert_foreign_element(NS_SVG, &t);
                if t.self_closing {
                    self.pop();
                }
                Proc::Done
            }
            "caption" | "col" | "colgroup" | "frame" | "head" | "tbody" | "td" | "tfoot" | "th"
            | "thead" | "tr" => Proc::Done,
            _ => {
                self.reconstruct_formatting();
                self.insert_element(&tag);
                Proc::Done
            }
        }
    }

    fn close_p_element(&mut self) {
        self.generate_implied_end_tags(Some("p"));
        self.pop_until("p");
    }

    fn in_body_end_tag(&mut self, name: String) -> Proc {
        match name.as_str() {
            "template" => self.mode_in_head(&Token::EndTag { name }),
            "body" => {
                if !self.in_scope("body") {
                    return Proc::Done;
                }
                self.mode = Mode::AfterBody;
                Proc::Done
            }
            "html" => {
                if !self.in_scope("body") {
                    return Proc::Done;
                }
                self.mode = Mode::AfterBody;
                Proc::Reprocess
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details"
            | "dialog" | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer"
            | "header" | "hgroup" | "listing" | "main" | "menu" | "nav" | "ol" | "pre"
            | "section" | "summary" | "ul" => {
                if !self.in_scope(&name) {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&name);
                Proc::Done
            }
            "form" => {
                let has_template = self.open.iter().any(|&n| self.is_html(n, "template"));
                if !has_template {
                    let node = self.form.take();
                    let node = match node {
                        Some(n) => n,
                        None => return Proc::Done,
                    };
                    if !self.node_in_scope(node) {
                        return Proc::Done;
                    }
                    self.generate_implied_end_tags(None);
                    self.remove_from_open(node);
                } else {
                    if !self.in_scope("form") {
                        return Proc::Done;
                    }
                    self.generate_implied_end_tags(None);
                    self.pop_until("form");
                }
                Proc::Done
            }
            "p" => {
                if !self.in_button_scope("p") {
                    self.insert_element_named("p");
                }
                self.close_p_element();
                Proc::Done
            }
            "li" => {
                if !self.in_list_item_scope("li") {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(Some("li"));
                self.pop_until("li");
                Proc::Done
            }
            "dd" | "dt" => {
                if !self.in_scope(&name) {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(Some(&name));
                self.pop_until(&name);
                Proc::Done
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if !self.in_scope_any(HEADINGS) {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until_any(HEADINGS);
                Proc::Done
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small"
            | "strike" | "strong" | "tt" | "u" => {
                self.adoption_agency(&name);
                Proc::Done
            }
            "applet" | "marquee" | "object" => {
                if !self.in_scope(&name) {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(&name);
                self.clear_fmt_to_marker();
                Proc::Done
            }
            "br" => {
                self.reprocess_token = Some(Token::StartTag {
                    name: "br".to_string(),
                    attrs: Vec::new(),
                    self_closing: false,
                });
                Proc::Reprocess
            }
            _ => {
                self.any_other_end_tag(&name);
                Proc::Done
            }
        }
    }

    // ---- text ----
    fn mode_text(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                self.insert_text(s);
                Proc::Done
            }
            Token::Eof => {
                self.pop();
                self.mode = self.original_mode;
                Proc::Reprocess
            }
            Token::EndTag { .. } => {
                self.pop();
                self.mode = self.original_mode;
                Proc::Done
            }
            _ => Proc::Done,
        }
    }

    // ---- in table ----
    fn mode_in_table(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(_)
                if self.current_is_any(&["table", "tbody", "tfoot", "thead", "tr"]) =>
            {
                self.pending_table_text.clear();
                self.pending_table_text_non_ws = false;
                self.original_mode = self.mode;
                self.mode = Mode::InTableText;
                Proc::Reprocess
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } => {
                let tag = Self::tag_of(token);
                match name.as_str() {
                    "caption" => {
                        self.clear_stack_to_table_context();
                        self.push_marker();
                        self.insert_element(&tag);
                        self.mode = Mode::InCaption;
                        Proc::Done
                    }
                    "colgroup" => {
                        self.clear_stack_to_table_context();
                        self.insert_element(&tag);
                        self.mode = Mode::InColumnGroup;
                        Proc::Done
                    }
                    "col" => {
                        self.clear_stack_to_table_context();
                        self.insert_element_named("colgroup");
                        self.mode = Mode::InColumnGroup;
                        Proc::Reprocess
                    }
                    "tbody" | "tfoot" | "thead" => {
                        self.clear_stack_to_table_context();
                        self.insert_element(&tag);
                        self.mode = Mode::InTableBody;
                        Proc::Done
                    }
                    "td" | "th" | "tr" => {
                        self.clear_stack_to_table_context();
                        self.insert_element_named("tbody");
                        self.mode = Mode::InTableBody;
                        Proc::Reprocess
                    }
                    "table" => {
                        if !self.in_table_scope("table") {
                            return Proc::Done;
                        }
                        self.pop_until("table");
                        self.reset_insertion_mode();
                        Proc::Reprocess
                    }
                    "style" | "script" | "template" => self.mode_in_head(token),
                    "input" => {
                        let is_hidden = tag
                            .attrs
                            .iter()
                            .any(|(n, v)| n == "type" && v.eq_ignore_ascii_case("hidden"));
                        if !is_hidden {
                            return self.in_table_anything_else(token);
                        }
                        self.insert_element(&tag);
                        self.pop();
                        Proc::Done
                    }
                    "form" => {
                        if self.open.iter().any(|&n| self.is_html(n, "template"))
                            || self.form.is_some()
                        {
                            return Proc::Done;
                        }
                        let el = self.insert_element(&tag);
                        self.form = Some(el);
                        self.pop();
                        Proc::Done
                    }
                    _ => self.in_table_anything_else(token),
                }
            }
            Token::EndTag { name } => match name.as_str() {
                "table" => {
                    if !self.in_table_scope("table") {
                        return Proc::Done;
                    }
                    self.pop_until("table");
                    self.reset_insertion_mode();
                    Proc::Done
                }
                "body" | "caption" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot"
                | "th" | "thead" | "tr" => Proc::Done,
                "template" => self.mode_in_head(token),
                _ => self.in_table_anything_else(token),
            },
            Token::Eof => self.mode_in_body(token),
            _ => self.in_table_anything_else(token),
        }
    }

    fn in_table_anything_else(&mut self, token: &Token) -> Proc {
        self.foster_parenting = true;
        let r = self.mode_in_body(token);
        self.foster_parenting = false;
        r
    }

    fn clear_stack_to_table_context(&mut self) {
        while let Some(&n) = self.open.last() {
            if self.is_html_any(n, &["table", "template", "html"]) {
                break;
            }
            self.pop();
        }
    }

    fn clear_stack_to_table_body_context(&mut self) {
        while let Some(&n) = self.open.last() {
            if self.is_html_any(n, &["tbody", "tfoot", "thead", "template", "html"]) {
                break;
            }
            self.pop();
        }
    }

    fn clear_stack_to_table_row_context(&mut self) {
        while let Some(&n) = self.open.last() {
            if self.is_html_any(n, &["tr", "template", "html"]) {
                break;
            }
            self.pop();
        }
    }

    // ---- in table text ----
    fn mode_in_table_text(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                if s.starts_with('\0') {
                    return Proc::Done;
                }
                if !Self::chars_all_ws(s) {
                    self.pending_table_text_non_ws = true;
                }
                self.pending_table_text.push_str(s);
                Proc::Done
            }
            _ => {
                let text = std::mem::take(&mut self.pending_table_text);
                if self.pending_table_text_non_ws {
                    self.foster_parenting = true;
                    self.reconstruct_formatting();
                    self.insert_text(&text);
                    self.frameset_ok = false;
                    self.foster_parenting = false;
                } else {
                    self.insert_text(&text);
                }
                self.mode = self.original_mode;
                Proc::Reprocess
            }
        }
    }

    // ---- in caption ----
    fn mode_in_caption(&mut self, token: &Token) -> Proc {
        match token {
            Token::EndTag { name } if name == "caption" => {
                if !self.in_table_scope("caption") {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until("caption");
                self.clear_fmt_to_marker();
                self.mode = Mode::InTable;
                Proc::Done
            }
            Token::StartTag { name, .. }
                if matches!(
                    name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                if !self.in_table_scope("caption") {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until("caption");
                self.clear_fmt_to_marker();
                self.mode = Mode::InTable;
                Proc::Reprocess
            }
            Token::EndTag { name } if name == "table" => {
                if !self.in_table_scope("caption") {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until("caption");
                self.clear_fmt_to_marker();
                self.mode = Mode::InTable;
                Proc::Reprocess
            }
            Token::EndTag { name }
                if matches!(
                    name.as_str(),
                    "body" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th"
                        | "thead" | "tr"
                ) =>
            {
                Proc::Done
            }
            _ => self.mode_in_body(token),
        }
    }

    // ---- in column group ----
    fn mode_in_column_group(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) if Self::chars_all_ws(s) => {
                self.insert_text(s);
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::StartTag { name, .. } if name == "col" => {
                let tag = Self::tag_of(token);
                self.insert_element(&tag);
                self.pop();
                Proc::Done
            }
            Token::EndTag { name } if name == "colgroup" => {
                if !self.current_is("colgroup") {
                    return Proc::Done;
                }
                self.pop();
                self.mode = Mode::InTable;
                Proc::Done
            }
            Token::EndTag { name } if name == "col" => Proc::Done,
            Token::StartTag { name, .. } if name == "template" => self.mode_in_head(token),
            Token::EndTag { name } if name == "template" => self.mode_in_head(token),
            Token::Eof => self.mode_in_body(token),
            _ => {
                if !self.current_is("colgroup") {
                    return Proc::Done;
                }
                self.pop();
                self.mode = Mode::InTable;
                Proc::Reprocess
            }
        }
    }

    // ---- in table body ----
    fn mode_in_table_body(&mut self, token: &Token) -> Proc {
        match token {
            Token::StartTag { name, .. } if name == "tr" => {
                let tag = Self::tag_of(token);
                self.clear_stack_to_table_body_context();
                self.insert_element(&tag);
                self.mode = Mode::InRow;
                Proc::Done
            }
            Token::StartTag { name, .. } if name == "th" || name == "td" => {
                self.clear_stack_to_table_body_context();
                self.insert_element_named("tr");
                self.mode = Mode::InRow;
                Proc::Reprocess
            }
            Token::EndTag { name } if matches!(name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.in_table_scope(name) {
                    return Proc::Done;
                }
                self.clear_stack_to_table_body_context();
                self.pop();
                self.mode = Mode::InTable;
                Proc::Done
            }
            Token::StartTag { name, .. }
                if matches!(
                    name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead"
                ) =>
            {
                if !self.in_table_scope_any(&["tbody", "thead", "tfoot"]) {
                    return Proc::Done;
                }
                self.clear_stack_to_table_body_context();
                self.pop();
                self.mode = Mode::InTable;
                Proc::Reprocess
            }
            Token::EndTag { name } if name == "table" => {
                if !self.in_table_scope_any(&["tbody", "thead", "tfoot"]) {
                    return Proc::Done;
                }
                self.clear_stack_to_table_body_context();
                self.pop();
                self.mode = Mode::InTable;
                Proc::Reprocess
            }
            Token::EndTag { name }
                if matches!(
                    name.as_str(),
                    "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th" | "tr"
                ) =>
            {
                Proc::Done
            }
            _ => self.mode_in_table(token),
        }
    }

    // ---- in row ----
    fn mode_in_row(&mut self, token: &Token) -> Proc {
        match token {
            Token::StartTag { name, .. } if name == "th" || name == "td" => {
                let tag = Self::tag_of(token);
                self.clear_stack_to_table_row_context();
                self.insert_element(&tag);
                self.mode = Mode::InCell;
                self.push_marker();
                Proc::Done
            }
            Token::EndTag { name } if name == "tr" => {
                if !self.in_table_scope("tr") {
                    return Proc::Done;
                }
                self.clear_stack_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Proc::Done
            }
            Token::StartTag { name, .. }
                if matches!(
                    name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" | "tr"
                ) =>
            {
                if !self.in_table_scope("tr") {
                    return Proc::Done;
                }
                self.clear_stack_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Proc::Reprocess
            }
            Token::EndTag { name } if name == "table" => {
                if !self.in_table_scope("tr") {
                    return Proc::Done;
                }
                self.clear_stack_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Proc::Reprocess
            }
            Token::EndTag { name } if matches!(name.as_str(), "tbody" | "tfoot" | "thead") => {
                if !self.in_table_scope(name) {
                    return Proc::Done;
                }
                if !self.in_table_scope("tr") {
                    return Proc::Done;
                }
                self.clear_stack_to_table_row_context();
                self.pop();
                self.mode = Mode::InTableBody;
                Proc::Reprocess
            }
            Token::EndTag { name }
                if matches!(
                    name.as_str(),
                    "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th"
                ) =>
            {
                Proc::Done
            }
            _ => self.mode_in_table(token),
        }
    }

    // ---- in cell ----
    fn mode_in_cell(&mut self, token: &Token) -> Proc {
        match token {
            Token::EndTag { name } if name == "td" || name == "th" => {
                if !self.in_table_scope(name) {
                    return Proc::Done;
                }
                self.generate_implied_end_tags(None);
                self.pop_until(name);
                self.clear_fmt_to_marker();
                self.mode = Mode::InRow;
                Proc::Done
            }
            Token::StartTag { name, .. }
                if matches!(
                    name.as_str(),
                    "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr"
                ) =>
            {
                if !self.in_table_scope_any(&["td", "th"]) {
                    return Proc::Done;
                }
                self.close_cell();
                Proc::Reprocess
            }
            Token::EndTag { name }
                if matches!(
                    name.as_str(),
                    "body" | "caption" | "col" | "colgroup" | "html"
                ) =>
            {
                Proc::Done
            }
            Token::EndTag { name }
                if matches!(name.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr") =>
            {
                if !self.in_table_scope(name) {
                    return Proc::Done;
                }
                self.close_cell();
                Proc::Reprocess
            }
            _ => self.mode_in_body(token),
        }
    }

    fn close_cell(&mut self) {
        self.generate_implied_end_tags(None);
        self.pop_until_any(&["td", "th"]);
        self.clear_fmt_to_marker();
        self.mode = Mode::InRow;
    }

    // ---- in select ----
    fn mode_in_select(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                if s.starts_with('\0') {
                    return Proc::Done;
                }
                self.insert_text(s);
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } => {
                let tag = Self::tag_of(token);
                match name.as_str() {
                    "html" => self.mode_in_body(token),
                    "option" => {
                        if self.current_is("option") {
                            self.pop();
                        }
                        self.insert_element(&tag);
                        Proc::Done
                    }
                    "optgroup" => {
                        if self.current_is("option") {
                            self.pop();
                        }
                        if self.current_is("optgroup") {
                            self.pop();
                        }
                        self.insert_element(&tag);
                        Proc::Done
                    }
                    "hr" => {
                        if self.current_is("option") {
                            self.pop();
                        }
                        if self.current_is("optgroup") {
                            self.pop();
                        }
                        self.insert_element(&tag);
                        self.pop();
                        Proc::Done
                    }
                    "select" => {
                        if !self.in_select_scope("select") {
                            return Proc::Done;
                        }
                        self.pop_until("select");
                        self.reset_insertion_mode();
                        Proc::Done
                    }
                    "input" | "keygen" | "textarea" => {
                        if !self.in_select_scope("select") {
                            return Proc::Done;
                        }
                        self.pop_until("select");
                        self.reset_insertion_mode();
                        Proc::Reprocess
                    }
                    "script" | "template" => self.mode_in_head(token),
                    _ => Proc::Done,
                }
            }
            Token::EndTag { name } => match name.as_str() {
                "optgroup" => {
                    if self.current_is("option") && self.open.len() >= 2 {
                        let prev = self.open[self.open.len() - 2];
                        if self.is_html(prev, "optgroup") {
                            self.pop();
                        }
                    }
                    if self.current_is("optgroup") {
                        self.pop();
                    }
                    Proc::Done
                }
                "option" => {
                    if self.current_is("option") {
                        self.pop();
                    }
                    Proc::Done
                }
                "select" => {
                    if !self.in_select_scope("select") {
                        return Proc::Done;
                    }
                    self.pop_until("select");
                    self.reset_insertion_mode();
                    Proc::Done
                }
                "template" => self.mode_in_head(token),
                _ => Proc::Done,
            },
            Token::Eof => self.mode_in_body(token),
        }
    }

    // ---- in select in table ----
    fn mode_in_select_in_table(&mut self, token: &Token) -> Proc {
        match token {
            Token::StartTag { name, .. }
                if matches!(
                    name.as_str(),
                    "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th"
                ) =>
            {
                self.pop_until("select");
                self.reset_insertion_mode();
                Proc::Reprocess
            }
            Token::EndTag { name }
                if matches!(
                    name.as_str(),
                    "caption" | "table" | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th"
                ) =>
            {
                if !self.in_table_scope(name) {
                    return Proc::Done;
                }
                self.pop_until("select");
                self.reset_insertion_mode();
                Proc::Reprocess
            }
            _ => self.mode_in_select(token),
        }
    }

    // ---- in template ----
    fn mode_in_template(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(_) | Token::Comment(_) | Token::Doctype { .. } => self.mode_in_body(token),
            Token::StartTag { name, .. } => match name.as_str() {
                "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script"
                | "style" | "template" | "title" => self.mode_in_head(token),
                "caption" | "colgroup" | "tbody" | "tfoot" | "thead" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InTable);
                    self.mode = Mode::InTable;
                    Proc::Reprocess
                }
                "col" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InColumnGroup);
                    self.mode = Mode::InColumnGroup;
                    Proc::Reprocess
                }
                "tr" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InTableBody);
                    self.mode = Mode::InTableBody;
                    Proc::Reprocess
                }
                "td" | "th" => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InRow);
                    self.mode = Mode::InRow;
                    Proc::Reprocess
                }
                _ => {
                    self.template_modes.pop();
                    self.template_modes.push(Mode::InBody);
                    self.mode = Mode::InBody;
                    Proc::Reprocess
                }
            },
            Token::EndTag { name } if name == "template" => self.mode_in_head(token),
            Token::EndTag { .. } => Proc::Done,
            Token::Eof => {
                if !self.open.iter().any(|&n| self.is_html(n, "template")) {
                    self.done = true;
                    return Proc::Done;
                }
                self.pop_until("template");
                self.clear_fmt_to_marker();
                self.template_modes.pop();
                self.reset_insertion_mode();
                Proc::Reprocess
            }
        }
    }

    // ---- after body ----
    fn mode_after_body(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) if Self::chars_all_ws(s) => self.mode_in_body(token),
            Token::Comment(c) => {
                let html = self.open[0];
                self.insert_comment_at(html, c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::EndTag { name } if name == "html" => {
                self.mode = Mode::AfterAfterBody;
                Proc::Done
            }
            Token::Eof => {
                self.done = true;
                Proc::Done
            }
            _ => {
                self.mode = Mode::InBody;
                Proc::Reprocess
            }
        }
    }

    // ---- in frameset ----
    fn mode_in_frameset(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                // insert whitespace characters only
                let ws: String = s.chars().filter(|&c| is_ws(c)).collect();
                if !ws.is_empty() {
                    self.insert_text(&ws);
                }
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } => {
                let tag = Self::tag_of(token);
                match name.as_str() {
                    "html" => self.mode_in_body(token),
                    "frameset" => {
                        self.insert_element(&tag);
                        Proc::Done
                    }
                    "frame" => {
                        self.insert_element(&tag);
                        self.pop();
                        Proc::Done
                    }
                    "noframes" => self.mode_in_head(token),
                    _ => Proc::Done,
                }
            }
            Token::EndTag { name } if name == "frameset" => {
                if self.open.len() == 1 && self.current_is("html") {
                    return Proc::Done;
                }
                self.pop();
                if !self.current_is("frameset") {
                    self.mode = Mode::AfterFrameset;
                }
                Proc::Done
            }
            Token::Eof => {
                self.done = true;
                Proc::Done
            }
            _ => Proc::Done,
        }
    }

    // ---- after frameset ----
    fn mode_after_frameset(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                let ws: String = s.chars().filter(|&c| is_ws(c)).collect();
                if !ws.is_empty() {
                    self.insert_text(&ws);
                }
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::EndTag { name } if name == "html" => {
                self.mode = Mode::AfterAfterFrameset;
                Proc::Done
            }
            Token::StartTag { name, .. } if name == "noframes" => self.mode_in_head(token),
            Token::Eof => {
                self.done = true;
                Proc::Done
            }
            _ => Proc::Done,
        }
    }

    // ---- after after body ----
    fn mode_after_after_body(&mut self, token: &Token) -> Proc {
        match token {
            Token::Comment(c) => {
                let doc = self.dom.document;
                self.insert_comment_at(doc, c);
                Proc::Done
            }
            Token::Doctype { .. } => self.mode_in_body(token),
            Token::Chars(s) if Self::chars_all_ws(s) => self.mode_in_body(token),
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::Eof => {
                self.done = true;
                Proc::Done
            }
            _ => {
                self.mode = Mode::InBody;
                Proc::Reprocess
            }
        }
    }

    // ---- after after frameset ----
    fn mode_after_after_frameset(&mut self, token: &Token) -> Proc {
        match token {
            Token::Comment(c) => {
                let doc = self.dom.document;
                self.insert_comment_at(doc, c);
                Proc::Done
            }
            Token::Doctype { .. } => self.mode_in_body(token),
            Token::Chars(s) if Self::chars_all_ws(s) => self.mode_in_body(token),
            Token::StartTag { name, .. } if name == "html" => self.mode_in_body(token),
            Token::StartTag { name, .. } if name == "noframes" => self.mode_in_head(token),
            Token::Eof => {
                self.done = true;
                Proc::Done
            }
            _ => Proc::Done,
        }
    }

    // ---- foreign content ----
    fn foreign_content(&mut self, token: &Token) -> Proc {
        match token {
            Token::Chars(s) => {
                let text: String = s.chars().map(|c| if c == '\0' { '\u{fffd}' } else { c }).collect();
                self.insert_text(&text);
                if !Self::chars_all_ws(s) {
                    self.frameset_ok = false;
                }
                Proc::Done
            }
            Token::Comment(c) => {
                self.insert_comment(c);
                Proc::Done
            }
            Token::Doctype { .. } => Proc::Done,
            Token::StartTag { name, attrs, .. } => {
                let breakout = matches!(
                    name.as_str(),
                    "b" | "big" | "blockquote" | "body" | "br" | "center" | "code" | "dd" | "div"
                        | "dl" | "dt" | "em" | "embed" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
                        | "head" | "hr" | "i" | "img" | "li" | "listing" | "menu" | "meta"
                        | "nobr" | "ol" | "p" | "pre" | "ruby" | "s" | "small" | "span"
                        | "strong" | "strike" | "sub" | "sup" | "table" | "tt" | "u" | "ul"
                        | "var"
                ) || (name == "font"
                    && attrs
                        .iter()
                        .any(|(n, _)| matches!(n.as_str(), "color" | "face" | "size")));
                if breakout {
                    // pop until HTML element or integration point
                    loop {
                        let cur = match self.open.last() {
                            Some(&c) => c,
                            None => break,
                        };
                        let is_html = self
                            .dom
                            .element_name(cur)
                            .map_or(false, |(ns, _)| ns == NS_HTML);
                        if is_html
                            || self.is_mathml_text_integration_point(cur)
                            || self.is_html_integration_point(cur)
                        {
                            break;
                        }
                        self.pop();
                    }
                    return Proc::Reprocess;
                }
                let acn = self.adjusted_current().unwrap();
                let (ns, _) = self.dom.element_name(acn).unwrap();
                let ns = ns.to_string();
                let mut tag = Self::tag_of(token);
                if ns == NS_MATHML {
                    adjust_mathml_attrs(&mut tag);
                } else if ns == NS_SVG {
                    tag.name = svg_adjust_tag(&tag.name).to_string();
                    adjust_svg_attrs(&mut tag);
                }
                self.insert_foreign_element(&ns, &tag);
                if tag.self_closing {
                    self.pop();
                }
                Proc::Done
            }
            Token::EndTag { name } => {
                let mut i = self.open.len() - 1;
                let mut node = self.open[i];
                if self.name_of(node).to_ascii_lowercase() != *name {
                    // parse error
                }
                loop {
                    if i == 0 {
                        break;
                    }
                    if self.name_of(node).to_ascii_lowercase() == *name {
                        self.open.truncate(i);
                        break;
                    }
                    i -= 1;
                    node = self.open[i];
                    let is_html = self
                        .dom
                        .element_name(node)
                        .map_or(false, |(ns, _)| ns == NS_HTML);
                    if is_html {
                        // process according to current insertion mode
                        return self.process_in_mode(self.mode, token);
                    }
                }
                Proc::Done
            }
            Token::Eof => self.process_in_mode(self.mode, token),
        }
    }
}

fn adjust_mathml_attrs(tag: &mut Tag) {
    for (n, _) in tag.attrs.iter_mut() {
        if n == "definitionurl" {
            *n = "definitionURL".to_string();
        }
    }
}

fn adjust_svg_attrs(tag: &mut Tag) {
    for (n, _) in tag.attrs.iter_mut() {
        let adj = svg_adjust_attr(n);
        if adj != n {
            *n = adj.to_string();
        }
    }
}
