//! CSS tokenizer (cssparser-compatible) and stylesheet processing.

#[derive(Clone, Debug, PartialEq)]
pub enum Tok {
    Ident(String),
    AtKeyword(String),
    Hash(String),
    IdHash(String),
    QuotedString(String),
    UnquotedUrl(String),
    Delim(char),
    Number {
        has_sign: bool,
        value: f32,
    },
    Percentage {
        has_sign: bool,
        unit_value: f32,
    },
    Dimension {
        has_sign: bool,
        value: f32,
        unit: String,
    },
    WhiteSpace(String),
    Comment(String),
    Colon,
    Semicolon,
    Comma,
    IncludeMatch,
    DashMatch,
    PrefixMatch,
    SuffixMatch,
    SubstringMatch,
    Cdo,
    Cdc,
    Function(String),
    ParenthesisBlock,
    SquareBracketBlock,
    CurlyBracketBlock,
    BadUrl(String),
    BadString(String),
    CloseParenthesis,
    CloseSquareBracket,
    CloseCurlyBracket,
}

pub struct CssTokenizer<'a> {
    input: &'a str,
    pos: usize,
}

fn is_name_start(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '_' || !c.is_ascii()
}

fn is_name_char(c: char) -> bool {
    is_name_start(c) || c.is_ascii_digit() || c == '-'
}

fn is_ws(c: char) -> bool {
    matches!(c, ' ' | '\t' | '\n' | '\r' | '\u{c}')
}

impl<'a> CssTokenizer<'a> {
    pub fn new(input: &'a str) -> Self {
        CssTokenizer { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn peek_at(&self, n: usize) -> Option<char> {
        self.input[self.pos..].chars().nth(n)
    }

    fn advance(&mut self, n_chars: usize) {
        for _ in 0..n_chars {
            if let Some(c) = self.peek() {
                self.pos += c.len_utf8();
            }
        }
    }

    fn is_eof(&self) -> bool {
        self.pos >= self.input.len()
    }

    fn starts_with(&self, s: &str) -> bool {
        self.input[self.pos..].starts_with(s)
    }

    fn is_valid_escape_at(&self, n: usize) -> bool {
        self.peek_at(n) == Some('\\')
            && match self.peek_at(n + 1) {
                Some('\n') | Some('\r') | Some('\u{c}') | None => false,
                Some(_) => true,
            }
    }

    fn would_start_ident_at(&self, n: usize) -> bool {
        match self.peek_at(n) {
            Some('-') => match self.peek_at(n + 1) {
                Some('-') => true,
                Some(c) if is_name_start(c) => true,
                _ => self.is_valid_escape_at(n + 1),
            },
            Some(c) if is_name_start(c) => true,
            Some('\\') => self.is_valid_escape_at(n),
            _ => false,
        }
    }

    fn would_start_number_at(&self, n: usize) -> bool {
        match self.peek_at(n) {
            Some('+') | Some('-') => match self.peek_at(n + 1) {
                Some(c) if c.is_ascii_digit() => true,
                Some('.') => matches!(self.peek_at(n + 2), Some(c) if c.is_ascii_digit()),
                _ => false,
            },
            Some('.') => matches!(self.peek_at(n + 1), Some(c) if c.is_ascii_digit()),
            Some(c) if c.is_ascii_digit() => true,
            _ => false,
        }
    }

    pub fn next_token(&mut self) -> Option<Tok> {
        let c = self.peek()?;
        let tok = match c {
            '\t' | '\n' | ' ' | '\r' | '\u{c}' => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if is_ws(c) {
                        self.advance(1);
                    } else {
                        break;
                    }
                }
                Tok::WhiteSpace(self.input[start..self.pos].to_string())
            }
            '"' | '\'' => self.consume_string(c),
            '#' => {
                self.advance(1);
                if matches!(self.peek(), Some(c) if is_name_char(c)) || self.is_valid_escape_at(0) {
                    if self.would_start_ident_at(0) {
                        Tok::IdHash(self.consume_name())
                    } else {
                        Tok::Hash(self.consume_name())
                    }
                } else {
                    Tok::Delim('#')
                }
            }
            '$' => {
                if self.peek_at(1) == Some('=') {
                    self.advance(2);
                    Tok::SuffixMatch
                } else {
                    self.advance(1);
                    Tok::Delim('$')
                }
            }
            '(' => {
                self.advance(1);
                Tok::ParenthesisBlock
            }
            ')' => {
                self.advance(1);
                Tok::CloseParenthesis
            }
            '*' => {
                if self.peek_at(1) == Some('=') {
                    self.advance(2);
                    Tok::SubstringMatch
                } else {
                    self.advance(1);
                    Tok::Delim('*')
                }
            }
            '+' => {
                if self.would_start_number_at(0) {
                    self.consume_numeric()
                } else {
                    self.advance(1);
                    Tok::Delim('+')
                }
            }
            ',' => {
                self.advance(1);
                Tok::Comma
            }
            '-' => {
                if self.would_start_number_at(0) {
                    self.consume_numeric()
                } else if self.starts_with("-->") {
                    self.advance(3);
                    Tok::Cdc
                } else if self.would_start_ident_at(0) {
                    self.consume_ident_like()
                } else {
                    self.advance(1);
                    Tok::Delim('-')
                }
            }
            '.' => {
                if self.would_start_number_at(0) {
                    self.consume_numeric()
                } else {
                    self.advance(1);
                    Tok::Delim('.')
                }
            }
            '/' => {
                if self.peek_at(1) == Some('*') {
                    self.advance(2);
                    let start = self.pos;
                    match self.input[self.pos..].find("*/") {
                        Some(i) => {
                            let s = self.input[start..start + i].to_string();
                            self.pos = start + i + 2;
                            Tok::Comment(s)
                        }
                        None => {
                            let s = self.input[start..].to_string();
                            self.pos = self.input.len();
                            Tok::Comment(s)
                        }
                    }
                } else {
                    self.advance(1);
                    Tok::Delim('/')
                }
            }
            '0'..='9' => self.consume_numeric(),
            ':' => {
                self.advance(1);
                Tok::Colon
            }
            ';' => {
                self.advance(1);
                Tok::Semicolon
            }
            '<' => {
                if self.starts_with("<!--") {
                    self.advance(4);
                    Tok::Cdo
                } else {
                    self.advance(1);
                    Tok::Delim('<')
                }
            }
            '@' => {
                self.advance(1);
                if self.would_start_ident_at(0) {
                    Tok::AtKeyword(self.consume_name())
                } else {
                    Tok::Delim('@')
                }
            }
            '[' => {
                self.advance(1);
                Tok::SquareBracketBlock
            }
            '\\' => {
                if self.is_valid_escape_at(0) {
                    self.consume_ident_like()
                } else {
                    self.advance(1);
                    Tok::Delim('\\')
                }
            }
            ']' => {
                self.advance(1);
                Tok::CloseSquareBracket
            }
            '^' => {
                if self.peek_at(1) == Some('=') {
                    self.advance(2);
                    Tok::PrefixMatch
                } else {
                    self.advance(1);
                    Tok::Delim('^')
                }
            }
            '{' => {
                self.advance(1);
                Tok::CurlyBracketBlock
            }
            '|' => {
                if self.peek_at(1) == Some('=') {
                    self.advance(2);
                    Tok::DashMatch
                } else {
                    self.advance(1);
                    Tok::Delim('|')
                }
            }
            '}' => {
                self.advance(1);
                Tok::CloseCurlyBracket
            }
            '~' => {
                if self.peek_at(1) == Some('=') {
                    self.advance(2);
                    Tok::IncludeMatch
                } else {
                    self.advance(1);
                    Tok::Delim('~')
                }
            }
            c if is_name_start(c) => self.consume_ident_like(),
            c => {
                self.advance(1);
                Tok::Delim(c)
            }
        };
        Some(tok)
    }

    fn consume_escape(&mut self) -> char {
        // assumes backslash already consumed
        match self.peek() {
            None => '\u{fffd}',
            Some(c) if c.is_ascii_hexdigit() => {
                let mut value: u32 = 0;
                let mut n = 0;
                while n < 6 {
                    match self.peek() {
                        Some(h) if h.is_ascii_hexdigit() => {
                            value = value * 16 + h.to_digit(16).unwrap();
                            self.advance(1);
                            n += 1;
                        }
                        _ => break,
                    }
                }
                // consume one whitespace
                match self.peek() {
                    Some('\r') => {
                        self.advance(1);
                        if self.peek() == Some('\n') {
                            self.advance(1);
                        }
                    }
                    Some(c) if is_ws(c) => self.advance(1),
                    _ => {}
                }
                if value == 0 || (0xD800..=0xDFFF).contains(&value) || value > 0x10FFFF {
                    '\u{fffd}'
                } else {
                    char::from_u32(value).unwrap_or('\u{fffd}')
                }
            }
            Some(c) => {
                self.advance(1);
                c
            }
        }
    }

    fn consume_name(&mut self) -> String {
        let mut out = String::new();
        loop {
            match self.peek() {
                Some(c) if is_name_char(c) => {
                    out.push(if c == '\0' { '\u{fffd}' } else { c });
                    self.advance(1);
                }
                Some('\\') if self.is_valid_escape_at(0) => {
                    self.advance(1);
                    out.push(self.consume_escape());
                }
                Some('\0') => {
                    out.push('\u{fffd}');
                    self.advance(1);
                }
                _ => break,
            }
        }
        out
    }

    fn consume_string(&mut self, quote: char) -> Tok {
        self.advance(1);
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Tok::QuotedString(out),
                Some(c) if c == quote => {
                    self.advance(1);
                    return Tok::QuotedString(out);
                }
                Some('\n') | Some('\r') | Some('\u{c}') => {
                    return Tok::BadString(out);
                }
                Some('\\') => {
                    self.advance(1);
                    match self.peek() {
                        None => {}
                        Some('\n') | Some('\u{c}') => self.advance(1),
                        Some('\r') => {
                            self.advance(1);
                            if self.peek() == Some('\n') {
                                self.advance(1);
                            }
                        }
                        Some(_) => out.push(self.consume_escape()),
                    }
                }
                Some('\0') => {
                    out.push('\u{fffd}');
                    self.advance(1);
                }
                Some(c) => {
                    out.push(c);
                    self.advance(1);
                }
            }
        }
    }

    fn consume_numeric(&mut self) -> Tok {
        let mut has_sign = false;
        let mut sign = 1.0f64;
        match self.peek() {
            Some('-') => {
                has_sign = true;
                sign = -1.0;
                self.advance(1);
            }
            Some('+') => {
                has_sign = true;
                self.advance(1);
            }
            _ => {}
        }
        let mut integral: f64 = 0.0;
        while let Some(c) = self.peek() {
            if let Some(d) = c.to_digit(10) {
                integral = integral * 10.0 + d as f64;
                self.advance(1);
            } else {
                break;
            }
        }
        let mut is_integer = true;
        let mut fractional: f64 = 0.0;
        if self.peek() == Some('.') && matches!(self.peek_at(1), Some(c) if c.is_ascii_digit()) {
            is_integer = false;
            self.advance(1);
            let mut factor = 0.1f64;
            while let Some(c) = self.peek() {
                if let Some(d) = c.to_digit(10) {
                    fractional += d as f64 * factor;
                    factor *= 0.1;
                    self.advance(1);
                } else {
                    break;
                }
            }
        }
        let mut value = sign * (integral + fractional);
        if matches!(self.peek(), Some('e') | Some('E')) {
            let exp_start_ok = match self.peek_at(1) {
                Some(c) if c.is_ascii_digit() => true,
                Some('+') | Some('-') => matches!(self.peek_at(2), Some(c) if c.is_ascii_digit()),
                _ => false,
            };
            if exp_start_ok {
                is_integer = false;
                self.advance(1);
                let mut esign = 1.0f64;
                match self.peek() {
                    Some('-') => {
                        esign = -1.0;
                        self.advance(1);
                    }
                    Some('+') => self.advance(1),
                    _ => {}
                }
                let mut exponent: f64 = 0.0;
                while let Some(c) = self.peek() {
                    if let Some(d) = c.to_digit(10) {
                        exponent = exponent * 10.0 + d as f64;
                        self.advance(1);
                    } else {
                        break;
                    }
                }
                value *= f64::powf(10.0, esign * exponent);
            }
        }
        let _ = is_integer;
        if self.peek() == Some('%') {
            self.advance(1);
            return Tok::Percentage {
                has_sign,
                unit_value: (value / 100.0) as f32,
            };
        }
        if self.would_start_ident_at(0) {
            let unit = self.consume_name();
            return Tok::Dimension {
                has_sign,
                value: value as f32,
                unit,
            };
        }
        Tok::Number {
            has_sign,
            value: value as f32,
        }
    }

    fn consume_ident_like(&mut self) -> Tok {
        let name = self.consume_name();
        if self.peek() == Some('(') {
            self.advance(1);
            if name.eq_ignore_ascii_case("url") {
                return self.consume_unquoted_url(name);
            }
            return Tok::Function(name);
        }
        Tok::Ident(name)
    }

    fn consume_unquoted_url(&mut self, fn_name: String) -> Tok {
        // positioned right after "url("
        let save = self.pos;
        // skip whitespace
        while let Some(c) = self.peek() {
            if is_ws(c) {
                self.advance(1);
            } else {
                break;
            }
        }
        match self.peek() {
            Some('"') | Some('\'') => {
                self.pos = save;
                return Tok::Function(fn_name);
            }
            Some(')') => {
                self.advance(1);
                return Tok::UnquotedUrl(String::new());
            }
            None => {
                return Tok::UnquotedUrl(String::new());
            }
            _ => {}
        }
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Tok::UnquotedUrl(out),
                Some(')') => {
                    self.advance(1);
                    return Tok::UnquotedUrl(out);
                }
                Some(c) if is_ws(c) => {
                    // only whitespace allowed before ')'
                    while let Some(c) = self.peek() {
                        if is_ws(c) {
                            self.advance(1);
                        } else {
                            break;
                        }
                    }
                    match self.peek() {
                        Some(')') => {
                            self.advance(1);
                            return Tok::UnquotedUrl(out);
                        }
                        None => return Tok::UnquotedUrl(out),
                        _ => return self.consume_bad_url(out),
                    }
                }
                Some('"') | Some('\'') | Some('(') => return self.consume_bad_url(out),
                Some(c) if (c as u32) < 0x20 && c != '\0' || c == '\u{7f}' => {
                    return self.consume_bad_url(out)
                }
                Some('\\') => {
                    if self.is_valid_escape_at(0) {
                        self.advance(1);
                        out.push(self.consume_escape());
                    } else {
                        return self.consume_bad_url(out);
                    }
                }
                Some('\0') => {
                    out.push('\u{fffd}');
                    self.advance(1);
                }
                Some(c) => {
                    out.push(c);
                    self.advance(1);
                }
            }
        }
    }

    fn consume_bad_url(&mut self, mut out: String) -> Tok {
        loop {
            match self.peek() {
                None => return Tok::BadUrl(out),
                Some(')') => {
                    self.advance(1);
                    return Tok::BadUrl(out);
                }
                Some('\\') => {
                    self.advance(1);
                    if let Some(c) = self.peek() {
                        out.push(c);
                        self.advance(1);
                    }
                }
                Some(c) => {
                    out.push(c);
                    self.advance(1);
                }
            }
        }
    }
}

pub fn tokenize(input: &str) -> Vec<Tok> {
    let mut t = CssTokenizer::new(input);
    let mut out = Vec::new();
    while let Some(tok) = t.next_token() {
        out.push(tok);
    }
    out
}

// ---------- serialization ----------

fn hex_escape(b: u8, out: &mut String) {
    out.push('\\');
    out.push_str(&format!("{:x}", b));
    out.push(' ');
}

fn char_escape(b: u8, out: &mut String) {
    out.push('\\');
    out.push(b as char);
}

pub fn serialize_name(value: &str, out: &mut String) {
    let bytes = value.as_bytes();
    let mut chunk_start = 0;
    for (i, &b) in bytes.iter().enumerate() {
        let escaped: Option<&str> = match b {
            b'0'..=b'9' | b'A'..=b'Z' | b'a'..=b'z' | b'_' | b'-' => continue,
            _ if !b.is_ascii() => continue,
            b'\0' => Some("\u{fffd}"),
            _ => None,
        };
        out.push_str(&value[chunk_start..i]);
        if let Some(e) = escaped {
            out.push_str(e);
        } else if (0x01..=0x1f).contains(&b) || b == 0x7f {
            hex_escape(b, out);
        } else {
            char_escape(b, out);
        }
        chunk_start = i + 1;
    }
    out.push_str(&value[chunk_start..]);
}

pub fn serialize_identifier(value: &str, out: &mut String) {
    if value.is_empty() {
        return;
    }
    if value.starts_with("--") {
        out.push_str("--");
        serialize_name(&value[2..], out);
    } else if value == "-" {
        out.push_str("\\-");
    } else {
        let mut v = value;
        if v.as_bytes()[0] == b'-' {
            out.push('-');
            v = &v[1..];
        }
        if let Some(&d @ b'0'..=b'9') = v.as_bytes().first() {
            hex_escape(d, out);
            v = &v[1..];
        }
        serialize_name(v, out);
    }
}

pub fn serialize_string(value: &str, out: &mut String) {
    out.push('"');
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\0' => out.push('\u{fffd}'),
            c if (c as u32) >= 0x01 && (c as u32) <= 0x1f || c as u32 == 0x7f => {
                hex_escape(c as u8, out);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

fn serialize_unquoted_url(value: &str, out: &mut String) {
    let bytes = value.as_bytes();
    let mut chunk_start = 0;
    for (i, &b) in bytes.iter().enumerate() {
        let hex = match b {
            0..=b' ' | 0x7f => true,
            b'(' | b')' | b'"' | b'\'' | b'\\' => false,
            _ => continue,
        };
        out.push_str(&value[chunk_start..i]);
        if hex {
            hex_escape(b, out);
        } else {
            char_escape(b, out);
        }
        chunk_start = i + 1;
    }
    out.push_str(&value[chunk_start..]);
}

fn write_numeric(value: f32, has_sign: bool, out: &mut String) {
    if has_sign && value >= 0.0 {
        out.push('+');
    }
    out.push_str(&format!("{}", value));
}

pub fn tok_to_css(tok: &Tok) -> String {
    let mut out = String::new();
    match tok {
        Tok::Ident(v) => serialize_identifier(v, &mut out),
        Tok::AtKeyword(v) => {
            out.push('@');
            serialize_identifier(v, &mut out);
        }
        Tok::Hash(v) => {
            out.push('#');
            serialize_name(v, &mut out);
        }
        Tok::IdHash(v) => {
            out.push('#');
            serialize_identifier(v, &mut out);
        }
        Tok::QuotedString(v) => serialize_string(v, &mut out),
        Tok::UnquotedUrl(v) => {
            out.push_str("url(");
            serialize_unquoted_url(v, &mut out);
            out.push(')');
        }
        Tok::Delim(c) => out.push(*c),
        Tok::Number { has_sign, value } => write_numeric(*value, *has_sign, &mut out),
        Tok::Percentage {
            has_sign,
            unit_value,
        } => {
            write_numeric(*unit_value * 100.0, *has_sign, &mut out);
            out.push('%');
        }
        Tok::Dimension {
            has_sign,
            value,
            unit,
        } => {
            write_numeric(*value, *has_sign, &mut out);
            serialize_identifier(unit, &mut out);
        }
        Tok::WhiteSpace(s) => out.push_str(s),
        Tok::Comment(s) => {
            out.push_str("/*");
            out.push_str(s);
            out.push_str("*/");
        }
        Tok::Colon => out.push(':'),
        Tok::Semicolon => out.push(';'),
        Tok::Comma => out.push(','),
        Tok::IncludeMatch => out.push_str("~="),
        Tok::DashMatch => out.push_str("|="),
        Tok::PrefixMatch => out.push_str("^="),
        Tok::SuffixMatch => out.push_str("$="),
        Tok::SubstringMatch => out.push_str("*="),
        Tok::Cdo => out.push_str("<!--"),
        Tok::Cdc => out.push_str("-->"),
        Tok::Function(name) => {
            serialize_identifier(name, &mut out);
            out.push('(');
        }
        Tok::ParenthesisBlock => out.push('('),
        Tok::SquareBracketBlock => out.push('['),
        Tok::CurlyBracketBlock => out.push('{'),
        Tok::BadUrl(_) => {}
        Tok::BadString(_) => {}
        Tok::CloseParenthesis => out.push(')'),
        Tok::CloseSquareBracket => out.push(']'),
        Tok::CloseCurlyBracket => out.push('}'),
    }
    out
}
