        "csshiftjis" | "ms932" | "ms_kanji" | "shift-jis" | "shift_jis" | "sjis" | "windows-31j" | "x-sjis" => enc!("Shift_JIS", Kind::Iconv("CP932")),
        "cseuckr" | "csksc56011987" | "euc-kr" | "iso-ir-149" | "korean" | "ks_c_5601-1987" | "ks_c_5601-1989" | "ksc5601" | "ksc_5601" | "windows-949" => enc!("EUC-KR", Kind::Iconv("CP949")),
        "csiso2022kr" | "hz-gb-2312" | "iso-2022-cn" | "iso-2022-cn-ext" | "iso-2022-kr" | "replacement" => enc!("replacement", Kind::Replacement),
        "unicodefffe" | "utf-16be" => enc!("UTF-16BE", Kind::Utf16Be),
        "csunicode" | "iso-10646-ucs-2" | "ucs-2" | "unicode" | "unicodefeff" | "utf-16" | "utf-16le" => enc!("UTF-16LE", Kind::Utf16Le),
