        _ => return None,
    };
    Some(e)
}

pub fn decode(enc: &Encoding, bytes: &[u8]) -> String {
    match enc.kind {
        Kind::Utf8 => String::from_utf8_lossy(bytes).into_owned(),
        Kind::SingleByte(table) => {
            let mut s = String::with_capacity(bytes.len());
            for &b in bytes {
                if b < 0x80 {
                    s.push(b as char);
                } else {
                    let cp = table[(b - 0x80) as usize];
                    if cp == 0 {
                        s.push('\u{fffd}');
                    } else {
                        s.push(char::from_u32(cp as u32).unwrap_or('\u{fffd}'));
                    }
                }
            }
            s
        }
        Kind::Utf16Le | Kind::Utf16Be => {
            let le = enc.kind == Kind::Utf16Le;
            let mut units: Vec<u16> = Vec::with_capacity(bytes.len() / 2);
            let mut i = 0;
            while i + 1 < bytes.len() {
                let u = if le {
                    u16::from_le_bytes([bytes[i], bytes[i + 1]])
                } else {
                    u16::from_be_bytes([bytes[i], bytes[i + 1]])
                };
                units.push(u);
                i += 2;
            }
            let mut s: String = char::decode_utf16(units.iter().copied())
                .map(|r| r.unwrap_or('\u{fffd}'))
                .collect();
            if i < bytes.len() {
                s.push('\u{fffd}');
            }
            s
        }
        Kind::Replacement => {
            if bytes.is_empty() {
                String::new()
            } else {
                "\u{fffd}".to_string()
            }
        }
        Kind::XUserDefined => bytes
            .iter()
            .map(|&b| {
                if b < 0x80 {
                    b as char
                } else {
                    char::from_u32(0xF780 + (b as u32 - 0x80)).unwrap()
                }
            })
            .collect(),
        Kind::Iconv(name) => iconv_decode(name, bytes),
    }
}

/// Encode with HTML-compatible replacement of unmappable characters (&#NNN;).
pub fn encode(enc: &Encoding, s: &str) -> Vec<u8> {
    match enc.kind {
        Kind::Utf8 | Kind::Utf16Le | Kind::Utf16Be | Kind::Replacement => s.as_bytes().to_vec(),
        Kind::SingleByte(table) => {
            let mut out = Vec::with_capacity(s.len());
            for c in s.chars() {
                let cp = c as u32;
                if cp < 0x80 {
                    out.push(cp as u8);
                    continue;
                }
                let mut found = None;
                if cp <= 0xFFFF {
                    for (i, &t) in table.iter().enumerate() {
                        if t as u32 == cp && t != 0 {
                            found = Some(0x80 + i as u8);
                            break;
                        }
                    }
                }
                match found {
                    Some(b) => out.push(b),
                    None => out.extend_from_slice(format!("&#{};", cp).as_bytes()),
                }
            }
            out
        }
        Kind::XUserDefined => {
            let mut out = Vec::new();
            for c in s.chars() {
                let cp = c as u32;
                if cp < 0x80 {
                    out.push(cp as u8);
                } else if (0xF780..=0xF7FF).contains(&cp) {
                    out.push((cp - 0xF780 + 0x80) as u8);
                } else {
                    out.extend_from_slice(format!("&#{};", cp).as_bytes());
                }
            }
            out
        }
        Kind::Iconv(name) => iconv_encode(name, s),
    }
}

fn iconv_open(to: &str, from: &str) -> Option<libc::iconv_t> {
    let to_c = CString::new(to).ok()?;
    let from_c = CString::new(from).ok()?;
    let cd = unsafe { libc::iconv_open(to_c.as_ptr(), from_c.as_ptr()) };
    if cd as isize == -1 {
        None
    } else {
        Some(cd)
    }
}

fn iconv_decode(name: &str, bytes: &[u8]) -> String {
    let cd = match iconv_open("UTF-8", name) {
        Some(cd) => cd,
        None => return String::from_utf8_lossy(bytes).into_owned(),
    };
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len() * 2 + 16);
    let mut inbuf = bytes.to_vec();
    let mut in_ptr = inbuf.as_mut_ptr() as *mut libc::c_char;
    let mut in_left = inbuf.len();
    let mut outbuf = vec![0u8; 8192];
    loop {
        let mut out_ptr = outbuf.as_mut_ptr() as *mut libc::c_char;
        let mut out_left = outbuf.len();
        let r = unsafe {
            libc::iconv(
                cd,
                &mut in_ptr,
                &mut in_left,
                &mut out_ptr,
                &mut out_left,
            )
        };
        let produced = outbuf.len() - out_left;
        out.extend_from_slice(&outbuf[..produced]);
        if r as isize == -1 {
            let errno = unsafe { *libc::__errno_location() };
            if errno == libc::E2BIG {
                continue;
            } else if errno == libc::EILSEQ {
                // invalid sequence: emit U+FFFD, skip one byte
                out.extend_from_slice("\u{fffd}".as_bytes());
                if in_left > 0 {
                    in_ptr = unsafe { in_ptr.add(1) };
                    in_left -= 1;
                }
                // reset shift state
                continue;
            } else if errno == libc::EINVAL {
                // incomplete sequence at end
                out.extend_from_slice("\u{fffd}".as_bytes());
                break;
            } else {
                break;
            }
        } else {
            break;
        }
    }
    unsafe {
        libc::iconv_close(cd);
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn iconv_encode(name: &str, s: &str) -> Vec<u8> {
    let cd = match iconv_open(name, "UTF-8") {
        Some(cd) => cd,
        None => return s.as_bytes().to_vec(),
    };
    let mut out: Vec<u8> = Vec::with_capacity(s.len() + 16);
    let bytes = s.as_bytes();
    let mut inbuf = bytes.to_vec();
    let mut in_ptr = inbuf.as_mut_ptr() as *mut libc::c_char;
    let mut in_left = inbuf.len();
    let mut outbuf = vec![0u8; 8192];
    loop {
        let mut out_ptr = outbuf.as_mut_ptr() as *mut libc::c_char;
        let mut out_left = outbuf.len();
        let r = unsafe {
            libc::iconv(
                cd,
                &mut in_ptr,
                &mut in_left,
                &mut out_ptr,
                &mut out_left,
            )
        };
        let produced = outbuf.len() - out_left;
        out.extend_from_slice(&outbuf[..produced]);
        if r as isize == -1 {
            let errno = unsafe { *libc::__errno_location() };
            if errno == libc::E2BIG {
                continue;
            } else if errno == libc::EILSEQ {
                // unmappable char: emit numeric entity and skip the UTF-8 sequence
                let consumed = inbuf.len() - in_left;
                let rest = &bytes[consumed..];
                let ch = std::str::from_utf8(rest)
                    .ok()
                    .and_then(|r| r.chars().next())
                    .or_else(|| {
                        String::from_utf8_lossy(rest).chars().next()
                    });
                let (cp, len) = match ch {
                    Some(c) => (c as u32, c.len_utf8().max(1)),
                    None => (0xFFFD, 1),
                };
                out.extend_from_slice(format!("&#{};", cp).as_bytes());
                let len = len.min(in_left);
                in_ptr = unsafe { in_ptr.add(len) };
                in_left -= len;
                continue;
            } else {
                break;
            }
        } else {
            // flush shift state
            let mut out_ptr = outbuf.as_mut_ptr() as *mut libc::c_char;
            let mut out_left = outbuf.len();
            unsafe {
                libc::iconv(
                    cd,
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    &mut out_ptr,
                    &mut out_left,
                );
            }
            let produced = outbuf.len() - out_left;
            out.extend_from_slice(&outbuf[..produced]);
            break;
        }
    }
    unsafe {
        libc::iconv_close(cd);
    }
    out
}
