impl Cookie {
    pub fn is_expired(&self) -> bool {
        if self.expires == 0 {
            return false;
        }
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        self.expires < now
    }

    pub fn matches_url(&self, url: &Url) -> bool {
        if self.is_expired() {
            return false;
        }
        if self.https_only && url.scheme() != "https" {
            return false;
        }
