enum Stream {
    Plain(TcpStream),
    Tls {
        _tcp: TcpStream,
        ctx: *mut ssl::SSL_CTX,
        ssl: *mut ssl::SSL,
    },
}

impl Drop for Stream {
    fn drop(&mut self) {
        if let Stream::Tls { ctx, ssl, .. } = self {
            unsafe {
                ssl::SSL_shutdown(*ssl);
                ssl::SSL_free(*ssl);
                ssl::SSL_CTX_free(*ctx);
            }
        }
    }
}

impl Stream {
    fn write_all(&mut self, data: &[u8]) -> Result<(), ()> {
        match self {
            Stream::Plain(t) => t.write_all(data).map_err(|_| ()),
            Stream::Tls { ssl, .. } => {
                let mut off = 0;
                while off < data.len() {
                    let n = unsafe {
                        ssl::SSL_write(
                            *ssl,
                            data[off..].as_ptr() as *const _,
                            (data.len() - off) as i32,
                        )
                    };
                    if n <= 0 {
                        return Err(());
                    }
                    off += n as usize;
                }
                Ok(())
            }
        }
    }

    fn read(&mut self, buf: &mut [u8]) -> Result<usize, ()> {
        match self {
            Stream::Plain(t) => t.read(buf).map_err(|_| ()),
            Stream::Tls { ssl, .. } => {
                let n = unsafe { ssl::SSL_read(*ssl, buf.as_mut_ptr() as *mut _, buf.len() as i32) };
                if n < 0 {
                    Err(())
                } else {
                    Ok(n as usize)
                }
            }
        }
    }
}

fn env_proxy(scheme: &str, host: &str) -> Option<Url> {
    let no_proxy = std::env::var("no_proxy")
        .or_else(|_| std::env::var("NO_PROXY"))
        .unwrap_or_default();
    for entry in no_proxy.split(',') {
        let e = entry.trim();
        if e.is_empty() {
            continue;
        }
        if e == "*" || host == e || host.ends_with(&format!(".{}", e.trim_start_matches('.'))) || (e.starts_with('.') && host.ends_with(e)) {
            return None;
        }
    }
    let var = if scheme == "https" {
        std::env::var("https_proxy").or_else(|_| std::env::var("HTTPS_PROXY"))
    } else {
        std::env::var("http_proxy").or_else(|_| std::env::var("HTTP_PROXY"))
    };
    let v = var.ok()?;
    if v.is_empty() {
        return None;
    }
    let v = if v.contains("://") { v } else { format!("http://{}", v) };
    Url::parse(&v).ok()
}

impl HttpClient {
    fn deadline(&self) -> Option<Instant> {
        if self.timeout == 0 {
            None
        } else {
            Some(Instant::now() + Duration::from_secs(self.timeout))
        }
    }

    fn remaining(deadline: Option<Instant>) -> Result<Option<Duration>, ()> {
        match deadline {
            None => Ok(None),
            Some(d) => {
                let now = Instant::now();
                if now >= d {
                    Err(())
                } else {
                    Ok(Some(d - now))
                }
            }
        }
    }

    fn connect(&self, host: &str, port: u16, deadline: Option<Instant>) -> Result<TcpStream, ()> {
        let addrs: Vec<_> = (host, port).to_socket_addrs().map_err(|_| ())?.collect();
        if addrs.is_empty() {
            return Err(());
        }
        let mut last_err = Err(());
        for addr in addrs {
            let rem = Self::remaining(deadline)?;
            let r = match rem {
                Some(d) => TcpStream::connect_timeout(&addr, d.min(Duration::from_secs(30))),
                None => TcpStream::connect_timeout(&addr, Duration::from_secs(30)),
            };
            match r {
                Ok(s) => return Ok(s),
                Err(_) => last_err = Err(()),
            }
        }
        last_err
    }

