        let _ = tcp.set_nodelay(true);
        if let Some(d) = Self::remaining(deadline)? {
            let _ = tcp.set_read_timeout(Some(d));
            let _ = tcp.set_write_timeout(Some(d));
        }
        if url.scheme() == "https" {
            let mut tcp = tcp;
            if via_proxy {
                let req = format!(
                    "CONNECT {}:{} HTTP/1.1\r\nhost: {}:{}\r\n\r\n",
                    host, port, host, port
                );
                tcp.write_all(req.as_bytes()).map_err(|_| ())?;
                // read response headers
                let mut buf = Vec::new();
                let mut b = [0u8; 1];
                while !buf.ends_with(b"\r\n\r\n") {
                    let n = tcp.read(&mut b).map_err(|_| ())?;
                    if n == 0 {
                        return Err(());
                    }
                    buf.push(b[0]);
                    if buf.len() > 65536 {
                        return Err(());
                    }
                }
                let line = String::from_utf8_lossy(&buf);
                let status: u16 = line
                    .split_whitespace()
                    .nth(1)
                    .and_then(|s| s.parse().ok())
                    .unwrap_or(0);
                if !(200..300).contains(&status) {
                    return Err(());
