use std::time::{Duration, Instant};
use url::Url;

use base64::Engine;

#[derive(Clone, Debug)]
pub struct Cookie {
    pub domain: String,
    pub include_subdomains: bool,
    pub path: String,
    pub https_only: bool,
    pub expires: u64,
    pub name: String,
    pub value: String,
}

impl Cookie {
    pub fn is_expired(&self) -> bool {
        if self.expires == 0 {
            return false;
        }
        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0);
        self.expires < now
    }

    pub fn matches_url(&self, url: &Url) -> bool {
        if self.is_expired() {
            return false;
        }
        if self.https_only && url.scheme() != "https" {
            return false;
        }
        let host = url.host_str().unwrap_or("");
        let domain_ok = if self.domain.starts_with('.') {
            host.ends_with(&self.domain)
        } else {
            host == self.domain
        };
        if !domain_ok {
            return false;
        }
        url.path().starts_with(&self.path)
    }
}

pub fn parse_cookie_file(content: &str) -> Result<Vec<Cookie>, ()> {
    let mut lines = content.lines();
    let first = match lines.next() {
        Some(l) => l,
        None => return Err(()),
    };
    if !(first.starts_with("# HTTP Cookie File") || first.starts_with("# Netscape HTTP Cookie File")) {
        return Err(());
    }
    let mut cookies = Vec::new();
    for line in lines {
        let line = line.trim_end_matches('\r');
        if line.trim().is_empty() || line.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() != 7 {
            continue;
        }
        let expires: u64 = match parts[4].parse() {
            Ok(v) => v,
            Err(_) => return Err(()),
        };
        let flag = parts[1].to_ascii_lowercase();
        let secure = parts[3].to_ascii_lowercase();
        if !(flag == "true" || flag == "false") || !(secure == "true" || secure == "false") {
            return Err(());
        }
        cookies.push(Cookie {
            domain: parts[0].to_string(),
            include_subdomains: flag == "true",
            path: parts[2].to_string(),
            https_only: secure == "true",
            expires,
            name: parts[5].to_string(),
            value: parts[6].to_string(),
        });
    }
    Ok(cookies)
}

#[derive(Debug)]
pub enum HttpError {
    /// "error sending request for url (...)"
    Send,
    /// "builder error for url (...)"
    Builder,
    /// "error following redirect for url (...)"
