// ---------- OpenSSL FFI ----------

#[allow(non_camel_case_types)]
mod ssl {
    use std::os::raw::{c_char, c_int, c_long, c_void};
    pub type SSL_CTX = c_void;
    pub type SSL = c_void;
    pub type SSL_METHOD = c_void;
    #[link(name = "ssl")]
    #[link(name = "crypto")]
    extern "C" {
        pub fn TLS_client_method() -> *const SSL_METHOD;
        pub fn SSL_CTX_new(method: *const SSL_METHOD) -> *mut SSL_CTX;
        pub fn SSL_CTX_free(ctx: *mut SSL_CTX);
        pub fn SSL_CTX_set_verify(ctx: *mut SSL_CTX, mode: c_int, cb: *const c_void);
        pub fn SSL_CTX_set_default_verify_paths(ctx: *mut SSL_CTX) -> c_int;
        pub fn SSL_new(ctx: *mut SSL_CTX) -> *mut SSL;
        pub fn SSL_free(ssl: *mut SSL);
        pub fn SSL_set_fd(ssl: *mut SSL, fd: c_int) -> c_int;
        pub fn SSL_ctrl(ssl: *mut SSL, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long;
        pub fn SSL_set1_host(ssl: *mut SSL, hostname: *const c_char) -> c_int;
        pub fn SSL_connect(ssl: *mut SSL) -> c_int;
        pub fn SSL_read(ssl: *mut SSL, buf: *mut c_void, num: c_int) -> c_int;
        pub fn SSL_write(ssl: *mut SSL, buf: *const c_void, num: c_int) -> c_int;
        pub fn SSL_shutdown(ssl: *mut SSL) -> c_int;
    }
    pub const SSL_VERIFY_NONE: c_int = 0;
    pub const SSL_VERIFY_PEER: c_int = 1;
    pub const SSL_CTRL_SET_TLSEXT_HOSTNAME: c_int = 55;
    pub const TLSEXT_NAMETYPE_HOST_NAME: c_long = 0;
}

enum Stream {
    Plain(TcpStream),
    Tls {
        _tcp: TcpStream,
        ctx: *mut ssl::SSL_CTX,
        ssl: *mut ssl::SSL,
    },
}

impl Drop for Stream {
    fn drop(&mut self) {
        if let Stream::Tls { ctx, ssl, .. } = self {
            unsafe {
                ssl::SSL_shutdown(*ssl);
                ssl::SSL_free(*ssl);
                ssl::SSL_CTX_free(*ctx);
            }
        }
    }
}

impl Stream {
    fn write_all(&mut self, data: &[u8]) -> Result<(), ()> {
        match self {
            Stream::Plain(t) => t.write_all(data).map_err(|_| ()),
            Stream::Tls { ssl, .. } => {
                let mut off = 0;
                while off < data.len() {
                    let n = unsafe {
                        ssl::SSL_write(
                            *ssl,
                            data[off..].as_ptr() as *const _,
                            (data.len() - off) as i32,
                        )
                    };
                    if n <= 0 {
                        return Err(());
                    }
                    off += n as usize;
                }
                Ok(())
            }
        }
    }

    fn read(&mut self, buf: &mut [u8]) -> Result<usize, ()> {
        match self {
            Stream::Plain(t) => t.read(buf).map_err(|_| ()),
            Stream::Tls { ssl, .. } => {
                let n = unsafe { ssl::SSL_read(*ssl, buf.as_mut_ptr() as *mut _, buf.len() as i32) };
                if n < 0 {
                    Err(())
                } else {
                    Ok(n as usize)
                }
            }
        }
    }
}

fn env_proxy(scheme: &str, host: &str) -> Option<Url> {
    let no_proxy = std::env::var("no_proxy")
        .or_else(|_| std::env::var("NO_PROXY"))
        .unwrap_or_default();
    for entry in no_proxy.split(',') {
        let e = entry.trim();
        if e.is_empty() {
            continue;
        }
        if e == "*" || host == e || host.ends_with(&format!(".{}", e.trim_start_matches('.'))) || (e.starts_with('.') && host.ends_with(e)) {
            return None;
        }
    }
    let var = if scheme == "https" {
        std::env::var("https_proxy").or_else(|_| std::env::var("HTTPS_PROXY"))
    } else {
        std::env::var("http_proxy").or_else(|_| std::env::var("HTTP_PROXY"))
    };
    let v = var.ok()?;
    if v.is_empty() {
        return None;
    }
    let v = if v.contains("://") { v } else { format!("http://{}", v) };
    Url::parse(&v).ok()
}

impl HttpClient {
    fn deadline(&self) -> Option<Instant> {
        if self.timeout == 0 {
            None
        } else {
            Some(Instant::now() + Duration::from_secs(self.timeout))
        }
    }

    fn remaining(deadline: Option<Instant>) -> Result<Option<Duration>, ()> {
        match deadline {
            None => Ok(None),
            Some(d) => {
                let now = Instant::now();
                if now >= d {
                    Err(())
                } else {
                    Ok(Some(d - now))
                }
            }
        }
    }

    fn connect(&self, host: &str, port: u16, deadline: Option<Instant>) -> Result<TcpStream, ()> {
        let addrs: Vec<_> = (host, port).to_socket_addrs().map_err(|_| ())?.collect();
        if addrs.is_empty() {
            return Err(());
        }
        let mut last_err = Err(());
        for addr in addrs {
            let rem = Self::remaining(deadline)?;
            let r = match rem {
                Some(d) => TcpStream::connect_timeout(&addr, d.min(Duration::from_secs(30))),
                None => TcpStream::connect_timeout(&addr, Duration::from_secs(30)),
            };
            match r {
                Ok(s) => return Ok(s),
                Err(_) => last_err = Err(()),
            }
        }
        last_err
    }

    fn open_stream(&self, url: &Url, deadline: Option<Instant>) -> Result<Stream, ()> {
        let host = url.host_str().ok_or(())?;
        let port = url.port_or_known_default().ok_or(())?;
        let proxy = env_proxy(url.scheme(), host);
        let (tcp, via_proxy) = match &proxy {
            Some(p) => {
                let ph = p.host_str().ok_or(())?;
                let pp = p.port_or_known_default().unwrap_or(80);
                (self.connect(ph, pp, deadline)?, true)
            }
            None => (self.connect(host, port, deadline)?, false),
        };
        let _ = tcp.set_nodelay(true);
        if let Some(d) = Self::remaining(deadline)? {
            let _ = tcp.set_read_timeout(Some(d));
            let _ = tcp.set_write_timeout(Some(d));
        }
        if url.scheme() == "https" {
            let mut tcp = tcp;
            if via_proxy {
                let req = format!(
                    "CONNECT {}:{} HTTP/1.1\r\nhost: {}:{}\r\n\r\n",
                    host, port, host, port
                );
                tcp.write_all(req.as_bytes()).map_err(|_| ())?;
                // read response headers
                let mut buf = Vec::new();
                let mut b = [0u8; 1];
                while !buf.ends_with(b"\r\n\r\n") {
                    let n = tcp.read(&mut b).map_err(|_| ())?;
                    if n == 0 {
                        return Err(());
                    }
                    buf.push(b[0]);
                    if buf.len() > 65536 {
                        return Err(());
                    }
                }
                let line = String::from_utf8_lossy(&buf);
                let status: u16 = line
                    .split_whitespace()
                    .nth(1)
                    .and_then(|s| s.parse().ok())
                    .unwrap_or(0);
                if !(200..300).contains(&status) {
                    return Err(());
                }
            }
            unsafe {
                let ctx = ssl::SSL_CTX_new(ssl::TLS_client_method());
                if ctx.is_null() {
                    return Err(());
                }
                if self.insecure {
                    ssl::SSL_CTX_set_verify(ctx, ssl::SSL_VERIFY_NONE, std::ptr::null());
                } else {
                    ssl::SSL_CTX_set_verify(ctx, ssl::SSL_VERIFY_PEER, std::ptr::null());
                    ssl::SSL_CTX_set_default_verify_paths(ctx);
                }
                let s = ssl::SSL_new(ctx);
                if s.is_null() {
                    ssl::SSL_CTX_free(ctx);
                    return Err(());
                }
                let host_c = std::ffi::CString::new(host).map_err(|_| ())?;
                let is_ip = host.parse::<std::net::IpAddr>().is_ok();
                if !is_ip {
                    ssl::SSL_ctrl(
                        s,
                        ssl::SSL_CTRL_SET_TLSEXT_HOSTNAME,
                        ssl::TLSEXT_NAMETYPE_HOST_NAME,
                        host_c.as_ptr() as *mut _,
                    );
                }
                if !self.insecure {
                    ssl::SSL_set1_host(s, host_c.as_ptr());
                }
                ssl::SSL_set_fd(s, tcp.as_raw_fd());
                let stream = Stream::Tls {
                    _tcp: tcp,
                    ctx,
                    ssl: s,
                };
                if ssl::SSL_connect(s) != 1 {
                    return Err(());
                }
                Ok(stream)
            }
        } else {
            Ok(Stream::Plain(tcp))
        }
    }

    fn cookie_header(&self, url: &Url) -> Option<String> {
        let mut result = None;
        for c in &self.cookies {
            if c.matches_url(url) {
                result = Some(format!("{}={}", c.name, c.value));
            }
        }
        result
    }

    fn single_request(
        &self,
        url: &Url,
        referer: Option<&str>,
        redirect_referer: Option<&str>,
        auth: Option<&str>,
        deadline: Option<Instant>,
    ) -> Result<Response, ()> {
        let mut stream = self.open_stream(url, deadline)?;
        let host = url.host_str().ok_or(())?;
        let port = url.port_or_known_default().unwrap_or(80);
        let default_port = match url.scheme() {
            "https" => 443,
            _ => 80,
        };
        let host_header = if port == default_port {
            host.to_string()
        } else {
            format!("{}:{}", host, port)
        };
        let via_proxy = url.scheme() == "http" && env_proxy("http", host).is_some();
        let mut target = url.path().to_string();
        if let Some(q) = url.query() {
            target.push('?');
            target.push_str(q);
        }
        if via_proxy {
            let mut u = url.clone();
            let _ = u.set_username("");
            let _ = u.set_password(None);
            u.set_fragment(None);
            target = u.to_string();
        }
        let mut req = String::new();
        req.push_str(&format!("GET {} HTTP/1.1\r\n", target));
        if let Some(a) = auth {
            req.push_str(&format!("authorization: Basic {}\r\n", a));
        }
        if let Some(c) = self.cookie_header(url) {
            req.push_str(&format!("cookie: {}\r\n", c));
        }
        if let Some(r) = referer {
            req.push_str(&format!("referer: {}\r\n", r));
        }
        req.push_str("accept: */*\r\n");
        req.push_str(&format!("user-agent: {}\r\n", self.user_agent));
        req.push_str("accept-encoding: gzip, br, deflate\r\n");
        if let Some(r) = redirect_referer {
            req.push_str(&format!("referer: {}\r\n", r));
        }
        req.push_str(&format!("host: {}\r\n", host_header));
        req.push_str("\r\n");
        stream.write_all(req.as_bytes())?;

        // Read all
        let mut raw: Vec<u8> = Vec::new();
        let mut buf = [0u8; 16384];
        let mut header_end: Option<usize> = None;
        loop {
            if let Some(d) = deadline {
                if Instant::now() >= d {
                    return Err(());
                }
            }
            let n = stream.read(&mut buf)?;
            if n == 0 {
                break;
            }
            raw.extend_from_slice(&buf[..n]);
            if header_end.is_none() {
                if let Some(p) = find_subslice(&raw, b"\r\n\r\n") {
                    header_end = Some(p + 4);
                } else if let Some(p) = find_subslice(&raw, b"\n\n") {
                    header_end = Some(p + 2);
                }
            }
            if let Some(he) = header_end {
                // check if body complete
                let (status, headers) = parse_head(&raw[..he]).ok_or(())?;
                let _ = status;
                if body_complete(&headers, &raw[he..], status) {
                    break;
                }
            }
        }
        let he = header_end.ok_or(())?;
        let (status, headers) = parse_head(&raw[..he]).ok_or(())?;
        let body_raw = &raw[he..];
        let mut body = extract_body(&headers, body_raw);
        // content-encoding
        if let Some(ce) = headers
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case("content-encoding"))
            .map(|(_, v)| v.to_ascii_lowercase())
        {
            if ce.contains("gzip") {
                let mut d = flate2::read::MultiGzDecoder::new(&body[..]);
                let mut out = Vec::new();
                if d.read_to_end(&mut out).is_ok() {
                    body = out;
                } else {
                    return Err(());
                }
            } else if ce.contains("deflate") {
                let mut out = Vec::new();
                let mut d = flate2::read::ZlibDecoder::new(&body[..]);
                if d.read_to_end(&mut out).is_ok() {
                    body = out;
                } else {
                    let mut d2 = flate2::read::DeflateDecoder::new(&body[..]);
                    let mut out2 = Vec::new();
                    if d2.read_to_end(&mut out2).is_ok() {
                        body = out2;
                    } else {
                        return Err(());
                    }
                }
            } else if ce.contains("br") {
                return Err(());
            }
        }
        Ok(Response {
            final_url: url.clone(),
            status,
            reason: reason_phrase(status).to_string(),
            headers,
            body,
        })
    }

    pub fn get(&self, url: &Url, referer: Option<&str>) -> Result<Response, HttpError> {
        if url.scheme() != "http" && url.scheme() != "https" {
            return Err(HttpError::Builder);
        }
        let deadline = self.deadline();
        let mut current = url.clone();
        let auth = if !url.username().is_empty() || url.password().is_some() {
            let creds = format!("{}:{}", url.username(), url.password().unwrap_or(""));
            Some(base64::engine::general_purpose::STANDARD.encode(creds.as_bytes()))
        } else {
            None
        };
        let _ = current.set_username("");
        let _ = current.set_password(None);
        let mut auth = auth;
        let mut redirects = 0;
        let mut redirect_referer: Option<String> = None;
        loop {
            let resp = self
                .single_request(
                    &current,
                    referer,
                    redirect_referer.as_deref(),
                    auth.as_deref(),
                    deadline,
                )
                .map_err(|_| HttpError::Send)?;
            let is_redirect = matches!(resp.status, 301 | 302 | 303 | 307 | 308);
            if is_redirect {
                if let Some(loc) = resp.header("location") {
                    let next = match current.join(loc) {
                        Ok(u) => u,
                        Err(_) => return Err(HttpError::Redirect),
                    };
                    if next.scheme() != "http" && next.scheme() != "https" {
                        return Err(HttpError::Redirect);
                    }
                    redirects += 1;
                    if redirects >= 10 {
                        return Err(HttpError::Redirect);
                    }
                    // Remove sensitive headers when changing host
                    if next.host_str() != current.host_str() {
                        auth = None;
                    }
                    let mut prev = current.clone();
                    prev.set_fragment(None);
                    redirect_referer = if next.scheme() == "http" && prev.scheme() == "https" {
                        None
                    } else {
                        Some(prev.to_string())
                    };
                    current = next;
                    let _ = current.set_username("");
                    let _ = current.set_password(None);
                    continue;
                }
            }
            let mut r = resp;
            r.final_url = current.clone();
            return Ok(r);
        }
    }
}

fn find_subslice(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || hay.len() < needle.len() {
        return None;
    }
    hay.windows(needle.len()).position(|w| w == needle)
}

fn parse_head(head: &[u8]) -> Option<(u16, Vec<(String, String)>)> {
    let text = String::from_utf8_lossy(head);
    let mut lines = text.split("\r\n").flat_map(|l| l.split('\n'));
    let status_line = lines.next()?;
    let mut parts = status_line.splitn(3, ' ');
    let _version = parts.next()?;
    let status: u16 = parts.next()?.parse().ok()?;
    let mut headers = Vec::new();
    for line in lines {
        if line.is_empty() {
            continue;
        }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].trim().to_string();
            let v = line[idx + 1..].trim().to_string();
            headers.push((k, v));
        }
    }
    Some((status, headers))
}

fn header_value<'a>(headers: &'a [(String, String)], name: &str) -> Option<&'a str> {
    headers
        .iter()
        .find(|(k, _)| k.eq_ignore_ascii_case(name))
        .map(|(_, v)| v.as_str())
}

fn body_complete(headers: &[(String, String)], body: &[u8], status: u16) -> bool {
    if status == 204 || status == 304 || (100..200).contains(&status) {
        return true;
    }
    if let Some(te) = header_value(headers, "transfer-encoding") {
        if te.to_ascii_lowercase().contains("chunked") {
            return decode_chunked(body).is_some();
        }
    }
    if let Some(cl) = header_value(headers, "content-length") {
        if let Ok(n) = cl.trim().parse::<usize>() {
            return body.len() >= n;
        }
    }
    false
}

fn extract_body(headers: &[(String, String)], body: &[u8]) -> Vec<u8> {
    if let Some(te) = header_value(headers, "transfer-encoding") {
        if te.to_ascii_lowercase().contains("chunked") {
            if let Some(b) = decode_chunked(body) {
                return b;
            }
            return Vec::new();
        }
    }
    if let Some(cl) = header_value(headers, "content-length") {
        if let Ok(n) = cl.trim().parse::<usize>() {
            return body[..n.min(body.len())].to_vec();
        }
    }
    body.to_vec()
}

/// Returns Some(decoded) if the chunked body is complete.
fn decode_chunked(data: &[u8]) -> Option<Vec<u8>> {
    let mut out = Vec::new();
    let mut pos = 0;
    loop {
        let line_end = find_subslice(&data[pos..], b"\r\n")? + pos;
        let size_str = String::from_utf8_lossy(&data[pos..line_end]);
        let size_str = size_str.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size_str, 16).ok()?;
        pos = line_end + 2;
        if size == 0 {
            // trailers until empty line
            loop {
                let le = match find_subslice(&data[pos..], b"\r\n") {
                    Some(p) => p + pos,
                    None => return Some(out), // lenient
                };
                if le == pos {
                    return Some(out);
                }
                pos = le + 2;
            }
        }
        if data.len() < pos + size + 2 {
            return None;
        }
        out.extend_from_slice(&data[pos..pos + size]);
        pos += size + 2;
    }
}
