//! Asset retrieval with caching, logging and option handling.

use std::collections::HashMap;
use url::Url;

use crate::http::{HttpClient, HttpError};
use crate::utils::*;

#[derive(Clone, Debug, Default)]
pub struct Options {
    pub no_audio: bool,
    pub base_url: Option<String>,
    pub blacklist_domains: bool,
    pub no_css: bool,
    pub cookie_file: Option<String>,
    pub domains: Option<Vec<String>>,
    pub ignore_errors: bool,
    pub encoding: Option<String>,
    pub no_frames: bool,
    pub no_fonts: bool,
    pub no_images: bool,
    pub isolate: bool,
    pub no_js: bool,
    pub insecure: bool,
    pub mhtml: bool,
    pub no_metadata: bool,
    pub unwrap_noscript: bool,
    pub output: String,
    pub quiet: bool,
    pub timeout: u64,
    pub user_agent: Option<String>,
    pub no_video: bool,
    pub target: String,
}

pub struct Asset {
    pub data: Vec<u8>,
    pub final_url: Url,
    pub media_type: String,
    pub charset: String,
}

pub struct Session {
    pub options: Options,
    pub client: HttpClient,
    cache: HashMap<String, (Vec<u8>, String, String)>,
}

impl Session {
    pub fn new(options: Options, client: HttpClient) -> Session {
        Session {
            options,
            client,
            cache: HashMap::new(),
        }
    }

    pub fn log(&self, msg: &str) {
        if !self.options.quiet {
            eprintln!("{}", msg);
        }
    }

    /// Retrieve an asset. On error returns Err(()) after logging (unless silent).
    pub fn retrieve(&mut self, parent_url: &Url, url: &Url) -> Result<Asset, ()> {
        let url_str = url.to_string();
        match url.scheme() {
            "data" => {
                let (media_type, charset, data) = parse_data_url(url);
                Ok(Asset {
                    data,
                    final_url: url.clone(),
                    media_type,
                    charset,
                })
            }
            "file" => {
                if parent_url.scheme() != "file" {
                    self.log(&format!("{} (security error)", url_str));
                    return Err(());
                }
                let path = match url.to_file_path() {
                    Ok(p) => p,
                    Err(_) => {
                        self.log(&format!("{} (file not found)", url_str));
                        return Err(());
                    }
                };
                if !path.is_file() {
                    self.log(&format!("{} (file not found)", url_str));
                    return Err(());
                }
                match std::fs::read(&path) {
                    Ok(data) => {
                        self.log(&url_str);
                        let media_type = detect_media_type(&data, &path.to_string_lossy());
