// ---------- processing ----------

use crate::session::Session;
use crate::utils::*;
use url::Url;

const IMAGE_PROPS: &[&str] = &[
    "background",
    "background-image",
    "border-image",
    "border-image-source",
    "mask",
    "mask-image",
    "list-style",
    "list-style-image",
    "cursor",
    "content",
];

#[derive(PartialEq, Clone, Copy)]
enum Mode {
    Normal,
    UrlFunction,
}

struct CssProcessor<'a> {
    session: &'a mut Session,
    parent_url: Url,
    base_url: Url,
    tokens: Vec<Tok>,
    pos: usize,
}

pub fn process_css(session: &mut Session, css: &str, parent_url: &Url, base_url: &Url) -> String {
    let tokens = tokenize(css);
    let mut p = CssProcessor {
        session,
        parent_url: parent_url.clone(),
        base_url: base_url.clone(),
        tokens,
        pos: 0,
    };
    p.process_block(None, Mode::Normal)
}

/// Decode CSS bytes using charset (defaulting per URL scheme), process, and return UTF-8 bytes.
pub fn process_css_asset(
    session: &mut Session,
    data: &[u8],
    charset: &str,
    css_url: &Url,
) -> Vec<u8> {
    let enc = crate::document::pick_encoding(charset, css_url);
    let text = crate::encoding::decode(&enc, data);
    let out = process_css(session, &text, css_url, css_url);
    out.into_bytes()
}

impl<'a> CssProcessor<'a> {
    fn skip_block(&mut self, closing: &Tok) {
        let mut depth = 0usize;
        while self.pos < self.tokens.len() {
            let t = self.tokens[self.pos].clone();
            self.pos += 1;
            match t {
                Tok::CurlyBracketBlock | Tok::ParenthesisBlock | Tok::SquareBracketBlock | Tok::Function(_) => {
                    depth += 1
                }
                Tok::CloseCurlyBracket | Tok::CloseParenthesis | Tok::CloseSquareBracket => {
                    if depth == 0 {
                        if &t == closing {
                            return;
                        }
                        // mismatched closer: treat as end anyway
                        return;
                    }
                    depth -= 1;
                }
                _ => {}
            }
        }
    }

    fn process_block(&mut self, closing: Option<Tok>, mode: Mode) -> String {
        let mut out = String::new();
        let mut at_rule: Option<String> = None;
        let mut last_ident: Option<String> = None;
        while self.pos < self.tokens.len() {
            let tok = self.tokens[self.pos].clone();
            self.pos += 1;
            if let Some(c) = &closing {
                if &tok == c {
                    return out;
                }
            }
            match &tok {
                Tok::CurlyBracketBlock | Tok::ParenthesisBlock | Tok::SquareBracketBlock => {
                    let (open, close) = match tok {
                        Tok::CurlyBracketBlock => ("{", Tok::CloseCurlyBracket),
                        Tok::ParenthesisBlock => ("(", Tok::CloseParenthesis),
                        _ => ("[", Tok::CloseSquareBracket),
                    };
                    let is_font_face = at_rule
                        .as_deref()
                        .map_or(false, |a| a.eq_ignore_ascii_case("font-face"));
                    if tok == Tok::CurlyBracketBlock && is_font_face && self.session.options.no_fonts {
                        self.skip_block(&close);
                        at_rule = None;
                        continue;
                    }
                    let inner = self.process_block(Some(close.clone()), Mode::Normal);
                    out.push_str(open);
                    if !inner.trim().is_empty() {
                        out.push_str(&inner);
                    }
                    out.push_str(&tok_to_css(&close));
                    if tok == Tok::CurlyBracketBlock {
                        at_rule = None;
                    }
                }
                Tok::Function(name) => {
                    if name == "url" {
                        let is_import = at_rule
                            .as_deref()
                            .map_or(false, |a| a.eq_ignore_ascii_case("import"));
                        let inner = self.process_url_function(is_import, last_ident.as_deref());
                        out.push_str("url(");
                        if !inner.trim().is_empty() {
                            out.push_str(&inner);
                        }
                        out.push(')');
                    } else {
                        let inner = self.process_block(Some(Tok::CloseParenthesis), Mode::Normal);
                        out.push_str(&tok_to_css(&tok));
                        if !inner.trim().is_empty() {
                            out.push_str(&inner);
                        }
                        out.push(')');
                    }
                }
                Tok::AtKeyword(name) => {
                    at_rule = Some(name.clone());
                    if self.session.options.no_fonts && name.eq_ignore_ascii_case("font-face") {
                        // dropped
                    } else {
                        out.push_str(&tok_to_css(&tok));
                    }
                }
                Tok::Semicolon => {
                    out.push(';');
                    at_rule = None;
                }
                Tok::Ident(v) => {
                    last_ident = Some(v.clone());
                    out.push_str(&tok_to_css(&tok));
                }
                Tok::QuotedString(v) => {
                    let is_import = at_rule
                        .as_deref()
                        .map_or(false, |a| a.eq_ignore_ascii_case("import"));
                    if mode == Mode::UrlFunction {
                        out.push_str(&self.quoted_url_value(v, is_import, last_ident.as_deref()));
                    } else if is_import {
                        out.push_str(&self.quoted_url_value(v, true, last_ident.as_deref()));
                    } else {
                        out.push_str(&tok_to_css(&tok));
                    }
                }
                Tok::UnquotedUrl(v) => {
                    let is_import = at_rule
                        .as_deref()
                        .map_or(false, |a| a.eq_ignore_ascii_case("import"));
                    if v.starts_with('#') {
                        out.push_str(&tok_to_css(&tok));
                    } else if v.is_empty() {
                        out.push_str("url()");
                    } else {
                        let value = self.embed_url(v, is_import, last_ident.as_deref());
                        match value {
                            Some(s) => {
                                out.push_str("url(");
                                serialize_string(&s, &mut out);
                                out.push(')');
                            }
                            None => out.push_str("url()"),
                        }
                    }
                }
                Tok::BadUrl(_) | Tok::BadString(_) => {}
                _ => out.push_str(&tok_to_css(&tok)),
            }
        }
        out
    }

    fn process_url_function(&mut self, is_import: bool, last_ident: Option<&str>) -> String {
        // Inner tokens of url( ... ) where the first non-whitespace token is a quoted string.
        let mut out = String::new();
        let mut at_rule: Option<String> = if is_import {
            Some("import".to_string())
        } else {
            None
        };
        let mut last_ident: Option<String> = last_ident.map(|s| s.to_string());
        while self.pos < self.tokens.len() {
            let tok = self.tokens[self.pos].clone();
            self.pos += 1;
            match &tok {
                Tok::CloseParenthesis => return out,
                Tok::QuotedString(v) => {
                    let imp = at_rule.is_some();
                    out.push_str(&self.quoted_url_value(v, imp, last_ident.as_deref()));
                }
                Tok::CurlyBracketBlock | Tok::ParenthesisBlock | Tok::SquareBracketBlock => {
                    let (open, close) = match tok {
                        Tok::CurlyBracketBlock => ("{", Tok::CloseCurlyBracket),
                        Tok::ParenthesisBlock => ("(", Tok::CloseParenthesis),
                        _ => ("[", Tok::CloseSquareBracket),
                    };
                    let inner = self.process_block(Some(close.clone()), Mode::Normal);
                    out.push_str(open);
                    if !inner.trim().is_empty() {
                        out.push_str(&inner);
                    }
                    out.push_str(&tok_to_css(&close));
                }
                Tok::Function(name) => {
                    if name == "url" {
                        let inner = self.process_url_function(false, last_ident.as_deref());
                        out.push_str("url(");
                        if !inner.trim().is_empty() {
                            out.push_str(&inner);
                        }
                        out.push(')');
                    } else {
                        let inner = self.process_block(Some(Tok::CloseParenthesis), Mode::Normal);
                        out.push_str(&tok_to_css(&tok));
                        if !inner.trim().is_empty() {
                            out.push_str(&inner);
                        }
                        out.push(')');
                    }
                }
                Tok::Ident(v) => {
                    last_ident = Some(v.clone());
                    out.push_str(&tok_to_css(&tok));
                }
                Tok::Semicolon => {
                    out.push(';');
                    at_rule = None;
                }
                Tok::BadUrl(_) | Tok::BadString(_) => {}
                _ => out.push_str(&tok_to_css(&tok)),
            }
        }
        out
    }

    /// Returns the serialized replacement for a quoted string that is a URL.
    fn quoted_url_value(&mut self, v: &str, is_import: bool, last_ident: Option<&str>) -> String {
        if v.is_empty() {
            return if is_import { "''".to_string() } else { String::new() };
        }
        match self.embed_url(v, is_import, last_ident) {
            Some(s) => {
                let mut out = String::new();
                serialize_string(&s, &mut out);
                out
            }
            None => String::new(),
        }
    }

    /// Resolve and embed a URL found in CSS. Returns the new URL string, or None for removal.
    fn embed_url(&mut self, v: &str, is_import: bool, last_ident: Option<&str>) -> Option<String> {
        if !is_import && self.session.options.no_images {
            if let Some(prop) = last_ident {
                if IMAGE_PROPS.contains(&prop.to_ascii_lowercase().as_str()) {
                    return Some(EMPTY_IMAGE_DATA_URL.to_string());
                }
            }
        }
        let resolved = resolve_url(&self.base_url, v);
        let parent = self.parent_url.clone();
        match self.session.retrieve(&parent, &resolved) {
            Ok(asset) => {
                if is_import {
                    let processed = process_css_asset(
                        self.session,
                        &asset.data,
                        &asset.charset,
                        &asset.final_url,
                    );
                    Some(create_data_url(
                        &asset.media_type,
                        &asset.charset,
                        &processed,
                        None,
                    ))
                } else {
                    Some(create_data_url(
                        &asset.media_type,
                        &asset.charset,
                        &asset.data,
                        resolved.fragment(),
                    ))
                }
            }
            Err(_) => {
                if is_http_url(&resolved) {
                    Some(resolved.to_string())
                } else {
                    None
                }
            }
        }
    }
}
