pub fn default_encoding_for(url: &Url, from_stdin: bool) -> Encoding {
    if from_stdin || url.scheme() == "file" {
        encoding::UTF_8
    } else {
        encoding::WINDOWS_1252
    }
}

/// Extract charset from a Content-Type-like meta content value.
pub fn charset_from_meta_content(content: &str) -> Option<String> {
    for part in content.split(';') {
        let p = part.trim();
        let lower = p.to_ascii_lowercase();
        if lower.starts_with("charset") {
            if let Some(idx) = p.find('=') {
                let v = p[idx + 1..].trim().trim_matches(|c| c == '"' || c == '\'');
                return Some(v.to_string());
            }
        }
    }
    None
}

/// Find the charset declared via <meta> in the document head (first declaration wins).
pub fn find_meta_charset(dom: &Dom) -> Option<String> {
    let head = dom.head_element()?;
    for child in dom.children(head) {
        if !dom.is_named(child, "meta") {
            continue;
        }
        if let Some(cs) = dom.get_attr(child, "charset") {
            return Some(cs);
        }
        if let Some(he) = dom.get_attr(child, "http-equiv") {
            if he.eq_ignore_ascii_case("content-type") {
                if let Some(content) = dom.get_attr(child, "content") {
                    if let Some(cs) = charset_from_meta_content(&content) {
                        return Some(cs);
                    }
                }
            }
        }
    }
    None
}

/// Decode bytes and parse into a DOM; honours <meta charset> declarations.
/// Returns (dom, encoding used).
pub fn html_to_dom(data: &[u8], initial: Encoding) -> (Dom, Encoding) {
    let text = encoding::decode(&initial, data);
    let dom = parse_document(&text);
    if let Some(cs) = find_meta_charset(&dom) {
        if let Some(enc) = encoding::for_label(&cs) {
            if enc != initial {
                let text2 = encoding::decode(&enc, data);
                let dom2 = parse_document(&text2);
                return (dom2, enc);
            }
        }
    }
    (dom, initial)
}

