pub fn create_element(dom: &mut Dom, name: &str, attrs: &[(&str, &str)]) -> NodeId {
    let attrs: Vec<Attr> = attrs
        .iter()
        .map(|(n, v)| Attr {
            ns: String::new(),
            prefix: None,
            local: n.to_string(),
            value: v.to_string(),
        })
        .collect();
    dom.new_element("", name, attrs)
