        s.push_str("font-src 'none';");
    }
    if o.no_frames {
        if !s.is_empty() {
            s.push(' ');
        }
        s.push_str("frame-src 'none'; child-src 'none';");
    }
    if o.no_js {
        if !s.is_empty() {
            s.push(' ');
        }
        s.push_str("script-src 'none';");
    }
    if o.no_images {
        if !s.is_empty() {
            s.push(' ');
        }
        s.push_str("img-src data:;");
    }
    s
