            continue;
        }
        if dom.has_attr(child, "charset") {
            dom.set_attr(child, "charset", Some(label));
            found = true;
        } else if let Some(he) = dom.get_attr(child, "http-equiv") {
            if he.eq_ignore_ascii_case("content-type") {
                if let Some(content) = dom.get_attr(child, "content") {
                    if charset_from_meta_content(&content).is_some() {
                        dom.set_attr(
                            child,
                            "content",
                            Some(&format!("text/html;charset={}", label)),
                        );
                        found = true;
                    }
                }
            }
        }
    }
    if !found {
        let el = create_element(dom, "meta", &[("charset", label)]);
        dom.append(head, el);
    }
}

