//! DOM walker: embeds assets and applies options.

use url::Url;

use crate::css;
use crate::document;
use crate::html::*;
use crate::session::Session;
use crate::utils::*;

#[derive(PartialEq, Debug)]
pub enum LinkKind {
    Stylesheet,
    Icon,
    Removable,
    Other,
}

pub fn link_rel_kind(rel: &str) -> LinkKind {
    let tokens: Vec<String> = rel.split_whitespace().map(|t| t.to_ascii_lowercase()).collect();
    if tokens.iter().any(|t| t == "stylesheet") {
        LinkKind::Stylesheet
    } else if tokens.iter().any(|t| t == "icon") {
        LinkKind::Icon
    } else if tokens.iter().any(|t| t == "preload" || t == "dns-prefetch") {
        LinkKind::Removable
    } else {
        LinkKind::Other
    }
}

const JS_EVENT_ATTRS: &[&str] = &[
    "onabort", "onafterprint", "onauxclick", "onbeforeprint", "onbeforeunload", "onblur",
    "oncancel", "oncanplay", "oncanplaythrough", "onchange", "onclick", "onclose",
    "oncontextmenu", "oncopy", "oncuechange", "oncut", "ondblclick", "ondrag", "ondragend",
    "ondragenter", "ondragexit", "ondragleave", "ondragover", "ondragstart", "ondrop",
    "ondurationchange", "onemptied", "onended", "onerror", "onfocus", "onformdata",
    "onhashchange", "oninput", "oninvalid", "onkeydown", "onkeypress", "onkeyup",
    "onlanguagechange", "onload", "onloadeddata", "onloadedmetadata", "onloadstart",
    "onmessage", "onmessageerror", "onmousedown", "onmouseenter", "onmouseleave",
    "onmousemove", "onmouseout", "onmouseover", "onmouseup", "onoffline", "ononline",
    "onpagehide", "onpageshow", "onpaste", "onpause", "onplay", "onplaying", "onpopstate",
    "onprogress", "onratechange", "onreset", "onresize", "onrejectionhandled", "onscroll",
    "onsecuritypolicyviolation", "onseeked", "onseeking", "onselect", "onslotchange",
    "onstalled", "onstorage", "onsubmit", "onsuspend", "ontimeupdate", "ontoggle",
    "onunhandledrejection", "onunload", "onvolumechange", "onwaiting", "onwebkitanimationend",
    "onwebkitanimationiteration", "onwebkitanimationstart", "onwebkittransitionend", "onwheel",
];

pub struct Walker<'a> {
    pub session: &'a mut Session,
    pub document_url: Url,
    pub base_url: Url,
}

enum Fetched {
    /// A data URL to embed
    Embedded(String),
    /// Retrieval failed but URL is http(s): use absolute URL
    Absolute(String),
    /// Retrieval failed: remove
    Failed,
}

impl<'a> Walker<'a> {
    pub fn walk(&mut self, dom: &mut Dom, node: NodeId) {
        if dom.is_element(node) {
            self.process_element(dom, node);
        }
        // snapshot children after processing (noscript/use may have changed them)
        let children = dom.children(node);
        for c in children {
            // the node might have been detached (e.g. noscript unwrapped) - still process
            if dom.node(c).parent.is_some() || true {
                self.walk(dom, c);
            }
        }
    }

    fn fetch_data_url(&mut self, href: &str, keep_fragment: bool) -> Fetched {
        let resolved = resolve_url(&self.base_url, href);
        let parent = self.document_url.clone();
        match self.session.retrieve(&parent, &resolved) {
            Ok(asset) => Fetched::Embedded(create_data_url(
                &asset.media_type,
                &asset.charset,
                &asset.data,
                if keep_fragment { resolved.fragment() } else { None },
            )),
            Err(_) => {
                if is_http_url(&resolved) {
                    Fetched::Absolute(resolved.to_string())
                } else {
                    Fetched::Failed
                }
            }
        }
    }

    /// Standard handling for a URL attribute: embed, absolutize, or remove.
    fn embed_attr(&mut self, dom: &mut Dom, node: NodeId, attr: &str, href: &str) {
        match self.fetch_data_url(href, true) {
            Fetched::Embedded(u) | Fetched::Absolute(u) => dom.set_attr(node, attr, Some(&u)),
            Fetched::Failed => dom.remove_attr(node, attr),
        }
    }

    fn process_srcset(&mut self, srcset: &str) -> String {
        let entries = parse_srcset(srcset);
        let mut out = Vec::new();
        for (u, d) in entries {
            let new_u = if self.session.options.no_images {
                EMPTY_IMAGE_DATA_URL.to_string()
            } else {
                match self.fetch_data_url(&u, true) {
                    Fetched::Embedded(x) | Fetched::Absolute(x) => x,
                    Fetched::Failed => EMPTY_IMAGE_DATA_URL.to_string(),
                }
            };
            out.push((new_u, d));
        }
        format_srcset(&out)
    }

    fn resolve_href_attr(&mut self, dom: &mut Dom, node: NodeId, attr: &str) {
        if let Some(value) = dom.get_attr(node, attr) {
            if value.starts_with('#') {
                return;
            }
            if Url::parse(&value).is_ok() {
                return;
            }
            let resolved = resolve_url(&self.base_url, &value);
            dom.set_attr(node, attr, Some(resolved.as_str()));
        }
    }

    fn check_integrity(data: &[u8], integrity: &str) -> bool {
        use sha2::Digest;
        let (algo, hash) = match integrity.find('-') {
            Some(i) => (&integrity[..i], &integrity[i + 1..]),
            None => return false,
        };
        let digest: Vec<u8> = match algo {
            "sha256" => sha2::Sha256::digest(data).to_vec(),
            "sha384" => sha2::Sha384::digest(data).to_vec(),
            "sha512" => sha2::Sha512::digest(data).to_vec(),
            _ => return false,
        };
        use base64::Engine;
        base64::engine::general_purpose::STANDARD.encode(&digest) == hash
    }

    fn process_element(&mut self, dom: &mut Dom, node: NodeId) {
        let name = match dom.local_name(node) {
            Some(n) => n.to_string(),
            None => return,
        };
        let opts = self.session.options.clone();

        // Remove JS event handler attributes
        if opts.no_js {
            if let Some(attrs) = dom.attrs_mut(node) {
                attrs.retain(|a| !JS_EVENT_ATTRS.contains(&a.local.to_ascii_lowercase().as_str()));
            }
        }

        match name.as_str() {
            "meta" => {
                if let Some(he) = dom.get_attr(node, "http-equiv") {
                    if he.eq_ignore_ascii_case("refresh") {
                        dom.remove_attr(node, "http-equiv");
                    }
                }
            }
            "link" => {
                let rel = dom.get_attr(node, "rel").unwrap_or_default();
                match link_rel_kind(&rel) {
                    LinkKind::Stylesheet => {
                        if opts.no_css {
                            dom.remove_attr(node, "href");
                        } else if let Some(href) = dom.get_attr(node, "href") {
                            if !href.is_empty() {
                                let resolved = resolve_url(&self.base_url, &href);
                                let parent = self.document_url.clone();
                                match self.session.retrieve(&parent, &resolved) {
                                    Ok(asset) => {
                                        let integrity = dom.get_attr(node, "integrity");
                                        let ok = match &integrity {
                                            Some(i) if !i.is_empty() => Self::check_integrity(&asset.data, i),
                                            _ => true,
                                        };
                                        if ok {
                                            let processed = css::process_css_asset(
                                                self.session,
                                                &asset.data,
                                                &asset.charset,
                                                &asset.final_url,
                                            );
                                            let du = create_data_url(
                                                &asset.media_type,
                                                &asset.charset,
                                                &processed,
                                                None,
                                            );
                                            dom.set_attr(node, "href", Some(&du));
                                        }
                                        dom.remove_attr(node, "integrity");
                                    }
                                    Err(_) => {
                                        if is_http_url(&resolved) {
                                            dom.set_attr(node, "href", Some(resolved.as_str()));
                                        } else {
                                            dom.remove_attr(node, "href");
                                        }
                                    }
                                }
                            }
                        }
                    }
                    LinkKind::Icon => {
                        let href = dom.get_attr(node, "href");
                        if opts.no_images || href.as_deref() == Some("") {
                            dom.remove_attr(node, "href");
                        } else if let Some(href) = href {
                            let resolved = resolve_url(&self.base_url, &href);
                            let parent = self.document_url.clone();
                            match self.session.retrieve(&parent, &resolved) {
                                Ok(asset) => {
                                    let integrity = dom.get_attr(node, "integrity");
                                    let ok = match &integrity {
                                        Some(i) if !i.is_empty() => Self::check_integrity(&asset.data, i),
                                        _ => true,
                                    };
                                    if ok {
                                        let du = create_data_url(
                                            &asset.media_type,
                                            &asset.charset,
                                            &asset.data,
                                            resolved.fragment(),
                                        );
                                        dom.set_attr(node, "href", Some(&du));
                                    }
                                    dom.remove_attr(node, "integrity");
                                }
                                Err(_) => {
                                    if is_http_url(&resolved) {
                                        dom.set_attr(node, "href", Some(resolved.as_str()));
                                    } else {
                                        dom.remove_attr(node, "href");
                                    }
                                }
                            }
                        }
                    }
                    LinkKind::Removable => {
                        dom.remove_attr(node, "rel");
                    }
                    LinkKind::Other => {
                        if let Some(href) = dom.get_attr(node, "href") {
                            if !href.is_empty() {
                                self.resolve_href_attr(dom, node, "href");
                            }
                        }
                    }
                }
            }
            "base" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    let resolved = resolve_url(&self.base_url, &href);
                    if is_http_url(&resolved) {
                        dom.set_attr(node, "href", Some(resolved.as_str()));
                    }
                }
            }
            "body" => {
                if let Some(bg) = dom.get_attr(node, "background") {
                    if opts.no_images {
                        dom.remove_attr(node, "background");
                    } else if !bg.is_empty() {
                        dom.remove_attr(node, "background");
                        match self.fetch_data_url(&bg, true) {
                            Fetched::Embedded(u) | Fetched::Absolute(u) => {
                                dom.set_attr(node, "background", Some(&u))
                            }
                            Fetched::Failed => {}
                        }
                    }
                }
            }
            "img" => {
                if opts.no_images {
                    if dom.has_attr(node, "src") {
                        dom.set_attr(node, "src", Some(EMPTY_IMAGE_DATA_URL));
                    }
                    if let Some(srcset) = dom.get_attr(node, "srcset") {
                        if !srcset.is_empty() {
                            let s = self.process_srcset(&srcset);
                            dom.set_attr(node, "srcset", Some(&s));
                        }
                    }
                } else {
                    let src = dom.get_attr(node, "src");
                    match src {
                        Some(s) if !s.is_empty() => {
                            self.embed_attr(dom, node, "src", &s);
                        }
                        _ => {
                            dom.set_attr(node, "src", Some(""));
                        }
                    }
                    if let Some(srcset) = dom.get_attr(node, "srcset") {
                        if !srcset.is_empty() {
                            let s = self.process_srcset(&srcset);
                            dom.set_attr(node, "srcset", Some(&s));
                        }
                    }
                }
            }
            "input" => {
                let is_image = dom
                    .get_attr(node, "type")
                    .map_or(false, |t| t.eq_ignore_ascii_case("image"));
                if is_image {
                    if let Some(src) = dom.get_attr(node, "src") {
                        if opts.no_images {
                            dom.set_attr(node, "src", Some(EMPTY_IMAGE_DATA_URL));
                        } else if !src.is_empty() {
                            self.embed_attr(dom, node, "src", &src);
                        }
                    }
                }
            }
            "svg" => {
                if opts.no_images {
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                }
            }
            "image" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    if opts.no_images {
                        dom.remove_attr(node, "href");
                    } else if !href.is_empty() {
                        self.embed_attr(dom, node, "href", &href);
                    }
                }
            }
            "use" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    if opts.no_images {
                        dom.remove_attr(node, "href");
                    } else {
                        self.process_use(dom, node, &href);
                    }
                }
            }
            "source" => {
                let parent_name = dom
                    .parent(node)
                    .and_then(|p| dom.local_name(p).map(|s| s.to_string()))
                    .unwrap_or_default();
                match parent_name.as_str() {
                    "audio" => {
                        if let Some(src) = dom.get_attr(node, "src") {
                            if opts.no_audio {
                                dom.remove_attr(node, "src");
                            } else if !src.is_empty() {
                                self.embed_attr(dom, node, "src", &src);
                            }
                        }
                    }
                    "video" => {
                        if let Some(src) = dom.get_attr(node, "src") {
                            if opts.no_video {
                                dom.remove_attr(node, "src");
                            } else if !src.is_empty() {
                                self.embed_attr(dom, node, "src", &src);
                            }
                        }
                    }
                    "picture" => {
                        if let Some(srcset) = dom.get_attr(node, "srcset") {
                            if opts.no_images {
                                dom.set_attr(node, "srcset", Some(EMPTY_IMAGE_DATA_URL));
                            } else if !srcset.is_empty() {
                                let s = self.process_srcset(&srcset);
                                dom.set_attr(node, "srcset", Some(&s));
                            }
                        }
                    }
                    _ => {}
                }
            }
            "audio" => {
                if let Some(src) = dom.get_attr(node, "src") {
                    if opts.no_audio {
                        dom.remove_attr(node, "src");
                    } else if !src.is_empty() {
                        self.embed_attr(dom, node, "src", &src);
                    }
                }
            }
            "video" => {
                if let Some(src) = dom.get_attr(node, "src") {
                    if opts.no_video {
                        dom.remove_attr(node, "src");
                    } else if !src.is_empty() {
                        self.embed_attr(dom, node, "src", &src);
                    }
                }
                if let Some(poster) = dom.get_attr(node, "poster") {
                    if opts.no_images {
                        dom.set_attr(node, "poster", Some(EMPTY_IMAGE_DATA_URL));
                    } else if !poster.is_empty() {
                        self.embed_attr(dom, node, "poster", &poster);
                    }
                }
            }
            "iframe" | "frame" => {
                if let Some(src) = dom.get_attr(node, "src") {
                    if opts.no_frames {
                        dom.set_attr(node, "src", Some(""));
                    } else if !src.is_empty() {
                        let resolved = resolve_url(&self.base_url, &src);
                        let parent = self.document_url.clone();
                        match self.session.retrieve(&parent, &resolved) {
                            Ok(asset) => {
                                let enc = document::pick_encoding(&asset.charset, &asset.final_url);
                                let text = crate::encoding::decode(&enc, &asset.data);
                                let mut sub = parse_document(&text);
                                let sub_base = match document::get_base_href(&sub) {
                                    Some(h) => resolve_url(&asset.final_url, &h),
                                    None => asset.final_url.clone(),
                                };
                                {
                                    let mut w = Walker {
                                        session: self.session,
                                        document_url: asset.final_url.clone(),
                                        base_url: sub_base,
                                    };
                                    let root = sub.document;
                                    w.walk(&mut sub, root);
                                }
                                let html = serializer::serialize_document(&sub);
                                let du = create_data_url(
                                    &asset.media_type,
                                    &asset.charset,
                                    html.as_bytes(),
                                    None,
                                );
                                dom.set_attr(node, "src", Some(&du));
                            }
                            Err(_) => {
                                if is_http_url(&resolved) {
                                    dom.set_attr(node, "src", Some(resolved.as_str()));
                                } else {
                                    dom.remove_attr(node, "src");
                                }
                            }
                        }
                    }
                }
            }
            "a" | "area" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    if opts.no_js && href.trim().starts_with("javascript:") {
                        dom.set_attr(node, "href", Some("javascript:;"));
                    } else {
                        self.resolve_href_attr(dom, node, "href");
                    }
                }
            }
            "form" => {
                self.resolve_href_attr(dom, node, "action");
            }
            "script" => {
                if opts.no_js {
                    dom.remove_attr(node, "src");
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                } else if let Some(src) = dom.get_attr(node, "src") {
                    if !src.is_empty() {
                        let resolved = resolve_url(&self.base_url, &src);
                        let parent = self.document_url.clone();
                        match self.session.retrieve(&parent, &resolved) {
                            Ok(asset) => {
                                let integrity = dom.get_attr(node, "integrity");
                                let ok = match &integrity {
                                    Some(i) if !i.is_empty() => Self::check_integrity(&asset.data, i),
                                    _ => true,
                                };
                                if ok {
                                    let script_type = dom.get_attr(node, "type");
                                    match script_type.as_deref() {
                                        None | Some("text/javascript") | Some("application/javascript") => {
                                            dom.remove_attr(node, "src");
                                            let text = String::from_utf8_lossy(&asset.data).into_owned();
                                            dom.append_text(node, &text);
                                        }
                                        Some(t) => {
                                            let mt = if t.is_empty() {
                                                asset.media_type.clone()
                                            } else {
                                                t.to_string()
                                            };
                                            let du = create_data_url(&mt, &asset.charset, &asset.data, None);
                                            dom.set_attr(node, "src", Some(&du));
                                        }
                                    }
                                }
                                dom.remove_attr(node, "integrity");
                            }
                            Err(_) => {
                                if is_http_url(&resolved) {
                                    dom.set_attr(node, "src", Some(resolved.as_str()));
                                } else {
                                    dom.remove_attr(node, "src");
                                }
                            }
                        }
                    }
                }
            }
            "style" => {
                if opts.no_css {
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                } else {
                    let text = dom.text_content(node);
                    let processed = css::process_css(
                        self.session,
                        &text,
                        &self.document_url.clone(),
                        &self.base_url.clone(),
                    );
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                    let t = dom.new_text(&processed);
                    dom.append(node, t);
                }
            }
            "noscript" => {
                self.process_noscript(dom, node);
            }
            _ => {}
        }

        // style attribute
        if let Some(style) = dom.get_attr(node, "style") {
            if opts.no_css {
                dom.remove_attr(node, "style");
            } else {
                let processed = css::process_css(
                    self.session,
                    &style,
                    &self.document_url.clone(),
                    &self.base_url.clone(),
                );
                dom.set_attr(node, "style", Some(&processed));
            }
        }
    }

    fn process_noscript(&mut self, dom: &mut Dom, node: NodeId) {
        let text = dom.text_content(node);
        let mut sub = parse_document(&text);
        let body = match sub.body_element() {
            Some(b) => b,
            None => return,
        };
        {
            let mut w = Walker {
                session: self.session,
                document_url: self.document_url.clone(),
                base_url: self.base_url.clone(),
            };
            for c in sub.children(body) {
                w.walk(&mut sub, c);
            }
        }
        // remove existing children
        for c in dom.children(node) {
            dom.detach(c);
        }
        if self.session.options.unwrap_noscript {
            let parent = match dom.parent(node) {
                Some(p) => p,
                None => return,
            };
            let start = dom.new_comment("noscript");
            let end = dom.new_comment("/noscript");
            dom.insert_before(parent, start, Some(node));
            for c in sub.children(body) {
                let imported = dom.import_subtree(&sub, c);
                dom.insert_before(parent, imported, Some(node));
            }
            dom.insert_before(parent, end, Some(node));
            dom.detach(node);
        } else {
            let html = serializer::serialize_children(&sub, body, true);
            let t = dom.new_text(&html);
            dom.append(node, t);
        }
    }

    fn process_use(&mut self, dom: &mut Dom, node: NodeId, href: &str) {
        let resolved = resolve_url(&self.base_url, href);
        let parent = self.document_url.clone();
        match self.session.retrieve(&parent, &resolved) {
            Ok(asset) => {
                if asset.media_type.eq_ignore_ascii_case("image/svg+xml") {
                    let enc = document::pick_encoding(&asset.charset, &asset.final_url);
                    let text = crate::encoding::decode(&enc, &asset.data);
                    let mut sub = parse_document(&text);
                    {
                        let mut w = Walker {
                            session: self.session,
                            document_url: asset.final_url.clone(),
                            base_url: asset.final_url.clone(),
                        };
                        let root = sub.document;
                        w.walk(&mut sub, root);
                    }
                    let body = sub.body_element();
                    let svgs: Vec<NodeId> = match body {
                        Some(b) => sub
                            .children(b)
                            .into_iter()
                            .filter(|&c| sub.is_named(c, "svg"))
                            .collect(),
                        None => Vec::new(),
                    };
                    match resolved.fragment() {
                        Some(frag) => {
                            let frag = frag.to_string();
                            let mut found: Option<NodeId> = None;
                            'outer: for svg in &svgs {
                                for c in sub.children(*svg) {
                                    if sub.is_named(c, "symbol") && sub.get_attr(c, "id").as_deref() == Some(frag.as_str()) {
                                        found = Some(c);
                                        break 'outer;
                                    }
                                    if sub.is_named(c, "defs") {
                                        for d in sub.children(c) {
                                            if sub.is_named(d, "symbol")
                                                && sub.get_attr(d, "id").as_deref() == Some(frag.as_str())
                                            {
                                                found = Some(d);
                                                break 'outer;
                                            }
                                        }
                                    }
                                }
                            }
                            match found {
                                Some(sym) => {
                                    let new_sym = document::create_element(dom, "symbol", &[("id", &frag)]);
                                    for c in sub.children(sym) {
                                        let imported = dom.import_subtree(&sub, c);
                                        dom.append(new_sym, imported);
                                    }
                                    dom.append(node, new_sym);
                                    dom.set_attr(node, "href", Some(&format!("#{}", frag)));
                                }
                                None => {
                                    let new_sym = document::create_element(dom, "symbol", &[]);
                                    dom.append(node, new_sym);
                                }
                            }
                        }
                        None => {
                            if let Some(svg) = svgs.first() {
                                for c in sub.children(*svg) {
                                    let imported = dom.import_subtree(&sub, c);
                                    dom.append(node, imported);
                                }
                            }
                        }
                    }
                } else {
                    let du = create_data_url(&asset.media_type, &asset.charset, &asset.data, None);
                    dom.set_attr(node, "href", Some(&du));
                }
            }
            Err(_) => {
                if is_http_url(&resolved) {
                    dom.set_attr(node, "href", Some(resolved.as_str()));
                } else {
                    dom.remove_attr(node, "href");
                }
            }
        }
    }
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/walk.rs <<'EOF'
//! DOM walker: embeds assets and applies options.

use url::Url;

use crate::css;
use crate::document;
use crate::html::*;
use crate::session::Session;
use crate::utils::*;

#[derive(PartialEq, Debug)]
pub enum LinkKind {
    Stylesheet,
    Icon,
    Removable,
    Other,
}

pub fn link_rel_kind(rel: &str) -> LinkKind {
    let tokens: Vec<String> = rel.split_whitespace().map(|t| t.to_ascii_lowercase()).collect();
    if tokens.iter().any(|t| t == "stylesheet") {
        LinkKind::Stylesheet
    } else if tokens.iter().any(|t| t == "icon") {
        LinkKind::Icon
    } else if tokens.iter().any(|t| t == "preload" || t == "dns-prefetch") {
        LinkKind::Removable
    } else {
        LinkKind::Other
    }
}

const JS_EVENT_ATTRS: &[&str] = &[
    "onabort", "onafterprint", "onauxclick", "onbeforeprint", "onbeforeunload", "onblur",
    "oncancel", "oncanplay", "oncanplaythrough", "onchange", "onclick", "onclose",
    "oncontextmenu", "oncopy", "oncuechange", "oncut", "ondblclick", "ondrag", "ondragend",
    "ondragenter", "ondragexit", "ondragleave", "ondragover", "ondragstart", "ondrop",
    "ondurationchange", "onemptied", "onended", "onerror", "onfocus", "onformdata",
    "onhashchange", "oninput", "oninvalid", "onkeydown", "onkeypress", "onkeyup",
    "onlanguagechange", "onload", "onloadeddata", "onloadedmetadata", "onloadstart",
    "onmessage", "onmessageerror", "onmousedown", "onmouseenter", "onmouseleave",
    "onmousemove", "onmouseout", "onmouseover", "onmouseup", "onoffline", "ononline",
    "onpagehide", "onpageshow", "onpaste", "onpause", "onplay", "onplaying", "onpopstate",
    "onprogress", "onratechange", "onreset", "onresize", "onrejectionhandled", "onscroll",
    "onsecuritypolicyviolation", "onseeked", "onseeking", "onselect", "onslotchange",
    "onstalled", "onstorage", "onsubmit", "onsuspend", "ontimeupdate", "ontoggle",
    "onunhandledrejection", "onunload", "onvolumechange", "onwaiting", "onwebkitanimationend",
    "onwebkitanimationiteration", "onwebkitanimationstart", "onwebkittransitionend", "onwheel",
];

pub struct Walker<'a> {
    pub session: &'a mut Session,
    pub document_url: Url,
    pub base_url: Url,
}

enum Fetched {
    /// A data URL to embed
    Embedded(String),
    /// Retrieval failed but URL is http(s): use absolute URL
    Absolute(String),
    /// Retrieval failed: remove
    Failed,
}

impl<'a> Walker<'a> {
    pub fn walk(&mut self, dom: &mut Dom, node: NodeId) {
        if dom.is_element(node) {
            self.process_element(dom, node);
        }
        // snapshot children after processing (noscript/use may have changed them)
        let children = dom.children(node);
        for c in children {
            // the node might have been detached (e.g. noscript unwrapped) - still process
            if dom.node(c).parent.is_some() || true {
                self.walk(dom, c);
            }
        }
    }

    fn fetch_data_url(&mut self, href: &str, keep_fragment: bool) -> Fetched {
        let resolved = resolve_url(&self.base_url, href);
        let parent = self.document_url.clone();
        match self.session.retrieve(&parent, &resolved) {
            Ok(asset) => Fetched::Embedded(create_data_url(
                &asset.media_type,
                &asset.charset,
                &asset.data,
                if keep_fragment { resolved.fragment() } else { None },
            )),
            Err(_) => {
                if is_http_url(&resolved) {
                    Fetched::Absolute(resolved.to_string())
                } else {
                    Fetched::Failed
                }
            }
        }
    }

    /// Standard handling for a URL attribute: embed, absolutize, or remove.
    fn embed_attr(&mut self, dom: &mut Dom, node: NodeId, attr: &str, href: &str) {
        match self.fetch_data_url(href, true) {
            Fetched::Embedded(u) | Fetched::Absolute(u) => dom.set_attr(node, attr, Some(&u)),
            Fetched::Failed => dom.remove_attr(node, attr),
        }
    }

    fn process_srcset(&mut self, srcset: &str) -> String {
        let entries = parse_srcset(srcset);
        let mut out = Vec::new();
        for (u, d) in entries {
            let new_u = if self.session.options.no_images {
                EMPTY_IMAGE_DATA_URL.to_string()
            } else {
                match self.fetch_data_url(&u, true) {
                    Fetched::Embedded(x) | Fetched::Absolute(x) => x,
                    Fetched::Failed => EMPTY_IMAGE_DATA_URL.to_string(),
                }
            };
            out.push((new_u, d));
        }
        format_srcset(&out)
    }

    fn resolve_href_attr(&mut self, dom: &mut Dom, node: NodeId, attr: &str) {
        if let Some(value) = dom.get_attr(node, attr) {
            if value.starts_with('#') {
                return;
            }
            if Url::parse(&value).is_ok() {
                return;
            }
            let resolved = resolve_url(&self.base_url, &value);
            dom.set_attr(node, attr, Some(resolved.as_str()));
        }
    }

    fn check_integrity(data: &[u8], integrity: &str) -> bool {
        use sha2::Digest;
        let (algo, hash) = match integrity.find('-') {
            Some(i) => (&integrity[..i], &integrity[i + 1..]),
            None => return false,
        };
        let digest: Vec<u8> = match algo {
            "sha256" => sha2::Sha256::digest(data).to_vec(),
            "sha384" => sha2::Sha384::digest(data).to_vec(),
            "sha512" => sha2::Sha512::digest(data).to_vec(),
            _ => return false,
        };
        use base64::Engine;
        base64::engine::general_purpose::STANDARD.encode(&digest) == hash
    }

    fn process_element(&mut self, dom: &mut Dom, node: NodeId) {
        let name = match dom.local_name(node) {
            Some(n) => n.to_string(),
            None => return,
        };
        let opts = self.session.options.clone();

        // Remove JS event handler attributes
        if opts.no_js {
            if let Some(attrs) = dom.attrs_mut(node) {
                attrs.retain(|a| !JS_EVENT_ATTRS.contains(&a.local.to_ascii_lowercase().as_str()));
            }
        }

        match name.as_str() {
            "meta" => {
                if let Some(he) = dom.get_attr(node, "http-equiv") {
                    if he.eq_ignore_ascii_case("refresh") {
                        dom.remove_attr(node, "http-equiv");
                    }
                }
            }
            "link" => {
                let rel = dom.get_attr(node, "rel").unwrap_or_default();
                match link_rel_kind(&rel) {
                    LinkKind::Stylesheet => {
                        if opts.no_css {
                            dom.remove_attr(node, "href");
                        } else if let Some(href) = dom.get_attr(node, "href") {
                            if !href.is_empty() {
                                let resolved = resolve_url(&self.base_url, &href);
                                let parent = self.document_url.clone();
                                match self.session.retrieve(&parent, &resolved) {
                                    Ok(asset) => {
                                        let integrity = dom.get_attr(node, "integrity");
                                        let ok = match &integrity {
                                            Some(i) if !i.is_empty() => Self::check_integrity(&asset.data, i),
                                            _ => true,
                                        };
                                        if ok {
                                            let processed = css::process_css_asset(
                                                self.session,
                                                &asset.data,
                                                &asset.charset,
                                                &asset.final_url,
                                            );
                                            let du = create_data_url(
                                                &asset.media_type,
                                                &asset.charset,
                                                &processed,
                                                None,
                                            );
                                            dom.set_attr(node, "href", Some(&du));
                                        }
                                        dom.remove_attr(node, "integrity");
                                    }
                                    Err(_) => {
                                        if is_http_url(&resolved) {
                                            dom.set_attr(node, "href", Some(resolved.as_str()));
                                        } else {
                                            dom.remove_attr(node, "href");
                                        }
                                    }
                                }
                            }
                        }
                    }
                    LinkKind::Icon => {
                        let href = dom.get_attr(node, "href");
                        if opts.no_images || href.as_deref() == Some("") {
                            dom.remove_attr(node, "href");
                        } else if let Some(href) = href {
                            let resolved = resolve_url(&self.base_url, &href);
                            let parent = self.document_url.clone();
                            match self.session.retrieve(&parent, &resolved) {
                                Ok(asset) => {
                                    let integrity = dom.get_attr(node, "integrity");
                                    let ok = match &integrity {
                                        Some(i) if !i.is_empty() => Self::check_integrity(&asset.data, i),
                                        _ => true,
                                    };
                                    if ok {
                                        let du = create_data_url(
                                            &asset.media_type,
                                            &asset.charset,
                                            &asset.data,
                                            resolved.fragment(),
                                        );
                                        dom.set_attr(node, "href", Some(&du));
                                    }
                                    dom.remove_attr(node, "integrity");
                                }
                                Err(_) => {
                                    if is_http_url(&resolved) {
                                        dom.set_attr(node, "href", Some(resolved.as_str()));
                                    } else {
                                        dom.remove_attr(node, "href");
                                    }
                                }
                            }
                        }
                    }
                    LinkKind::Removable => {
                        dom.remove_attr(node, "rel");
                    }
                    LinkKind::Other => {
                        if let Some(href) = dom.get_attr(node, "href") {
                            if !href.is_empty() {
                                self.resolve_href_attr(dom, node, "href");
                            }
                        }
                    }
                }
            }
            "base" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    let resolved = resolve_url(&self.base_url, &href);
                    if is_http_url(&resolved) {
                        dom.set_attr(node, "href", Some(resolved.as_str()));
                    }
                }
            }
            "body" => {
                if let Some(bg) = dom.get_attr(node, "background") {
                    if opts.no_images {
                        dom.remove_attr(node, "background");
                    } else if !bg.is_empty() {
                        dom.remove_attr(node, "background");
                        match self.fetch_data_url(&bg, true) {
                            Fetched::Embedded(u) | Fetched::Absolute(u) => {
                                dom.set_attr(node, "background", Some(&u))
                            }
                            Fetched::Failed => {}
                        }
                    }
                }
            }
            "img" => {
                if opts.no_images {
                    if dom.has_attr(node, "src") {
                        dom.set_attr(node, "src", Some(EMPTY_IMAGE_DATA_URL));
                    }
                    if let Some(srcset) = dom.get_attr(node, "srcset") {
                        if !srcset.is_empty() {
                            let s = self.process_srcset(&srcset);
                            dom.set_attr(node, "srcset", Some(&s));
                        }
                    }
                } else {
                    let src = dom.get_attr(node, "src");
                    match src {
                        Some(s) if !s.is_empty() => {
                            self.embed_attr(dom, node, "src", &s);
                        }
                        _ => {
                            dom.set_attr(node, "src", Some(""));
                        }
                    }
                    if let Some(srcset) = dom.get_attr(node, "srcset") {
                        if !srcset.is_empty() {
                            let s = self.process_srcset(&srcset);
                            dom.set_attr(node, "srcset", Some(&s));
                        }
                    }
                }
            }
            "input" => {
                let is_image = dom
                    .get_attr(node, "type")
                    .map_or(false, |t| t.eq_ignore_ascii_case("image"));
                if is_image {
                    if let Some(src) = dom.get_attr(node, "src") {
                        if opts.no_images {
                            dom.set_attr(node, "src", Some(EMPTY_IMAGE_DATA_URL));
                        } else if !src.is_empty() {
                            self.embed_attr(dom, node, "src", &src);
                        }
                    }
                }
            }
            "svg" => {
                if opts.no_images {
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                }
            }
            "image" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    if opts.no_images {
                        dom.remove_attr(node, "href");
                    } else if !href.is_empty() {
                        self.embed_attr(dom, node, "href", &href);
                    }
                }
            }
            "use" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    if opts.no_images {
                        dom.remove_attr(node, "href");
                    } else {
                        self.process_use(dom, node, &href);
                    }
                }
            }
            "source" => {
                let parent_name = dom
                    .parent(node)
                    .and_then(|p| dom.local_name(p).map(|s| s.to_string()))
                    .unwrap_or_default();
                match parent_name.as_str() {
                    "audio" => {
                        if let Some(src) = dom.get_attr(node, "src") {
                            if opts.no_audio {
                                dom.remove_attr(node, "src");
                            } else if !src.is_empty() {
                                self.embed_attr(dom, node, "src", &src);
                            }
                        }
                    }
                    "video" => {
                        if let Some(src) = dom.get_attr(node, "src") {
                            if opts.no_video {
                                dom.remove_attr(node, "src");
                            } else if !src.is_empty() {
                                self.embed_attr(dom, node, "src", &src);
                            }
                        }
                    }
                    "picture" => {
                        if let Some(srcset) = dom.get_attr(node, "srcset") {
                            if opts.no_images {
                                dom.set_attr(node, "srcset", Some(EMPTY_IMAGE_DATA_URL));
                            } else if !srcset.is_empty() {
                                let s = self.process_srcset(&srcset);
                                dom.set_attr(node, "srcset", Some(&s));
                            }
                        }
                    }
                    _ => {}
                }
            }
            "audio" => {
                if let Some(src) = dom.get_attr(node, "src") {
                    if opts.no_audio {
                        dom.remove_attr(node, "src");
                    } else if !src.is_empty() {
                        self.embed_attr(dom, node, "src", &src);
                    }
                }
            }
            "video" => {
                if let Some(src) = dom.get_attr(node, "src") {
                    if opts.no_video {
                        dom.remove_attr(node, "src");
                    } else if !src.is_empty() {
                        self.embed_attr(dom, node, "src", &src);
                    }
                }
                if let Some(poster) = dom.get_attr(node, "poster") {
                    if opts.no_images {
                        dom.set_attr(node, "poster", Some(EMPTY_IMAGE_DATA_URL));
                    } else if !poster.is_empty() {
                        self.embed_attr(dom, node, "poster", &poster);
                    }
                }
            }
            "iframe" | "frame" => {
                if let Some(src) = dom.get_attr(node, "src") {
                    if opts.no_frames {
                        dom.set_attr(node, "src", Some(""));
                    } else if !src.is_empty() {
                        let resolved = resolve_url(&self.base_url, &src);
                        let parent = self.document_url.clone();
                        match self.session.retrieve(&parent, &resolved) {
                            Ok(asset) => {
                                let enc = document::pick_encoding(&asset.charset, &asset.final_url);
                                let text = crate::encoding::decode(&enc, &asset.data);
                                let mut sub = parse_document(&text);
                                let sub_base = match document::get_base_href(&sub) {
                                    Some(h) => resolve_url(&asset.final_url, &h),
                                    None => asset.final_url.clone(),
                                };
                                {
                                    let mut w = Walker {
                                        session: self.session,
                                        document_url: asset.final_url.clone(),
                                        base_url: sub_base,
                                    };
                                    let root = sub.document;
                                    w.walk(&mut sub, root);
                                }
                                let html = serializer::serialize_document(&sub);
                                let du = create_data_url(
                                    &asset.media_type,
                                    &asset.charset,
                                    html.as_bytes(),
                                    None,
                                );
                                dom.set_attr(node, "src", Some(&du));
                            }
                            Err(_) => {
                                if is_http_url(&resolved) {
                                    dom.set_attr(node, "src", Some(resolved.as_str()));
                                } else {
                                    dom.remove_attr(node, "src");
                                }
                            }
                        }
                    }
                }
            }
            "a" | "area" => {
                if let Some(href) = dom.get_attr(node, "href") {
                    if opts.no_js && href.trim().starts_with("javascript:") {
                        dom.set_attr(node, "href", Some("javascript:;"));
                    } else {
                        self.resolve_href_attr(dom, node, "href");
                    }
                }
            }
            "form" => {
                self.resolve_href_attr(dom, node, "action");
            }
            "script" => {
                if opts.no_js {
                    dom.remove_attr(node, "src");
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                } else if let Some(src) = dom.get_attr(node, "src") {
                    if !src.is_empty() {
                        let resolved = resolve_url(&self.base_url, &src);
                        let parent = self.document_url.clone();
                        match self.session.retrieve(&parent, &resolved) {
                            Ok(asset) => {
                                let integrity = dom.get_attr(node, "integrity");
                                let ok = match &integrity {
                                    Some(i) if !i.is_empty() => Self::check_integrity(&asset.data, i),
                                    _ => true,
                                };
                                if ok {
                                    let script_type = dom.get_attr(node, "type");
                                    match script_type.as_deref() {
                                        None | Some("text/javascript") | Some("application/javascript") => {
                                            dom.remove_attr(node, "src");
                                            let text = String::from_utf8_lossy(&asset.data).into_owned();
                                            dom.append_text(node, &text);
                                        }
                                        Some(t) => {
                                            let mt = if t.is_empty() {
                                                asset.media_type.clone()
                                            } else {
                                                t.to_string()
                                            };
                                            let du = create_data_url(&mt, &asset.charset, &asset.data, None);
                                            dom.set_attr(node, "src", Some(&du));
                                        }
                                    }
                                }
                                dom.remove_attr(node, "integrity");
                            }
                            Err(_) => {
                                if is_http_url(&resolved) {
                                    dom.set_attr(node, "src", Some(resolved.as_str()));
                                } else {
                                    dom.remove_attr(node, "src");
                                }
                            }
                        }
                    }
                }
            }
            "style" => {
                if opts.no_css {
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                } else {
                    let text = dom.text_content(node);
                    let processed = css::process_css(
                        self.session,
                        &text,
                        &self.document_url.clone(),
                        &self.base_url.clone(),
                    );
                    for c in dom.children(node) {
                        dom.detach(c);
                    }
                    let t = dom.new_text(&processed);
                    dom.append(node, t);
                }
            }
            "noscript" => {
                self.process_noscript(dom, node);
            }
            _ => {}
        }

        // style attribute
        if let Some(style) = dom.get_attr(node, "style") {
            if opts.no_css {
                dom.remove_attr(node, "style");
            } else {
                let processed = css::process_css(
                    self.session,
                    &style,
                    &self.document_url.clone(),
                    &self.base_url.clone(),
                );
                dom.set_attr(node, "style", Some(&processed));
            }
        }
    }

    fn process_noscript(&mut self, dom: &mut Dom, node: NodeId) {
        let text = dom.text_content(node);
        let mut sub = parse_document(&text);
        let body = match sub.body_element() {
            Some(b) => b,
            None => return,
        };
        {
            let mut w = Walker {
                session: self.session,
                document_url: self.document_url.clone(),
                base_url: self.base_url.clone(),
            };
            for c in sub.children(body) {
                w.walk(&mut sub, c);
            }
        }
        // remove existing children
        for c in dom.children(node) {
            dom.detach(c);
        }
        if self.session.options.unwrap_noscript {
            let parent = match dom.parent(node) {
                Some(p) => p,
                None => return,
            };
            let start = dom.new_comment("noscript");
            let end = dom.new_comment("/noscript");
            dom.insert_before(parent, start, Some(node));
            for c in sub.children(body) {
                let imported = dom.import_subtree(&sub, c);
                dom.insert_before(parent, imported, Some(node));
            }
            dom.insert_before(parent, end, Some(node));
            dom.detach(node);
        } else {
            let html = serializer::serialize_children(&sub, body, true);
            let t = dom.new_text(&html);
            dom.append(node, t);
        }
    }

    fn process_use(&mut self, dom: &mut Dom, node: NodeId, href: &str) {
        let resolved = resolve_url(&self.base_url, href);
        let parent = self.document_url.clone();
        match self.session.retrieve(&parent, &resolved) {
            Ok(asset) => {
                if asset.media_type.eq_ignore_ascii_case("image/svg+xml") {
                    let enc = document::pick_encoding(&asset.charset, &asset.final_url);
                    let text = crate::encoding::decode(&enc, &asset.data);
                    let mut sub = parse_document(&text);
                    {
                        let mut w = Walker {
                            session: self.session,
                            document_url: asset.final_url.clone(),
                            base_url: asset.final_url.clone(),
                        };
                        let root = sub.document;
                        w.walk(&mut sub, root);
                    }
                    let body = sub.body_element();
                    let svgs: Vec<NodeId> = match body {
                        Some(b) => sub
                            .children(b)
                            .into_iter()
                            .filter(|&c| sub.is_named(c, "svg"))
                            .collect(),
                        None => Vec::new(),
                    };
                    match resolved.fragment() {
                        Some(frag) => {
                            let frag = frag.to_string();
                            let mut found: Option<NodeId> = None;
                            'outer: for svg in &svgs {
                                for c in sub.children(*svg) {
                                    if sub.is_named(c, "symbol") && sub.get_attr(c, "id").as_deref() == Some(frag.as_str()) {
                                        found = Some(c);
                                        break 'outer;
                                    }
                                    if sub.is_named(c, "defs") {
                                        for d in sub.children(c) {
                                            if sub.is_named(d, "symbol")
                                                && sub.get_attr(d, "id").as_deref() == Some(frag.as_str())
                                            {
                                                found = Some(d);
                                                break 'outer;
                                            }
                                        }
                                    }
                                }
                            }
                            match found {
                                Some(sym) => {
                                    let new_sym = document::create_element(dom, "symbol", &[("id", &frag)]);
                                    for c in sub.children(sym) {
                                        let imported = dom.import_subtree(&sub, c);
                                        dom.append(new_sym, imported);
                                    }
                                    dom.append(node, new_sym);
                                    dom.set_attr(node, "href", Some(&format!("#{}", frag)));
                                }
                                None => {
                                    let new_sym = document::create_element(dom, "symbol", &[]);
                                    dom.append(node, new_sym);
                                }
                            }
                        }
                        None => {
                            if let Some(svg) = svgs.first() {
                                for c in sub.children(*svg) {
                                    let imported = dom.import_subtree(&sub, c);
                                    dom.append(node, imported);
                                }
                            }
                        }
                    }
                } else {
                    let du = create_data_url(&asset.media_type, &asset.charset, &asset.data, None);
                    dom.set_attr(node, "href", Some(&du));
                }
            }
            Err(_) => {
                if is_http_url(&resolved) {
                    dom.set_attr(node, "href", Some(resolved.as_str()));
                } else {
                    dom.remove_attr(node, "href");
                }
            }
        }
    }
}
