fn eprint_unless_quiet(options: &Options, msg: &str) {
    if !options.quiet {
        eprintln!("{}", msg);
    }
}

fn run(options: Options) -> i32 {
    // Validate encoding
    if let Some(enc) = &options.encoding {
        if encoding::for_label(enc).is_none() {
            eprint_unless_quiet(&options, &format!("Error: unknown encoding \"{}\"", enc));
            return 1;
        }
    }

    // Cookies
    let mut cookies = Vec::new();
    if let Some(cf) = &options.cookie_file {
        match std::fs::read_to_string(cf) {
            Ok(content) => match http::parse_cookie_file(&content) {
                Ok(c) => cookies = c,
                Err(_) => {
                    eprint_unless_quiet(
                        &options,
                        &format!("could not parse specified cookie file \"{}\"", cf),
                    );
                    return 1;
                }
            },
            Err(_) => {
                eprint_unless_quiet(
                    &options,
                    &format!("could not read specified cookie file \"{}\"", cf),
                );
                return 1;
            }
        }
    }

    let target = options.target.clone();
    if target.is_empty() {
        eprint_unless_quiet(&options, "Error: no target specified");
        return 1;
    }

    let client = http::HttpClient {
        timeout: options.timeout,
        user_agent: options
            .user_agent
            .clone()
            .unwrap_or_else(|| DEFAULT_USER_AGENT.to_string()),
        insecure: options.insecure,
        cookies,
    };
    let mut session = Session::new(options.clone(), client);

    // Determine target URL and retrieve the document
    let from_stdin = target == "-";
    let (data, mut document_url, media_type, charset): (Vec<u8>, Url, String, String);
    if from_stdin {
        let mut buf = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut buf);
        use base64::Engine;
        let du = format!(
            "data:text/html;base64,{}",
            base64::engine::general_purpose::STANDARD.encode(&buf)
        );
        document_url = Url::parse(&du).unwrap_or_else(|_| utils::empty_url());
        data = buf;
        media_type = "text/html".to_string();
        charset = String::new();
    } else {
        let target_url: Url = match Url::parse(&target) {
            Ok(u) => {
                if !matches!(u.scheme(), "http" | "https" | "file" | "data") {
                    eprint_unless_quiet(
                        &options,
                        &format!("Error: unsupported target URL scheme \"{}\"", u.scheme()),
                    );
                    return 1;
                }
                u
            }
            Err(_) => {
                let p = Path::new(&target);
                if p.exists() {
                    if !p.is_file() {
                        eprint_unless_quiet(
                            &options,
                            &format!("Error: local target \"{}\" is not a file", target),
                        );
                        return 1;
                    }
                    let abs = std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
                    match Url::from_file_path(&abs) {
                        Ok(u) => u,
                        Err(_) => {
                            eprint_unless_quiet(&options, "Error: could not retrieve target document");
                            return 1;
                        }
                    }
                } else {
                    match Url::parse(&format!("http://{}", target)) {
                        Ok(u) => u,
                        Err(_) => {
                            eprint_unless_quiet(&options, "Error: could not retrieve target document");
                            return 1;
                        }
                    }
                }
            }
        };
        match session.retrieve(&target_url.clone(), &target_url) {
            Ok(asset) => {
                data = asset.data;
                document_url = asset.final_url;
                media_type = asset.media_type;
                charset = asset.charset;
            }
            Err(_) => {
                eprint_unless_quiet(&options, "Error: could not retrieve target document");
                return 1;
            }
        }
    }

    let is_local_source = from_stdin || document_url.scheme() == "data" || document_url.scheme() == "file";

    // Non-HTML target: output raw data
    if !utils::is_html_media_type(&media_type) {
        return write_output(&options, &data, None);
    }

    // Decode and parse
    let initial_enc = if charset.trim().is_empty() {
        document::default_encoding_for(&document_url, from_stdin)
    } else {
        encoding::for_label(&charset).unwrap_or(encoding::UTF_8)
    };
    let (mut dom, doc_enc) = document::html_to_dom(&data, initial_enc);

    // Base URL
    let mut base_url = document_url.clone();
    if let Some(b) = &options.base_url {
        let candidate = match Url::parse(b) {
            Ok(u) => Some(u),
            Err(_) => {
                let p = Path::new(b);
                if p.exists() {
                    std::fs::canonicalize(p)
                        .ok()
                        .and_then(|abs| Url::from_file_path(abs).ok())
                } else {
                    None
                }
            }
        };
        if let Some(c) = candidate {
            if !(c.scheme() == "file" && document_url.scheme() != "file") {
                base_url = c;
            }
        }
    } else if let Some(href) = document::get_base_href(&dom) {
        base_url = utils::resolve_url(&document_url, &href);
    }

    // Walk
    {
        let mut w = walk::Walker {
            session: &mut session,
            document_url: document_url.clone(),
            base_url: base_url.clone(),
        };
        let root = dom.document;
        w.walk(&mut dom, root);
    }

    // Base element
    if let Some(b) = &options.base_url {
        document::set_base_url(&mut dom, b);
    }

    // Favicon
    if utils::is_http_url(&document_url) && !options.no_images && !document::head_has_favicon(&dom) {
        let favicon_url = utils::resolve_url(&base_url, "/favicon.ico");
        let parent = document_url.clone();
        if let Ok(asset) = session.retrieve(&parent, &favicon_url) {
            // monolith re-parses the document at this point
            let html = html::serializer::serialize_document(&dom);
            dom = html::parse_document(&html);
            let du = utils::create_data_url(&asset.media_type, &asset.charset, &asset.data, None);
            document::add_favicon(&mut dom, &du);
        }
    }

    // Robots
    document::add_robots_meta(&mut dom);

    // CSP
    let csp = document::csp_content(&options);
    if !csp.is_empty() {
        document::add_csp_meta(&mut dom, &csp);
    }

    // Charset meta
    if let Some(enc_label) = &options.encoding {
        document::set_charset_meta(&mut dom, enc_label);
    }

    // Serialize
    let html = html::serializer::serialize_document(&dom);
    let output_enc = match &options.encoding {
        Some(l) => encoding::for_label(l).unwrap_or(encoding::UTF_8),
        None => doc_enc,
    };
    let mut bytes = encoding::encode(&output_enc, &html);

    if !options.no_metadata && !from_stdin {
        let source = if is_local_source {
            "local source".to_string()
        } else {
            document_url.to_string()
        };
        let comment = format!(
            "<!-- Saved from {} at {} using monolith v2.11.0 -->\n",
            source,
            now_timestamp()
        );
        let mut c = encoding::encode(&output_enc, &comment);
        c.extend_from_slice(&bytes);
        bytes = c;
    }

    let title = document::get_title(&dom);

    if options.mhtml {
        let mut out: Vec<u8> = Vec::new();
        out.extend_from_slice(b"MIME-Version: 1.0\r\n");
        out.extend_from_slice(
            b"Content-Type: multipart/related; boundary=\"----=_NextPart_000_0000\"\r\n\r\n",
        );
        out.extend_from_slice(b"------=_NextPart_000_0000\r\n");
        out.extend_from_slice(b"Content-Type: text/html; charset=\"utf-8\"\r\n");
        out.extend_from_slice(b"Content-Location: http://example.com/\r\n\r\n");
        out.extend_from_slice(&bytes);
        out.extend_from_slice(b"\r\n------=_NextPart_000_0000--\r\n");
        return write_output(&options, &out, title.as_deref());
    }

    bytes.push(b'\n');
    write_output(&options, &bytes, title.as_deref())
}

fn write_output(options: &Options, data: &[u8], title: Option<&str>) -> i32 {
    if options.output.is_empty() || options.output == "-" {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(data);
        let _ = lock.flush();
        return 0;
    }
    let mut filename = options.output.clone();
    if filename.contains("%timestamp%") {
        filename = filename.replace("%timestamp%", &now_timestamp().replace(':', "_"));
    }
    if filename.contains("%title%") {
        filename = filename.replace("%title%", &sanitize_title(title.unwrap_or("")));
    }
    match std::fs::File::create(&filename) {
        Ok(mut f) => {
            let _ = f.write_all(data);
            0
        }
        Err(e) => {
            eprint_unless_quiet(options, &format!("Error: {}", e));
            1
        }
    }
}
