new = '''fn iconv_decode(name: &str, bytes: &[u8]) -> String {
    let cd = match iconv_open("UTF-8", name) {
        Some(cd) => cd,
        None => return String::from_utf8_lossy(bytes).into_owned(),
    };
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len() * 2 + 16);
    let mut inbuf = bytes.to_vec();
    let base_ptr = inbuf.as_mut_ptr();
    let mut in_ptr = base_ptr as *mut libc::c_char;
    let mut in_left = inbuf.len();
    let mut outbuf = vec![0u8; 8192];
    loop {
        let mut out_ptr = outbuf.as_mut_ptr() as *mut libc::c_char;
        let mut out_left = outbuf.len();
        let r = unsafe {
            libc::iconv(
                cd,
                &mut in_ptr,
                &mut in_left,
                &mut out_ptr,
                &mut out_left,
            )
        };
        let produced = outbuf.len() - out_left;
        out.extend_from_slice(&outbuf[..produced]);
        if r as isize == -1 {
            let errno = unsafe { *libc::__errno_location() };
            if errno == libc::E2BIG {
                continue;
            } else if errno == libc::EILSEQ {
                let consumed = inbuf.len() - in_left;
                let rest = &bytes[consumed..];
                let b0 = rest.first().copied().unwrap_or(0);
                let b1 = rest.get(1).copied();
                // WHATWG-style handling of a few special single bytes
                let (repl, skip): (&str, usize) = if b0 == 0x80 && name == "CP932" {
                    ("\\u{80}", 1)
                } else if b0 == 0x80 && (name == "GBK" || name == "GB18030") {
                    ("\\u{20ac}", 1)
                } else if b0 >= 0x81 && matches!(b1, Some(b) if b >= 0x80) {
                    // lead byte followed by a non-ASCII trail: both consumed, one replacement
                    ("\\u{fffd}", 2)
                } else {
                    ("\\u{fffd}", 1)
                };
                out.extend_from_slice(repl.as_bytes());
                let skip = skip.min(in_left);
                in_ptr = unsafe { in_ptr.add(skip) };
                in_left -= skip;
                continue;
            } else if errno == libc::EINVAL {
                // incomplete sequence at end
                out.extend_from_slice("\\u{fffd}".as_bytes());
                break;
            } else {
                break;
            }
        } else {
            break;
        }
    }
    unsafe {
        libc::iconv_close(cd);
    }
    String::from_utf8_lossy(&out).into_owned()
}

'''
